def walk_battle_to(battle, target):
    """Move a battle to `target` along LEGAL transitions, for tests that need a
    later state than the flow they set up actually reaches.

    T19, 2026-08-15: accepting a challenge now opens a 48-hour preparation
    window, so an accepted battle is SCHEDULED where it used to be
    MENU_LOCKED. Several tests wrote the later status in one hop, which was
    legal from MENU_LOCKED and is not from SCHEDULED - T12's transition matrix
    and the trigger in migration 0094 refuse it, correctly.

    The path is taken from ALLOWED_BATTLE_TRANSITIONS itself rather than
    hand-listed here, so a test can never walk a route the product forbids.
    """
    from collections import deque

    from .state_machine import ALLOWED_BATTLE_TRANSITIONS

    start = Battle.objects.values_list("status", flat=True).get(pk=battle.pk)
    if start == target:
        battle.status = target
        return battle

    queue, seen = deque([(start, [])]), {start}
    while queue:
        status, path = queue.popleft()
        for nxt in ALLOWED_BATTLE_TRANSITIONS.get(status, set()):
            if nxt in seen:
                continue
            if nxt == target:
                for step in path + [nxt]:
                    Battle.objects.filter(pk=battle.pk).update(status=step)
                battle.status = target
                return battle
            seen.add(nxt)
            queue.append((nxt, path + [nxt]))
    raise AssertionError(f"No legal transition path from {start} to {target}")


class ChefBattleServiceTests(TestCase):
    def setUp(self):
        User = get_user_model()
        self.user_a = User.objects.create_user(username="chef-a", password="pw")
        self.user_b = User.objects.create_user(username="chef-b", password="pw")
        self.voter = User.objects.create_user(username="voter", password="pw")
        self.chef_a = RecipeAuthor.objects.create(user=self.user_a, name="Chef A", slug="chef-a")
        self.chef_b = RecipeAuthor.objects.create(user=self.user_b, name="Chef B", slug="chef-b")

    def _challenge(self):
        return BattleChallenge.objects.create(
            challenger=self.chef_a,
            opponent=self.chef_b,
            theme="Best Modern Irish Lamb Dish",
            expires_at=timezone.now() + timezone.timedelta(hours=24),
        )

    def test_accept_challenge_creates_active_battle(self):
        challenge = self._challenge()

        battle = accept_challenge(challenge)
        challenge.refresh_from_db()

        self.assertEqual(challenge.status, BattleChallenge.Status.ACCEPTED)
        # T19, Owner 2026-08-15: acceptance opens 48 hours of preparation, so
        # the battle is SCHEDULED. It used to be MENU_LOCKED, because a
        # challenge with no proposed start began immediately.
        self.assertEqual(battle.status, Battle.Status.SCHEDULED)
        self.assertEqual(battle.challenger, self.chef_a)
        self.assertEqual(battle.opponent, self.chef_b)
        self.assertEqual(battle.events.count(), 2)

    def test_accept_challenge_attaches_challenger_recipe_without_submitting_dish(self):
        from recipes.models import Recipe
        recipe = Recipe.objects.create(
            title="Challenger dish", slug="challenger-dish", author=self.chef_a,
            ingredients="lamb\npotatoes", method="Cook.", status=Recipe.Status.APPROVED,
        )
        challenge = self._challenge()
        challenge.theme_recipe = recipe
        challenge.save(update_fields=["theme_recipe"])

        battle = accept_challenge(challenge)
        entry = BattleEntry.objects.get(battle=battle, author=self.chef_a)

        self.assertEqual(entry.recipe, recipe)
        self.assertIsNone(entry.dish_submitted_at)

    def test_accept_challenge_leaves_off_a_theme_recipe_that_lost_approval(self):
        """A challenge stands for twelve hours and moderation can act inside
        that window, so the recipe is re-checked when the battle is made."""
        from recipes.models import Recipe
        recipe = Recipe.objects.create(
            title="Withdrawn dish", slug="withdrawn-dish", author=self.chef_a,
            ingredients="lamb", method="Cook.", status=Recipe.Status.APPROVED,
        )
        challenge = self._challenge()
        challenge.theme_recipe = recipe
        challenge.save(update_fields=["theme_recipe"])

        recipe.status = Recipe.Status.REJECTED
        recipe.save(update_fields=["status"])

        battle = accept_challenge(challenge)

        self.assertFalse(
            BattleEntry.objects.filter(battle=battle, author=self.chef_a).exists(),
            "a rejected recipe must not become a battle entry the audience cannot open",
        )

    def test_challenge_form_offers_only_approved_recipes(self):
        from recipes.models import Recipe
        from .forms import BattleChallengeForm
        approved = Recipe.objects.create(
            title="Ready dish", slug="ready-dish", author=self.chef_a,
            ingredients="lamb", method="Cook.", status=Recipe.Status.APPROVED,
        )
        for tag, status in (
            ("draft", Recipe.Status.DRAFT),
            ("pending", Recipe.Status.PENDING),
            ("rejected", Recipe.Status.REJECTED),
        ):
            Recipe.objects.create(
                title=f"Unready {tag}", slug=f"unready-{tag}", author=self.chef_a,
                ingredients="lamb", method="Cook.", status=status,
            )

        offered = list(BattleChallengeForm(challenger=self.chef_a).fields["theme_recipe"].queryset)

        self.assertEqual(offered, [approved])

    def test_recipe_attach_form_offers_only_approved_recipes(self):
        from recipes.models import Recipe
        from .forms import BattleRecipeAttachForm
        approved = Recipe.objects.create(
            title="Attachable dish", slug="attachable-dish", author=self.chef_a,
            ingredients="lamb", method="Cook.", status=Recipe.Status.APPROVED,
        )
        Recipe.objects.create(
            title="Draft dish", slug="draft-dish", author=self.chef_a,
            ingredients="lamb", method="Cook.", status=Recipe.Status.DRAFT,
        )

        offered = list(BattleRecipeAttachForm(author=self.chef_a).fields["recipe"].queryset)

        self.assertEqual(offered, [approved])

    def test_refuse_challenge_records_reputation_penalty(self):
        challenge = self._challenge()

        refuse_challenge(challenge)
        challenge.refresh_from_db()
        # Read the ROW, not the cached instance. refuse_challenge locks and
        # writes its own copy of the profile (F70), so self.chef_b's cached
        # battle_profile is the pre-refusal object and shows nothing moved.
        # Inherited red on main, found while running T01's suite.
        profile = ChefBattleProfile.objects.get(author=self.chef_b)

        self.assertEqual(challenge.status, BattleChallenge.Status.REFUSED)
        self.assertEqual(profile.refused_battles, 1)
        self.assertEqual(profile.reputation, -5)

    def test_calculate_battle_result_updates_profiles(self):
        battle = accept_challenge(self._challenge())
        BattleVote.objects.create(battle=battle, voter=self.voter, voted_for=self.chef_a)

        # T01, 2026-08-12: the scorer takes only a locked VOTING battle now.
        # This is the state the real flow is in when voting closes.
        walk_battle_to(battle, Battle.Status.VOTING)
        calculate_battle_result(battle)
        battle.refresh_from_db()
        winner_profile = self.chef_a.battle_profile
        loser_profile = self.chef_b.battle_profile

        self.assertEqual(battle.status, Battle.Status.COMPLETED)
        self.assertEqual(battle.winner, self.chef_a)
        winner_profile.refresh_from_db()
        loser_profile.refresh_from_db()
        self.assertEqual(winner_profile.wins, 1)
        self.assertEqual(winner_profile.battle_moves, 11)  # MOVES_BATTLE_WIN(10) + MOVES_BATTLE_PARTICIPATION(1)
        self.assertEqual(loser_profile.battle_moves, 6)    # PARTICIPATION(1) + half of WIN(10)
        self.assertEqual(loser_profile.losses, 1)

        # THE OWNER'S RULING, 2026-08-05: a loss is not punished. Second place
        # takes half of everything first place takes, and nothing is deducted.
        self.assertEqual(winner_profile.rating, 25)
        self.assertEqual(loser_profile.rating, 12)
        self.assertEqual(winner_profile.reputation, 15)
        self.assertEqual(loser_profile.reputation, 7)
        self.assertEqual(winner_profile.seasonal_score, 10)
        self.assertEqual(loser_profile.seasonal_score, 5)

    def test_calculate_battle_result_is_idempotent_under_a_repeat_call(self):
        """A cron run and an operator click (or two overlapping cron runs) can
        both fire calculate_battle_result on the same battle. Only the first may
        score it; the rest must be no-ops, or ratings and crowns double."""
        battle = accept_challenge(self._challenge())
        BattleVote.objects.create(battle=battle, voter=self.voter, voted_for=self.chef_a)

        # Two callers each hold their OWN stale copy of the battle — the real
        # race (cron process + operator process), not one shared object. Both
        # see a not-yet-completed status in memory; without the locked re-check
        # both would pass the guard and award the win twice.
        first = Battle.objects.get(pk=battle.pk)
        second = Battle.objects.get(pk=battle.pk)
        # T01, 2026-08-12: the scorer takes only a locked VOTING battle now.
        # This is the state the real flow is in when voting closes.
        # T01, 2026-08-12: the scorer takes only a locked VOTING battle. The
        # row is put in VOTING once, which is where the real flow is when the
        # deadline passes - and deliberately NOT again before the second call,
        # because the second caller landing on an already-completed row is the
        # whole race this test exists for.
        walk_battle_to(first, Battle.Status.VOTING)
        second.status = Battle.Status.VOTING
        calculate_battle_result(first)
        calculate_battle_result(second)

        winner_profile = self.chef_a.battle_profile
        loser_profile = self.chef_b.battle_profile
        winner_profile.refresh_from_db()
        loser_profile.refresh_from_db()
        self.assertEqual(winner_profile.wins, 1)
        self.assertEqual(winner_profile.crown_count, 1)
        self.assertEqual(winner_profile.battle_moves, 11)
        self.assertEqual(loser_profile.losses, 1)

    def test_decisive_win_returns_unused_reserved_artifacts(self):
        """The draw path returned unused reserved personal artifacts to the chest
        but the (far more common) decisive path did not, pinning them to the
        finished battle forever. Both outcomes must settle the same way."""
        from chef_battle.models import Artifact, ChefArtifact
        battle = accept_challenge(self._challenge())
        artifact = Artifact.objects.create(name="Unused Loadout Blade")
        reserved = ChefArtifact.objects.create(
            chef=self.chef_a, artifact=artifact,
            status=ChefArtifact.Status.AVAILABLE, reserved_in_battle=battle,
        )
        BattleVote.objects.create(battle=battle, voter=self.voter, voted_for=self.chef_a)

        # T01, 2026-08-12: the scorer takes only a locked VOTING battle now.
        # This is the state the real flow is in when voting closes.
        walk_battle_to(battle, Battle.Status.VOTING)
        calculate_battle_result(battle)

        reserved.refresh_from_db()
        self.assertIsNone(
            reserved.reserved_in_battle,
            "an unused reserved artifact must return to the chef after a decisive win",
        )

    @override_settings(SECURE_SSL_REDIRECT=False)
    def test_recipe_is_locked_from_edits_while_in_a_live_battle(self):
        """A recipe entered in a running battle is frozen: editing it would drift
        the biathlon's line indices and could flip it out of APPROVED, 404-ing the
        dish out from under the audience mid-vote."""
        from recipes.models import Recipe
        from chef_battle.selectors import active_battle_locking_recipe

        recipe = Recipe.objects.create(
            title="Live Battle Dish", slug="live-battle-dish", author=self.chef_a,
            ingredients="lamb\npotato\nmint", method="Cook.", status=Recipe.Status.APPROVED,
        )
        challenge = self._challenge()
        challenge.theme_recipe = recipe
        challenge.save(update_fields=["theme_recipe"])
        battle = accept_challenge(challenge)

        self.assertEqual(active_battle_locking_recipe(recipe), battle)

        self.client.force_login(self.user_a)
        edit_url = reverse("recipes:recipe_edit", args=[recipe.slug])
        blocked = self.client.get(edit_url)
        self.assertEqual(blocked.status_code, 302)
        self.assertIn(recipe.get_absolute_url(), blocked["Location"])

        # Once the battle is over the recipe is editable again.
        battle.status = Battle.Status.COMPLETED
        battle.save(update_fields=["status"])
        self.assertIsNone(active_battle_locking_recipe(recipe))
        self.assertEqual(self.client.get(edit_url).status_code, 200)

    def test_matchup_is_limited_to_adjacent_ranks(self):
        profile_a = ChefBattleProfile.objects.create(
            author=self.chef_a,
            rank=ChefBattleProfile.Rank.KITCHEN_PORTER,
        )
        profile_b = ChefBattleProfile.objects.create(
            author=self.chef_b,
            rank=ChefBattleProfile.Rank.PREP_COOK,
        )

        self.assertIsNone(check_rank_matchup(self.chef_a, self.chef_b))

        profile_b.rank = ChefBattleProfile.Rank.COMMIS_CHEF
        profile_b.save(update_fields=["rank"])
        self.assertIn("Rank mismatch", check_rank_matchup(self.chef_a, self.chef_b))

        profile_a.is_hero = True
        profile_a.save(update_fields=["is_hero"])
        self.assertIsNone(check_rank_matchup(self.chef_a, self.chef_b))

    def test_fifteenth_win_does_not_grant_hero_status(self):
        battle = accept_challenge(self._challenge())
        # accept_challenge creates both profiles since F9 (v2.5.994) - its
        # rank check calls get_or_create_battle_profile - so creating one here
        # raises UniqueViolation. Take the row it made and set the wins.
        profile = get_or_create_battle_profile(self.chef_a)
        ChefBattleProfile.objects.filter(pk=profile.pk).update(wins=14)
        profile.refresh_from_db()
        BattleVote.objects.create(battle=battle, voter=self.voter, voted_for=self.chef_a)

        # T01, 2026-08-12: the scorer takes only a locked VOTING battle now.
        # This is the state the real flow is in when voting closes.
        walk_battle_to(battle, Battle.Status.VOTING)
        calculate_battle_result(battle)

        profile.refresh_from_db()
        self.assertEqual(profile.wins, 15)
        self.assertFalse(profile.is_hero)

    def test_vote_clean_allows_authenticated_user_without_author_profile(self):
        battle = accept_challenge(self._challenge())
        vote = BattleVote(battle=battle, voter=self.voter, voted_for=self.chef_a)

        vote.full_clean()

    def test_vote_clean_blocks_self_vote_for_linked_author(self):
        battle = accept_challenge(self._challenge())
        vote = BattleVote(battle=battle, voter=self.user_a, voted_for=self.chef_a)

        with self.assertRaises(ValidationError):
            vote.full_clean()


@override_settings(SECURE_SSL_REDIRECT=False, CHEF_BATTLE_ENABLED=True)
class ChefBattleAccessTests(TestCase):
    """Permission tests for Chef Battle pages with feature flag enabled."""

    def setUp(self):
        User = get_user_model()
        self.client = Client()
        self.user = User.objects.create_user(username="regular", password="pw")
        self.staff = User.objects.create_user(username="staff", password="pw", is_staff=True)
        self.superuser = User.objects.create_user(
            username="bearseeker-super", password="pw", is_staff=True, is_superuser=True
        )
        self.moderator = User.objects.create_user(username="bearseeker-admin", password="pw")
        RecipeAuthor.objects.create(
            user=self.moderator, name="Bearseeker Admin", slug="bearseeker-admin",
            has_bearseeker_privileges=True,
        )

    def test_anonymous_can_view_battle_home(self):
        response = self.client.get(reverse("chef_battle:home"))
        self.assertEqual(response.status_code, 200)

    def test_regular_user_can_view_battle_home(self):
        self.client.login(username="regular", password="pw")
        response = self.client.get(reverse("chef_battle:home"))
        self.assertEqual(response.status_code, 200)

    def test_staff_user_can_access_battle_home(self):
        self.client.login(username="staff", password="pw")
        response = self.client.get(reverse("chef_battle:home"))
        self.assertEqual(response.status_code, 200)

    def test_anonymous_can_view_rankings(self):
        response = self.client.get(reverse("chef_battle:rankings"))
        self.assertEqual(response.status_code, 200)

    def test_anonymous_challenge_list_redirects_to_login(self):
        response = self.client.get(reverse("chef_battle:challenge_list"))
        # challenge_list requires login → redirect to login page
        self.assertEqual(response.status_code, 302)

    @override_settings(CHEF_BATTLE_ENABLED=False)
    def test_only_a_bearseeker_super_user_sees_chef_battles(self):
        """The Owner's three tiers, 2026-08-04, separated by `is_staff`.

        AUTHOR is_staff False -> nothing. (Bear)seeker Admin and (Bear)seeker
        Super User are is_staff True -> the application. AGENTS.md section 20.

        Asserted with the public flag off, which is where the gate decides.
        """
        from django.test import RequestFactory
        from django.contrib.auth.models import AnonymousUser
        from config.context_processors import battle_visibility
        from chef_battle.access import is_battle_visible

        request = RequestFactory().get("/")
        cases = [
            ("anonymous", AnonymousUser(), False),
            ("AUTHOR", self.user, False),
            # The moderator flag without the staff bit is not a tier: it is what
            # the panel's grant action produced for its whole life.
            ("moderator flag, no staff bit", self.moderator, False),
            ("(Bear)seeker Admin", self.staff, True),
            ("(Bear)seeker Super User", self.superuser, True),
        ]
        for label, user, expected in cases:
            with self.subTest(tier=label):
                request.user = user
                self.assertEqual(is_battle_visible(request), expected)
                # The advertised entrance must agree with the gate, or a shown
                # button leads to a 404 - which is the argument that was used to
                # widen the gate in the first place, instead of narrowing the UI.
                self.assertEqual(
                    battle_visibility(request)["battle_visible"], expected
                )

    @override_settings(CHEF_BATTLE_ENABLED=False)
    def test_being_let_into_the_app_is_not_being_let_into_the_console(self):
        """A (Bear)seeker Super User reaches the application. The Arena Master
        Console needs the Owner to authorise that account separately
        (has_arena_console_access), so being a superuser is not enough."""
        from django.test import RequestFactory
        from chef_battle.access import is_battle_visible, has_arena_console_access

        request = RequestFactory().get("/")

        request.user = self.superuser
        self.assertTrue(is_battle_visible(request))
        self.assertFalse(has_arena_console_access(request))

        # An Admin reaches the application and gets nowhere near the console.
        request.user = self.staff
        self.assertTrue(is_battle_visible(request))
        self.assertFalse(has_arena_console_access(request))

    @override_settings(CHEF_BATTLE_ENABLED=False)
    def test_the_rules_page_stays_open_and_the_galleries_do_not(self):
        """The Owner named the exceptions himself: the rules, and the news.
        The artifact and gift galleries were public by an older decision and
        are Chef Battles content, so they moved behind the gate in v2.5.798."""
        self.assertEqual(self.client.get(reverse("chef_battle:rules")).status_code, 200)
        for name in ("artifact_gallery", "appreciation_gallery"):
            with self.subTest(view=name):
                self.assertEqual(
                    self.client.get(reverse(f"chef_battle:{name}")).status_code, 404
                )


@override_settings(SECURE_SSL_REDIRECT=False, CHEF_BATTLE_ENABLED=True)
class ChefBattleChallengeCreateViewTests(TestCase):
    def setUp(self):
        User = get_user_model()
        self.client = Client()
        self.user = User.objects.create_user(username="challenge-owner", password="pw", is_staff=True)
        self.opponent_user = User.objects.create_user(username="challenge-opponent", password="pw")
        self.author = RecipeAuthor.objects.create(user=self.user, name="Challenge Owner", slug="challenge-owner")
        self.opponent = RecipeAuthor.objects.create(user=self.opponent_user, name="Challenge Opponent", slug="challenge-opponent")
        ChefBattleProfile.objects.create(author=self.author, battle_moves=10)

    def _opponent_recipe(self, status=None):
        from recipes.models import Recipe
        return Recipe.objects.create(
            title="Dingle Crab Toast", slug="dingle-crab-toast", author=self.opponent,
            ingredients="crab\nbread", method="Toast.",
            status=status or Recipe.Status.APPROVED,
        )

    def test_inspired_by_seeds_the_theme_and_names_the_recipe_author(self):
        """The CTA on someone else's recipe page arrives here."""
        recipe = self._opponent_recipe()
        self.client.login(username="challenge-owner", password="pw")

        response = self.client.get(
            reverse("chef_battle:challenge_create") + f"?inspired_by={recipe.slug}"
        )

        self.assertEqual(response.status_code, 200)
        form = response.context["form"]
        self.assertEqual(form.initial["theme"], "Dingle Crab Toast")
        self.assertEqual(form.initial["opponent"], self.opponent.pk)
        self.assertEqual(response.context["inspired_by"], recipe)

    def test_inspired_by_never_offers_someone_elses_recipe_as_your_entry(self):
        """theme_recipe becomes the challenger's own battle entry on accept, so
        the recipe that inspired the theme must not leak into that choice."""
        recipe = self._opponent_recipe()
        self.client.login(username="challenge-owner", password="pw")

        response = self.client.get(
            reverse("chef_battle:challenge_create") + f"?inspired_by={recipe.slug}"
        )

        form = response.context["form"]
        self.assertNotIn("theme_recipe", form.initial)
        self.assertNotIn(recipe, form.fields["theme_recipe"].queryset)

    def test_inspired_by_ignores_a_recipe_the_audience_cannot_open(self):
        from recipes.models import Recipe
        recipe = self._opponent_recipe(status=Recipe.Status.DRAFT)
        self.client.login(username="challenge-owner", password="pw")

        response = self.client.get(
            reverse("chef_battle:challenge_create") + f"?inspired_by={recipe.slug}"
        )

        self.assertEqual(response.status_code, 200)
        self.assertIsNone(response.context["inspired_by"])
        self.assertNotIn("theme", response.context["form"].initial)

    def test_inspired_by_ignores_an_unknown_slug(self):
        self.client.login(username="challenge-owner", password="pw")

        response = self.client.get(
            reverse("chef_battle:challenge_create") + "?inspired_by=no-such-recipe"
        )

        self.assertEqual(response.status_code, 200)
        self.assertIsNone(response.context["inspired_by"])

    def test_explicit_opponent_wins_over_the_inspiring_recipes_author(self):
        recipe = self._opponent_recipe()
        User = get_user_model()
        third_user = User.objects.create_user(username="third-chef", password="pw")
        third = RecipeAuthor.objects.create(user=third_user, name="Third Chef", slug="third-chef")
        self.client.login(username="challenge-owner", password="pw")

        response = self.client.get(
            reverse("chef_battle:challenge_create")
            + f"?inspired_by={recipe.slug}&opponent={third.slug}"
        )

        self.assertEqual(response.context["form"].initial["opponent"], third.pk)

    @override_settings(CHEF_BATTLE_ENABLED=False)
    def test_issue_challenge_cta_shows_only_where_the_click_would_work(self):
        """The recipe-page CTA (spec [23]) must appear exactly when the challenge
        view would accept it: for a battle-visible viewer, on someone else's
        approved recipe. Never on your own recipe, never for anonymous."""
        from recipes.models import Recipe
        recipe = Recipe.objects.create(
            title="Someone Elses Dish", slug="someone-elses-dish", author=self.opponent,
            ingredients="crab", method="Toast.", status=Recipe.Status.APPROVED,
        )
        url = reverse("recipes:recipe_detail", args=[recipe.slug])
        expected_href = (
            reverse("chef_battle:challenge_create")
            + f"?opponent={self.opponent.slug}&inspired_by={recipe.slug}"
        )

        # A (Bear)seeker Admin - is_staff, which is the tier line (AGENTS.md 20).
        # The actor here has moved twice in one day and the invariant has not:
        # the CTA shows exactly where the click works. First it was any staff
        # user, then superuser-only for an hour, now staff again. Each time the
        # test followed the gate, which is the point of it.
        self.client.login(username="challenge-owner", password="pw")
        shown = self.client.get(url)
        self.assertContains(shown, "Issue a Challenge")
        self.assertContains(shown, expected_href)

        # An AUTHOR - no staff bit - is not a viewer, and the CTA must follow.
        # A shown button whose click 404s is the exact defect that got the gate
        # widened in the first place.
        self.user.is_staff = False
        self.user.save(update_fields=["is_staff"])
        self.assertNotContains(self.client.get(url), "Issue a Challenge")
        self.user.is_staff = True
        self.user.save(update_fields=["is_staff"])

        # anonymous never sees it
        self.client.logout()
        self.assertNotContains(self.client.get(url), "Issue a Challenge")

        # the author never sees it on their own recipe
        own = Recipe.objects.create(
            title="Owners Own Dish", slug="owners-own-dish", author=self.author,
            ingredients="lamb", method="Cook.", status=Recipe.Status.APPROVED,
        )
        self.client.login(username="challenge-owner", password="pw")
        self.assertNotContains(
            self.client.get(reverse("recipes:recipe_detail", args=[own.slug])),
            "Issue a Challenge",
        )

    def test_challenge_create_page_renders_guided_form_layout(self):
        self.client.login(username="challenge-owner", password="pw")

        response = self.client.get(reverse("chef_battle:challenge_create"))

        self.assertEqual(response.status_code, 200)
        self.assertContains(response, "battle-challenge-layout")
        self.assertContains(response, "Challenge checklist")
        self.assertContains(response, "Pending challenges expire after 12 hours.")
        self.assertContains(response, "Challenge Opponent")
        self.assertContains(response, 'name="opponent"', html=False)
        self.assertContains(response, 'name="battle_type"', html=False)


