# ---------------------------------------------------------------------------
# CB-22xx: Phase 8 — Suspension gate on arena POST actions
# ---------------------------------------------------------------------------

class RoutedViewAccessAuditTests(TestCase):
    """Every routed chef_battle view is guarded, or listed as deliberately not.

    Guarding by decorator is fail-open: a view added without chef_battle_guard
    is public, and nothing announces it. An audit found 37 of 79 routed views
    without a guard — most correct, some only by luck, one (battle_chat_poll)
    a leak that had already been found and patched by hand. The point of this
    test is not the current count; it is that the NEXT view cannot slip in
    unnoticed.
    """

    def _routed_chef_battle_views(self):
        from django.urls import get_resolver

        resolver = get_resolver()
        found = {}
        for pattern in resolver.url_patterns:
            if getattr(pattern, "namespace", None) != "chef_battle":
                continue
            for route in pattern.url_patterns:
                callback = getattr(route, "callback", None)
                if callback is None:
                    continue
                found[callback.__name__] = callback
        return found

    def test_every_routed_view_is_guarded_or_listed(self):
        from .access import UNGUARDED_BY_DESIGN

        views = self._routed_chef_battle_views()
        self.assertTrue(views, "no chef_battle routes were resolved — check the namespace")

        unaccounted = sorted(
            name for name, view in views.items()
            if not getattr(view, "chef_battle_access_checked", False)
            and name not in UNGUARDED_BY_DESIGN
        )
        self.assertEqual(
            unaccounted, [],
            "These chef_battle views carry no access guard and are not listed in "
            "UNGUARDED_BY_DESIGN. Add the guard, or add the view to that dict with "
            "the reason it is safe without one: " + ", ".join(unaccounted),
        )

    def test_the_allowlist_does_not_outlive_its_views(self):
        """A name left behind after a view is renamed or deleted is a stale
        exemption that would silently cover the next view to take that name."""
        from .access import UNGUARDED_BY_DESIGN

        views = self._routed_chef_battle_views()
        stale = sorted(set(UNGUARDED_BY_DESIGN) - set(views))
        self.assertEqual(
            stale, [],
            "UNGUARDED_BY_DESIGN names views that are no longer routed: " + ", ".join(stale),
        )

    def test_every_exemption_states_a_reason(self):
        from .access import UNGUARDED_BY_DESIGN

        blank = sorted(k for k, v in UNGUARDED_BY_DESIGN.items() if not (v or "").strip())
        self.assertEqual(blank, [], "Exemptions without a reason: " + ", ".join(blank))


@override_settings(CHEF_BATTLE_ENABLED=True)
class SuspensionGateTests(TestCase):
    """CB-2201: suspended profiles cannot POST to arena views."""

    def setUp(self):
        User = get_user_model()
        self.user = User.objects.create_user(username="suspendedchef", password="pw")
        chef = RecipeAuthor.objects.create(user=self.user, name="Suspended Chef", slug="suspended-chef")
        profile = ChefBattleProfile.objects.create(author=chef)
        profile.is_suspended = True
        profile.save()
        self.client = Client()
        self.client.login(username="suspendedchef", password="pw")

    def test_suspended_user_post_to_send_gift_is_redirected(self):
        url = reverse("chef_battle:send_appreciation_gift", kwargs={"pk": 1})
        response = self.client.post(url, {"gift_type": "coffee"})
        # redirect, not 200 or 403
        self.assertIn(response.status_code, [301, 302])

    def test_suspension_covers_every_combat_action_endpoint(self):
        """Suspension is enforced by chef_battle_guard and by nothing else, so a
        combat endpoint without the decorator lets a suspended chef keep playing.
        These five carried only @login_required and were reachable throughout."""
        endpoints = [
            ("chef_battle:battle_set_ready", {}),
            ("chef_battle:battle_declare_menu", {}),
            ("chef_battle:biathlon_shoot", {"target_ingredient_id": "0"}),
            ("chef_battle:cooking_submit", {}),
        ]
        for name, payload in endpoints:
            with self.subTest(endpoint=name):
                url = reverse(name, kwargs={"pk": 1})
                response = self.client.post(url, payload)
                self.assertIn(
                    response.status_code, [301, 302],
                    f"{name} did not turn a suspended chef away",
                )

    def test_refused_post_does_not_redirect_a_post_only_view_onto_itself(self):
        """Most arena actions are POST-only, so bouncing a refused POST back to
        its own URL served the suspended user a bare 405 instead of the message."""
        url = reverse("chef_battle:biathlon_shoot", kwargs={"pk": 1})
        response = self.client.post(url, {"target_ingredient_id": "0"})
        self.assertIn(response.status_code, [301, 302])
        self.assertNotEqual(response["Location"], url)

    def test_refused_post_honours_a_same_site_referer(self):
        response = self.client.post(
            reverse("chef_battle:battle_set_ready", kwargs={"pk": 1}),
            HTTP_REFERER="/chef-battle/challenges/",
        )
        self.assertEqual(response["Location"], "/chef-battle/challenges/")

    def test_refused_post_refuses_an_off_site_referer(self):
        """A Referer is attacker-controlled; it must never become an open redirect."""
        response = self.client.post(
            reverse("chef_battle:battle_set_ready", kwargs={"pk": 1}),
            HTTP_REFERER="https://evil.example/phish",
        )
        self.assertNotIn("evil.example", response["Location"])


