@override_settings(
    CHEF_BATTLE_ENABLED=True,
    ARENA_MASTER_CONSOLE_ENABLED=True,
    OWNER_SLUG="amc-sec-owner",
)
class ArenaMasterActionSecurityTests(TransactionTestCase):
    """Audit trail, idempotency, concurrency, rollback, and CSRF tests for
    the Arena Master Console master_action endpoint.

    Two tiers under test:
      DG-01 (arena_console_guard): superuser + has_arena_console_access
      DG-02 (view-level): owner-only for write actions (OWNER_SLUG match)

    amc-sec-owner  -- passes DG-01 AND DG-02 (OWNER_SLUG overridden)
    amc-sec-other  -- passes DG-01 but fails DG-02 (non-owner operator)
    """

    def setUp(self):
        User = get_user_model()
        owner_user = User.objects.create_user("amc-sec-owner", password="pw", is_superuser=True)
        other_user = User.objects.create_user("amc-sec-other", password="pw", is_superuser=True)
        self.owner_author = RecipeAuthor.objects.create(
            user=owner_user, name="AMC Owner", slug="amc-sec-owner",
            has_arena_console_access=True)
        self.other_author = RecipeAuthor.objects.create(
            user=other_user, name="AMC Other", slug="amc-sec-other",
            has_arena_console_access=True)
        now = timezone.now()
        self.battle = Battle.objects.create(
            challenger=self.owner_author, opponent=self.other_author,
            theme="Security Battle", status=Battle.Status.SCHEDULED,
            start_time=now, submission_deadline=now + timezone.timedelta(days=1),
            voting_deadline=now + timezone.timedelta(days=2),
            end_time=now + timezone.timedelta(days=3),
        )
        self.url = reverse("chef_battle:master_action")

    def _login_owner(self):
        c = Client()
        c.login(username="amc-sec-owner", password="pw")
        return c

    def _login_other(self):
        c = Client()
        c.login(username="amc-sec-other", password="pw")
        return c

    # -- Audit trail tests ------------------------------------------------
    # NOTE: master_action view reads request.POST (form-encoded), not JSON.
    # Field names come from the view: target_status (not new_status), etc.

    def test_non_owner_rejection_is_audited(self):
        """Non-owner console operator (passes DG-01 guard) gets 403 from DG-02
        and the rejection is written to the audit trail."""
        c = self._login_other()
        before = BattleEvent.objects.count()
        resp = c.post(self.url, data={
            "action": "force_status", "battle_id": self.battle.pk,
            "target_status": "active", "correlation_id": "sec-test-1"})
        self.assertEqual(resp.status_code, 403)
        self.assertEqual(BattleEvent.objects.count(), before + 1)
        ev = BattleEvent.objects.order_by("-created_at").first()
        self.assertEqual(ev.payload_json["outcome"], "rejected")

    def test_invalid_battle_id_rejection_is_audited(self):
        c = self._login_owner()
        before = BattleEvent.objects.count()
        resp = c.post(self.url, data={
            "action": "force_status", "battle_id": "not-a-number",
            "target_status": "active", "correlation_id": "sec-test-2"})
        self.assertEqual(resp.status_code, 400)
        self.assertEqual(BattleEvent.objects.count(), before + 1)
        ev = BattleEvent.objects.order_by("-created_at").first()
        self.assertEqual(ev.payload_json["outcome"], "rejected")

    def test_not_found_rejection_is_audited(self):
        c = self._login_owner()
        before = BattleEvent.objects.count()
        resp = c.post(self.url, data={
            "action": "force_status", "battle_id": 999999,
            "target_status": "active", "correlation_id": "sec-test-3"})
        self.assertEqual(resp.status_code, 404)
        self.assertEqual(BattleEvent.objects.count(), before + 1)
        ev = BattleEvent.objects.order_by("-created_at").first()
        self.assertEqual(ev.payload_json["outcome"], "rejected")

    def test_unknown_action_rejection_is_audited(self):
        c = self._login_owner()
        before = BattleEvent.objects.count()
        resp = c.post(self.url, data={
            "action": "does_not_exist", "correlation_id": "sec-test-4"})
        self.assertEqual(resp.status_code, 400)
        self.assertEqual(BattleEvent.objects.count(), before + 1)
        ev = BattleEvent.objects.order_by("-created_at").first()
        self.assertEqual(ev.payload_json["outcome"], "rejected")

    def test_service_rejection_stale_state_is_audited(self):
        """force_status with wrong expected_status triggers OperatorActionError."""
        c = self._login_owner()
        before = BattleEvent.objects.count()
        resp = c.post(self.url, data={
            "action": "force_status", "battle_id": self.battle.pk,
            "target_status": "active",
            "expected_status": "voting",  # wrong -- battle is scheduled
            "correlation_id": "sec-test-5"})
        self.assertIn(resp.status_code, (400, 409))
        self.assertGreater(BattleEvent.objects.count(), before)
        ev = BattleEvent.objects.filter(
            payload_json__outcome="rejected").order_by("-created_at").first()
        self.assertIsNotNone(ev)

    # -- Idempotency / dedup tests ----------------------------------------

    def test_broadcast_replay_with_same_correlation_id_is_rejected(self):
        c = self._login_owner()
        post_data = {
            "action": "broadcast", "message": "Hello arena",
            "correlation_id": "idem-corr-001"}
        r1 = c.post(self.url, data=post_data)
        self.assertEqual(r1.status_code, 200)
        r2 = c.post(self.url, data=post_data)
        self.assertEqual(r2.status_code, 409)
        data2 = json.loads(r2.content)
        self.assertFalse(data2["ok"])
        self.assertIn("already", data2["error"].lower())
        self.assertEqual(
            OperatorActionIdempotencyKey.objects.filter(correlation_id="idem-corr-001").count(),
            1)

    def test_broadcast_without_correlation_id_is_not_deduplicated(self):
        """Omitting correlation_id: view auto-generates a unique one per request,
        so two identical broadcasts both apply."""
        c = self._login_owner()
        post_data = {"action": "broadcast", "message": "No dedup here"}
        r1 = c.post(self.url, data=post_data)
        r2 = c.post(self.url, data=post_data)
        self.assertEqual(r1.status_code, 200)
        self.assertEqual(r2.status_code, 200)

    # -- Concurrency test -------------------------------------------------

    def test_concurrent_force_status_requests_serialize_exactly_once(self):
        """Two threads race to force the same status transition.
        Only one must succeed; the other must be rejected (stale-state guard
        or DB serialization). raise_request_exception=False so SQLite
        serialization errors appear as 500 rather than propagating."""
        import threading

        self.battle.status = Battle.Status.SCHEDULED
        self.battle.save(update_fields=["status"])

        results = []
        errors = []

        # Log both clients in serially on the main thread — a concurrent login
        # is a session-table write that can hit an SQLite lock and kill the
        # thread before the race under test (the POST) even starts.
        clients = []
        for _ in range(2):
            c = Client(raise_request_exception=False)
            c.login(username="amc-sec-owner", password="pw")
            clients.append(c)

        def do_request(c):
            # raise_request_exception=False: DB errors become 500, not thread crashes
            try:
                r = c.post(self.url, data={
                    "action": "force_status",
                    "battle_id": self.battle.pk,
                    "target_status": "active",
                    "expected_status": "scheduled",
                    "correlation_id": ""})
                results.append(r.status_code)
            except Exception as e:
                errors.append(e)
            finally:
                # Thread-local PostgreSQL connections otherwise survive long
                # enough to block Django from dropping the test database.
                from django.db import connections
                connections.close_all()

        t1 = threading.Thread(target=do_request, args=(clients[0],))
        t2 = threading.Thread(target=do_request, args=(clients[1],))
        t1.start(); t2.start()
        t1.join(); t2.join()

        self.assertFalse(errors, f"Thread errors: {errors}")
        self.assertEqual(len(results), 2, f"Both threads must complete, got: {results}")
        ok_count = results.count(200)
        # Any non-200 counts as a rejection (409=stale, 400=invalid, 500=db lock)
        rejected_count = len([s for s in results if s != 200])
        self.assertEqual(ok_count, 1, f"Expected exactly 1 success, got: {results}")
        self.assertEqual(rejected_count, 1, f"Expected exactly 1 rejection, got: {results}")

    # -- Rollback test ----------------------------------------------------

    def test_exception_mid_transaction_rolls_back_state_and_audit(self):
        """If RuntimeError fires before operator_force_status runs (simulating
        a crash before any DB write), the battle status must remain unchanged
        and the view must not return 200. raise_request_exception=False so the
        RuntimeError becomes a 500 response instead of propagating to the test."""
        from unittest.mock import patch
        from chef_battle import services as svc

        def crashing_force(**kwargs):
            raise RuntimeError("Crash before any state write")

        c = Client(raise_request_exception=False)
        c.login(username="amc-sec-owner", password="pw")
        before_status = self.battle.status

        with patch.object(svc, "operator_force_status", side_effect=crashing_force):
            resp = c.post(self.url, data={
                "action": "force_status",
                "battle_id": self.battle.pk,
                "target_status": "active",
                "expected_status": "",
                "correlation_id": "rollback-test-001"})

        # Must not return 200 (no success on crash)
        self.assertNotEqual(resp.status_code, 200)
        # Battle status must be unchanged because the service never ran
        self.battle.refresh_from_db()
        self.assertEqual(self.battle.status, before_status,
                         "Battle status must not have changed after service crash")

    # -- CSRF enforcement tests -------------------------------------------

    def test_post_without_csrf_token_is_rejected_with_csrf_enforced(self):
        c = Client(enforce_csrf_checks=True)
        c.login(username="amc-sec-owner", password="pw")
        resp = c.post(self.url, data={
            "action": "broadcast", "message": "csrf test",
            "correlation_id": "csrf-test-no-token"})
        self.assertEqual(resp.status_code, 403)

    def test_post_with_valid_csrf_token_succeeds_with_csrf_enforced(self):
        c = Client(enforce_csrf_checks=True)
        c.login(username="amc-sec-owner", password="pw")
        # GET to master_console forces Django to set the csrftoken cookie
        c.get(reverse("chef_battle:master_console"))
        csrf_value = c.cookies.get("csrftoken")
        self.assertIsNotNone(csrf_value, "CSRF cookie must be set after GET")
        resp = c.post(self.url,
            data={"action": "broadcast", "message": "csrf success test",
                  "correlation_id": "csrf-test-with-token"},
            HTTP_X_CSRFTOKEN=csrf_value.value)
        self.assertEqual(resp.status_code, 200)
        data = json.loads(resp.content)
        self.assertTrue(data["ok"])


# ── Combat artifact activation (Gap 2 fix) ───────────────────────────────────

@override_settings(CHEF_BATTLE_ENABLED=True)
class CombatArtifactTests(TestCase):
    """submit_combat_action accepts artifact_id; _resolve_round consumes it."""

    def setUp(self):
        from .models import Artifact, ChefArtifact, ChefBattleProfile
        User = get_user_model()
        ua = User.objects.create_user("art-chef-a", password="pw")
        ub = User.objects.create_user("art-chef-b", password="pw")
        self.chef_a = RecipeAuthor.objects.create(user=ua, name="Art Chef A", slug="art-chef-a")
        self.chef_b = RecipeAuthor.objects.create(user=ub, name="Art Chef B", slug="art-chef-b")
        ChefBattleProfile.objects.create(author=self.chef_a, enrolled_at=timezone.now(), battle_moves=50)
        ChefBattleProfile.objects.create(author=self.chef_b, enrolled_at=timezone.now(), battle_moves=50)
        now = timezone.now()
        self.battle = Battle.objects.create(
            challenger=self.chef_a, opponent=self.chef_b,
            theme="Artifact Dish", status=Battle.Status.ACTIVE,
            start_time=now,
            submission_deadline=now + timezone.timedelta(days=2),
            voting_deadline=now + timezone.timedelta(days=4),
            end_time=now + timezone.timedelta(days=5),
        )
        self.artifact = Artifact.objects.create(
            name="Iron Pan", rarity=Artifact.Rarity.RARE,
            effect_type="attack", effect_value=5, token_cost=50,
        )
        self.chef_artifact = ChefArtifact.objects.create(
            chef=self.chef_a, artifact=self.artifact,
            status=ChefArtifact.Status.AVAILABLE,
        )

    def test_artifact_id_sets_artifact_used_on_action(self):
        from .services import submit_combat_action
        action = submit_combat_action(
            self.battle, self.chef_a, "attack", 3, artifact_id=self.chef_artifact.pk
        )
        self.assertEqual(action.artifact_used_id, self.chef_artifact.pk)

    def test_artifact_consumed_after_round_resolves(self):
        from .models import ChefArtifact
        from .services import submit_combat_action
        submit_combat_action(self.battle, self.chef_a, "attack", 3, artifact_id=self.chef_artifact.pk)
        # Resolves automatically when opponent submits
        submit_combat_action(self.battle, self.chef_b, "defend", 1)
        self.chef_artifact.refresh_from_db()
        self.assertEqual(self.chef_artifact.status, ChefArtifact.Status.CONSUMED)
        self.assertIsNotNone(self.chef_artifact.consumed_at)
        self.assertEqual(self.chef_artifact.consumed_in_battle_id, self.battle.pk)

    def test_artifact_belonging_to_opponent_is_rejected(self):
        from .models import Artifact, ChefArtifact
        from .services import submit_combat_action
        other_artifact = Artifact.objects.create(
            name="Silver Spoon", rarity=Artifact.Rarity.COMMON,
            effect_type="boost", effect_value=2, token_cost=10,
        )
        opponent_ca = ChefArtifact.objects.create(
            chef=self.chef_b, artifact=other_artifact,
            status=ChefArtifact.Status.AVAILABLE,
        )
        with self.assertRaises(ValueError, msg="Artifact not available or does not belong to you."):
            submit_combat_action(self.battle, self.chef_a, "attack", 3, artifact_id=opponent_ca.pk)

    def test_consumed_artifact_is_rejected(self):
        from .models import ChefArtifact
        from .services import submit_combat_action
        self.chef_artifact.status = ChefArtifact.Status.CONSUMED
        self.chef_artifact.save(update_fields=["status"])
        with self.assertRaises(ValueError):
            submit_combat_action(self.battle, self.chef_a, "attack", 3, artifact_id=self.chef_artifact.pk)

    def test_fourth_attack_artifact_is_rejected_for_one_battle(self):
        """A battle loadout has three attack slots, independent of inventory size."""
        from .models import Artifact
        from .services import submit_combat_action

        extras = []
        for index in range(3):
            artifact = Artifact.objects.create(
                name=f"Attack Reserve {index}", rarity=Artifact.Rarity.COMMON,
                effect_type="attack", effect_value=1, token_cost=10,
            )
            extras.append(ChefArtifact.objects.create(
                chef=self.chef_a, artifact=artifact, status=ChefArtifact.Status.AVAILABLE,
            ))

        # Reserve the initial artifact and two extras in separate, unlocked
        # draft actions.  The fourth distinct attack artifact must be refused.
        submit_combat_action(self.battle, self.chef_a, "attack", 1, artifact_id=self.chef_artifact.pk)
        action = self.battle.combat_actions.get(chef=self.chef_a, round_number=1)
        action.delete()
        for chef_artifact in extras[:2]:
            submit_combat_action(self.battle, self.chef_a, "attack", 1, artifact_id=chef_artifact.pk)
            self.battle.combat_actions.get(chef=self.chef_a, round_number=1).delete()

        with self.assertRaisesMessage(ValueError, "at most 3 attack artifacts"):
            submit_combat_action(self.battle, self.chef_a, "attack", 1, artifact_id=extras[2].pk)

    def test_spectator_buys_exact_nonlegendary_artifact_with_delivery_fee(self):
        from .models import TokenTransaction, TokenWallet, ViewerBattleGift
        from .services import credit_tokens, send_battle_artifact

        credit_tokens(self.chef_a, 100, TokenTransaction.TxType.ADMIN_GRANT)
        gift = send_battle_artifact(
            sender_user=self.chef_a.user, recipient=self.chef_b,
            battle=self.battle, artifact=self.artifact,
        )
        self.assertEqual(gift.artifact_id, self.artifact.pk)
        self.assertEqual(gift.delivery_fee, 50)
        self.assertEqual(gift.tokens_spent, 100)
        self.assertTrue(ViewerBattleGift.objects.filter(pk=gift.pk).exists())
        self.assertEqual(TokenWallet.objects.get(chef=self.chef_a).balance, 0)

    def test_legendary_artifact_cannot_be_bought_as_battle_gift(self):
        from .models import Artifact, TokenTransaction
        from .services import credit_tokens, send_battle_artifact

        legendary = Artifact.objects.create(
            name="Prize-only Blade", rarity=Artifact.Rarity.LEGENDARY,
            effect_type="attack", effect_value=60, token_cost=400,
        )
        credit_tokens(self.chef_a, 1000, TokenTransaction.TxType.ADMIN_GRANT)
        with self.assertRaisesMessage(ValueError, "prize-only"):
            send_battle_artifact(
                sender_user=self.chef_a.user, recipient=self.chef_b,
                battle=self.battle, artifact=legendary,
            )

    def test_artifact_effect_label_includes_type_value_and_move(self):
        self.assertEqual(self.artifact.effect_label, "Attack +5 Move")

    def test_knife_roll_uses_paginated_company_style_context(self):
        self.client.force_login(self.chef_a.user)
        response = self.client.get(reverse("chef_battle:battle_chest"))
        self.assertEqual(response.status_code, 200)
        self.assertContains(response, "Your Combat Collection")
        self.assertEqual(response.context["available_page"].paginator.per_page, 24)

    def test_knife_roll_filters_and_links_to_artifact_detail(self):
        self.client.force_login(self.chef_a.user)
        filtered = self.client.get(reverse("chef_battle:battle_chest"), {"filter": "attack"})
        self.assertEqual(filtered.status_code, 200)
        self.assertEqual(filtered.context["roll_filter"], "attack")
        detail = self.client.get(reverse("chef_battle:artifact_detail", args=[self.artifact.pk]))
        self.assertEqual(detail.status_code, 200)
        self.assertContains(detail, "Attack +5 Move")

    def test_combat_without_artifact_unchanged(self):
        from .services import submit_combat_action
        action = submit_combat_action(self.battle, self.chef_a, "attack", 2)
        self.assertIsNone(action.artifact_used_id)

    def test_stronger_defence_wins_the_round_and_scores_a_point(self):
        from .models import Artifact, BattleRound, ChefArtifact
        from .services import submit_combat_action
        apron = Artifact.objects.create(
            name="Common Apron", rarity=Artifact.Rarity.COMMON,
            effect_type="defence", effect_value=5, token_cost=10,
        )
        defender_artifact = ChefArtifact.objects.create(
            chef=self.chef_b, artifact=apron, status=ChefArtifact.Status.AVAILABLE,
        )

        # 3 Move + Apple Corer attack(5) loses to 4 Move + Apron defence(5).
        submit_combat_action(
            self.battle, self.chef_a, "attack", 3, artifact_id=self.chef_artifact.pk)
        submit_combat_action(
            self.battle, self.chef_b, "defend", 4, artifact_id=defender_artifact.pk)

        round_obj = self.battle.combat_rounds.get(round_number=1)
        self.assertEqual(round_obj.attack_power, 8)
        self.assertEqual(round_obj.defence_power, 9)
        self.assertEqual(round_obj.outcome, BattleRound.Outcome.BLOCKED)
        self.assertEqual(round_obj.challenger_hits, 0)
        self.assertEqual(round_obj.opponent_hits, 1)

    def test_combat_winner_opens_recipe_biathlon(self):
        from .services import submit_combat_action
        for _ in range(3):
            submit_combat_action(self.battle, self.chef_a, "attack", 5)
            submit_combat_action(self.battle, self.chef_b, "defend", 1)

        self.battle.refresh_from_db()
        self.assertEqual(self.battle.status, Battle.Status.INGREDIENT_PENALTY)
        self.assertEqual(self.battle.winner, self.chef_a)
        self.assertEqual(self.battle.loser, self.chef_b)

    def test_battle_detail_context_includes_available_artifacts(self):
        self.client.force_login(self.chef_a.user)
        resp = self.client.get(reverse("chef_battle:battle_detail", args=[self.battle.pk]))
        self.assertEqual(resp.status_code, 200)
        available = resp.context["user_available_artifacts"]
        self.assertEqual(len(available), 1)
        self.assertEqual(available[0].pk, self.chef_artifact.pk)

    def test_battle_combat_action_view_accepts_artifact_id(self):
        from .models import ChefArtifact
        self.client.force_login(self.chef_a.user)
        resp = self.client.post(
            reverse("chef_battle:battle_combat_action", args=[self.battle.pk]),
            {"action_type": "attack", "moves_invested": "2", "artifact_id": str(self.chef_artifact.pk)},
        )
        self.assertEqual(resp.status_code, 200)
        data = resp.json()
        self.assertTrue(data["ok"])
        from .models import BattleCombatAction
        action = BattleCombatAction.objects.get(battle=self.battle, chef=self.chef_a, round_number=1)
        self.assertEqual(action.artifact_used_id, self.chef_artifact.pk)


# ── Post-battle cooldown — accept path (Gap 4 fix) ───────────────────────────

@override_settings(CHEF_BATTLE_ENABLED=True, SECURE_SSL_REDIRECT=False)
class PostBattleCooldownAcceptTests(TestCase):
    """gate_post_battle_cooldown is enforced on challenge_respond (accept) as well as challenge_create."""

    def setUp(self):
        from .models import ChefBattleProfile
        User = get_user_model()
        ua = User.objects.create_user("cd-chef-a", password="pw")
        ub = User.objects.create_user("cd-chef-b", password="pw")
        self.chef_a = RecipeAuthor.objects.create(user=ua, name="CD Chef A", slug="cd-chef-a")
        self.chef_b = RecipeAuthor.objects.create(user=ub, name="CD Chef B", slug="cd-chef-b")
        # age_verified is required to ACCEPT since F13 (v2.5.1000) - the gate
        # used to run only for the challenger at challenge_create, so the
        # opponent could enter a real-money battle unverified. This class is
        # about the COOLDOWN, so both chefs are verified and the cooldown is
        # the only thing left that can refuse an accept.
        ChefBattleProfile.objects.create(
            author=self.chef_a, enrolled_at=timezone.now(), battle_moves=20,
            age_verified=True, age_confirmed_at=timezone.now())
        ChefBattleProfile.objects.create(
            author=self.chef_b, enrolled_at=timezone.now(), battle_moves=20,
            age_verified=True, age_confirmed_at=timezone.now())

    def _make_pending_challenge(self):
        return BattleChallenge.objects.create(
            challenger=self.chef_a,
            opponent=self.chef_b,
            theme="Cooldown Dish",
            expires_at=timezone.now() + timezone.timedelta(hours=24),
        )

    def _completed_battle_for(self, chef):
        now = timezone.now()
        other = self.chef_a if chef == self.chef_b else self.chef_b
        return Battle.objects.create(
            challenger=chef, opponent=other,
            theme="Past Dish", status=Battle.Status.COMPLETED,
            start_time=now - timezone.timedelta(hours=2),
            submission_deadline=now - timezone.timedelta(hours=1),
            voting_deadline=now - timezone.timedelta(minutes=30),
            end_time=now - timezone.timedelta(minutes=10),
        )

    def test_accept_blocked_when_accepting_chef_in_cooldown(self):
        self._completed_battle_for(self.chef_b)
        challenge = self._make_pending_challenge()
        self.client.force_login(self.chef_b.user)
        resp = self.client.post(
            reverse("chef_battle:challenge_respond", kwargs={"pk": challenge.pk}),
            {"action": "accept"},
        )
        self.assertEqual(resp.status_code, 302)
        challenge.refresh_from_db()
        self.assertEqual(challenge.status, BattleChallenge.Status.PENDING)

    def test_accept_allowed_when_no_recent_completed_battle(self):
        challenge = self._make_pending_challenge()
        self.client.force_login(self.chef_b.user)
        resp = self.client.post(
            reverse("chef_battle:challenge_respond", kwargs={"pk": challenge.pk}),
            {"action": "accept"},
        )
        self.assertEqual(resp.status_code, 302)
        challenge.refresh_from_db()
        self.assertEqual(challenge.status, BattleChallenge.Status.ACCEPTED)


class DeclareMenuServiceTests(TestCase):
    """Tests for the declare_menu() service (Gap 1 Phase 1)."""

    def setUp(self):
        from .services import declare_menu
        self.declare_menu = declare_menu

        User = get_user_model()
        self.user_a = User.objects.create_user(username="dm-chef-a", password="pw")
        self.user_b = User.objects.create_user(username="dm-chef-b", password="pw")
        self.chef_a = RecipeAuthor.objects.create(user=self.user_a, name="DM Chef A", slug="dm-chef-a")
        self.chef_b = RecipeAuthor.objects.create(user=self.user_b, name="DM Chef B", slug="dm-chef-b")

        now = timezone.now()
        self.battle = Battle.objects.create(
            challenger=self.chef_a,
            opponent=self.chef_b,
            theme="Test Theme",
            status=Battle.Status.MENU_LOCKED,
            submission_deadline=now + timezone.timedelta(days=5),
            voting_deadline=now + timezone.timedelta(days=7),
            end_time=now + timezone.timedelta(days=7),
        )

    def _ingredients(self, n=5, key_indices=(0, 1)):
        return [
            {"name": f"Ingredient {i}", "is_key": i in key_indices}
            for i in range(n)
        ]

    def test_menu_locked_status_precondition(self):
        self.assertEqual(self.battle.status, Battle.Status.MENU_LOCKED)

    def test_declare_menu_creates_ingredients(self):
        from .models import BattleIngredient
        result = self.declare_menu(
            battle=self.battle, chef=self.chef_a, ingredients=self._ingredients()
        )
        self.assertEqual(len(result), 5)
        db_count = BattleIngredient.objects.filter(battle=self.battle, chef=self.chef_a).count()
        self.assertEqual(db_count, 5)

    def test_declare_menu_exactly_two_keys(self):
        from .models import BattleIngredient
        self.declare_menu(battle=self.battle, chef=self.chef_a, ingredients=self._ingredients())
        key_count = BattleIngredient.objects.filter(
            battle=self.battle, chef=self.chef_a, is_key=True
        ).count()
        self.assertEqual(key_count, 2)

    def test_too_few_ingredients_raises(self):
        with self.assertRaises(ValueError):
            self.declare_menu(
                battle=self.battle, chef=self.chef_a, ingredients=self._ingredients(n=4)
            )

    def test_too_many_ingredients_raises(self):
        with self.assertRaises(ValueError):
            self.declare_menu(
                battle=self.battle, chef=self.chef_a, ingredients=self._ingredients(n=8)
            )

    def test_wrong_key_count_raises(self):
        with self.assertRaises(ValueError):
            self.declare_menu(
                battle=self.battle, chef=self.chef_a,
                ingredients=self._ingredients(key_indices=(0,))  # only 1 key
            )

    def test_both_declare_transitions_to_active(self):
        self.declare_menu(battle=self.battle, chef=self.chef_a, ingredients=self._ingredients())
        self.declare_menu(battle=self.battle, chef=self.chef_b, ingredients=self._ingredients())
        self.battle.refresh_from_db()
        self.assertEqual(self.battle.status, Battle.Status.ACTIVE)

    def test_first_declare_stays_menu_locked(self):
        self.declare_menu(battle=self.battle, chef=self.chef_a, ingredients=self._ingredients())
        self.battle.refresh_from_db()
        self.assertEqual(self.battle.status, Battle.Status.MENU_LOCKED)

    def test_duplicate_declare_raises(self):
        self.declare_menu(battle=self.battle, chef=self.chef_a, ingredients=self._ingredients())
        with self.assertRaises(ValueError):
            self.declare_menu(
                battle=self.battle, chef=self.chef_a, ingredients=self._ingredients()
            )

    def test_unequal_count_raises(self):
        """Spec: both chefs must declare the same number of ingredients (5 vs 5, 6 vs 6)."""
        self.declare_menu(battle=self.battle, chef=self.chef_a, ingredients=self._ingredients(n=5))
        with self.assertRaises(ValueError):
            self.declare_menu(
                battle=self.battle, chef=self.chef_b, ingredients=self._ingredients(n=6)
            )
        # Matching count is accepted and starts the battle
        self.declare_menu(battle=self.battle, chef=self.chef_b, ingredients=self._ingredients(n=5))
        self.battle.refresh_from_db()
        self.assertEqual(self.battle.status, Battle.Status.ACTIVE)

    def test_wrong_battle_status_raises(self):
        # RED ON MAIN, NOT MINE, FIXED ON THE WAY PAST (T19, 2026-08-15).
        # This wrote MENU_LOCKED -> SCHEDULED on the class's own battle, which
        # T12's transition matrix and the migration 0094 trigger refuse - the
        # test died on the setup rather than on what it asserts. The subject
        # is "declare_menu refuses a battle that is not MENU_LOCKED", so it
        # takes a battle that IS scheduled instead of walking one backwards.
        now = timezone.now()
        scheduled = Battle.objects.create(
            challenger=self.chef_a,
            opponent=self.chef_b,
            theme="Not locked yet",
            status=Battle.Status.SCHEDULED,
            submission_deadline=now + timezone.timedelta(days=5),
            voting_deadline=now + timezone.timedelta(days=7),
            end_time=now + timezone.timedelta(days=7),
        )
        with self.assertRaises(ValueError):
            self.declare_menu(
                battle=scheduled, chef=self.chef_a, ingredients=self._ingredients()
            )


@override_settings(SECURE_SSL_REDIRECT=False, CHEF_BATTLE_ENABLED=True)
class TokenCheckoutCancelSecurityTests(TestCase):
    """IDOR guard: only the order's owner may cancel it via ?order=N."""

    def setUp(self):
        from .models import TokenOrder, TokenPackage, TokenWallet
        User = get_user_model()
        self.owner_user = User.objects.create_user(username="tcc-owner", password="pw")
        self.other_user = User.objects.create_user(username="tcc-other", password="pw")
        self.owner = RecipeAuthor.objects.create(user=self.owner_user, name="TCC Owner", slug="tcc-owner")
        self.other = RecipeAuthor.objects.create(user=self.other_user, name="TCC Other", slug="tcc-other")
        self.wallet = TokenWallet.objects.create(chef=self.owner)
        self.package = TokenPackage.objects.create(
            key="tcc-pack", name="TCC Pack", tokens=100, price_eur="10.00"
        )
        self.order = TokenOrder.objects.create(
            wallet=self.wallet, package=self.package, tokens=100, amount_eur_cents=1000
        )
        self.url = reverse("chef_battle:token_checkout_cancel")

    def _order_status(self):
        self.order.refresh_from_db()
        return self.order.status

    def test_anonymous_cannot_cancel_order(self):
        response = self.client.get(f"{self.url}?order={self.order.pk}")
        self.assertEqual(response.status_code, 200)
        self.assertEqual(self._order_status(), "pending")

    def test_other_user_cannot_cancel_order(self):
        self.client.login(username="tcc-other", password="pw")
        response = self.client.get(f"{self.url}?order={self.order.pk}")
        self.assertEqual(response.status_code, 200)
        self.assertEqual(self._order_status(), "pending")

    def test_owner_can_cancel_own_order(self):
        self.client.login(username="tcc-owner", password="pw")
        response = self.client.get(f"{self.url}?order={self.order.pk}")
        self.assertEqual(response.status_code, 200)
        self.assertEqual(self._order_status(), "cancelled")

    def test_non_numeric_order_param_is_safe(self):
        self.client.login(username="tcc-owner", password="pw")
        response = self.client.get(f"{self.url}?order=abc")
        self.assertEqual(response.status_code, 200)
        self.assertEqual(self._order_status(), "pending")


@override_settings(SECURE_SSL_REDIRECT=False, CHEF_BATTLE_ENABLED=True)
class BattleChatSecurityTests(TestCase):
    """Anonymous chat: no impersonation of registered names; poll input hardened."""

    def setUp(self):
        from .models import BattleChatMessage
        self.BattleChatMessage = BattleChatMessage
        User = get_user_model()
        self.user_a = User.objects.create_user(username="chat-chef-a", password="pw")
        self.user_b = User.objects.create_user(username="chat-chef-b", password="pw")
        self.chef_a = RecipeAuthor.objects.create(user=self.user_a, name="Chat Chef A", slug="chat-chef-a")
        self.chef_b = RecipeAuthor.objects.create(user=self.user_b, name="Chat Chef B", slug="chat-chef-b")
        now = timezone.now()
        self.battle = Battle.objects.create(
            challenger=self.chef_a,
            opponent=self.chef_b,
            theme="Chat Theme",
            status=Battle.Status.ACTIVE,
            submission_deadline=now + timezone.timedelta(days=2),
            voting_deadline=now + timezone.timedelta(days=4),
            end_time=now + timezone.timedelta(days=4),
        )
        self.send_url = reverse("chef_battle:battle_chat_send", args=[self.battle.pk])
        self.poll_url = reverse("chef_battle:battle_chat_poll", args=[self.battle.pk])

    def test_anonymous_cannot_impersonate_username(self):
        self.client.post(self.send_url, {"body": "hello", "display_name": "chat-chef-a"})
        msg = self.BattleChatMessage.objects.get(battle=self.battle)
        self.assertEqual(msg.display_name, "Anonymous")

    def test_anonymous_cannot_impersonate_author_name(self):
        self.client.post(self.send_url, {"body": "hello", "display_name": "Chat Chef B"})
        msg = self.BattleChatMessage.objects.get(battle=self.battle)
        self.assertEqual(msg.display_name, "Anonymous")

    def test_anonymous_free_name_is_kept(self):
        self.client.post(self.send_url, {"body": "hello", "display_name": "RandomGuest42"})
        msg = self.BattleChatMessage.objects.get(battle=self.battle)
        self.assertEqual(msg.display_name, "RandomGuest42")

    def test_authenticated_name_not_overridden(self):
        self.client.login(username="chat-chef-a", password="pw")
        self.client.post(self.send_url, {"body": "hello", "display_name": "ignored"})
        msg = self.BattleChatMessage.objects.get(battle=self.battle)
        self.assertEqual(msg.display_name, "chat-chef-a")

    def test_chat_poll_non_numeric_since_is_safe(self):
        response = self.client.get(f"{self.poll_url}?since=abc")
        self.assertEqual(response.status_code, 200)


@override_settings(SECURE_SSL_REDIRECT=False, CHEF_BATTLE_ENABLED=False)
class ArenaDarkLaunchTests(TestCase):
    """With the flag OFF, every arena endpoint must 404 for the public
    (P00 contract: arena is gated by chef_battle_guard) while superusers
    keep dark-launch preview access."""

    def setUp(self):
        User = get_user_model()
        self.super_user = User.objects.create_superuser(
            username="adl-super", password="pw", email="adl@example.com"
        )
        RecipeAuthor.objects.create(user=self.super_user, name="ADL Super", slug="adl-super")

    def test_arena_page_hidden_from_anonymous(self):
        response = self.client.get(reverse("chef_battle:arena"))
        self.assertEqual(response.status_code, 404)

    def test_arena_state_hidden_from_anonymous(self):
        response = self.client.post(reverse("chef_battle:arena_state"))
        self.assertEqual(response.status_code, 404)

    def test_arena_blast_hidden_from_anonymous(self):
        response = self.client.get(reverse("chef_battle:arena_blast"))
        self.assertEqual(response.status_code, 404)

    def test_arena_ping_hidden_from_anonymous(self):
        response = self.client.post(reverse("chef_battle:arena_ping"))
        self.assertEqual(response.status_code, 404)

    def test_superuser_keeps_dark_launch_preview(self):
        self.client.login(username="adl-super", password="pw")
        response = self.client.get(reverse("chef_battle:arena"))
        self.assertEqual(response.status_code, 200)
        response = self.client.post(reverse("chef_battle:arena_state"))
        self.assertEqual(response.status_code, 200)

    def test_plain_author_hidden_from_arena_during_dark_launch(self):
        """Owner ruling 2026-07-21 (and the standing product contract): the
        Arena is not publicly released, so access during dark launch is
        STAFF/SUPERUSER ONLY. A plain registered author who is not staff must
        404 — the superseded v2.5.380 "any author may visit" rule no longer
        applies. This inverts the previous test that asserted a 200 here."""
        User = get_user_model()
        plain_user = User.objects.create_user(username="adl-plain-author", password="pw")
        RecipeAuthor.objects.create(user=plain_user, name="ADL Plain Author", slug="adl-plain-author")
        self.client.login(username="adl-plain-author", password="pw")

        response = self.client.get(reverse("chef_battle:arena"))
        self.assertEqual(response.status_code, 404)

    def test_authenticated_user_without_an_author_profile_still_hidden(self):
        """An ordinary logged-in account with no author profile is hidden
        during dark launch — same as a plain author now: staff/superuser
        only."""
        User = get_user_model()
        User.objects.create_user(username="adl-no-author", password="pw")
        self.client.login(username="adl-no-author", password="pw")

        response = self.client.get(reverse("chef_battle:arena"))
        self.assertEqual(response.status_code, 404)

    def test_arena_react_hidden_from_anonymous(self):
        """CF2: arena_react was public (rate-limited only); during dark launch
        it must 404 for anonymous, same gate as the arena it belongs to."""
        response = self.client.post(reverse("chef_battle:arena_react"))
        self.assertEqual(response.status_code, 404)

    def test_arena_react_hidden_from_plain_author(self):
        User = get_user_model()
        plain_user = User.objects.create_user(username="adl-react-author", password="pw")
        RecipeAuthor.objects.create(user=plain_user, name="ADL React Author", slug="adl-react-author")
        self.client.login(username="adl-react-author", password="pw")
        response = self.client.post(reverse("chef_battle:arena_react"))
        self.assertEqual(response.status_code, 404)

    def test_battle_chat_poll_hidden_from_anonymous(self):
        """CF3: battle_chat_poll had only a rate limit and leaked chat to
        anonymous. The visibility gate now fires before the battle lookup, so
        an anonymous visitor 404s even for a non-existent battle id."""
        response = self.client.get(
            reverse("chef_battle:battle_chat_poll", kwargs={"pk": 1})
        )
        self.assertEqual(response.status_code, 404)


@override_settings(SECURE_SSL_REDIRECT=False, CHEF_BATTLE_ENABLED=True)
class TokenChargebackServiceTests(TestCase):
    """handle_token_order_chargeback must run end-to-end without FieldError/TypeError.

    Regression: after the owner->chef fix, the clawback TokenTransaction was
    still built with a non-existent 'reason' kwarg and omitted the required
    tx_type/balance_after fields, so a real chargeback with token deduction
    crashed with TypeError and the chargeback lock never applied.
    """

    def setUp(self):
        from .models import TokenWallet, TokenPackage, TokenOrder, TokenLot, ChefBattleProfile
        User = get_user_model()
        self.user = User.objects.create_user(username="cb-buyer", password="pw")
        self.buyer = RecipeAuthor.objects.create(user=self.user, name="CB Buyer", slug="cb-buyer")
        ChefBattleProfile.objects.create(author=self.buyer)
        self.wallet = TokenWallet.objects.create(chef=self.buyer, balance=100)
        self.package = TokenPackage.objects.create(
            key="cb-pack", name="CB Pack", tokens=50, price_eur="5.00"
        )
        self.order = TokenOrder.objects.create(
            wallet=self.wallet, package=self.package, tokens=50,
            amount_eur_cents=500, status=TokenOrder.Status.COMPLETED,
        )
        TokenLot.objects.create(
            wallet=self.wallet, source_order=self.order,
            source_type=TokenLot.SourceType.PURCHASE,
            original_amount=50, remaining_amount=50,
        )
        TokenLot.objects.create(
            wallet=self.wallet, source_type=TokenLot.SourceType.LEGACY,
            original_amount=50, remaining_amount=50, origin_ambiguous=True,
        )

    def test_chargeback_runs_and_locks(self):
        from .services import handle_token_order_chargeback
        from .models import TokenOrder, TokenTransaction, LedgerEvent, ChefBattleProfile

        result = handle_token_order_chargeback(self.order.pk, chargeback=True)

        self.order.refresh_from_db()
        self.wallet.refresh_from_db()
        self.assertEqual(self.order.status, TokenOrder.Status.DISPUTED)
        self.assertEqual(self.wallet.balance, 50)  # 100 - 50 clawed back
        self.assertEqual(result["deducted_tokens"], 50)
        self.assertTrue(
            TokenTransaction.objects.filter(
                wallet=self.wallet,
                tx_type=TokenTransaction.TxType.REFUND,
                amount=-50,
            ).exists()
        )
        self.assertTrue(
            LedgerEvent.objects.filter(
                event_type=LedgerEvent.EventType.CHARGEBACK_LOCK
            ).exists()
        )
        profile = ChefBattleProfile.objects.get(author=self.buyer)
        self.assertTrue(profile.payout_blocked)

    def test_refund_deducts_capped_at_balance(self):
        from .services import handle_token_order_chargeback
        from .models import TokenOrder
        self.wallet.balance = 20
        self.wallet.save(update_fields=["balance"])
        result = handle_token_order_chargeback(self.order.pk, chargeback=False)
        self.order.refresh_from_db()
        self.wallet.refresh_from_db()
        self.assertEqual(self.order.status, TokenOrder.Status.REFUNDED)
        self.assertEqual(self.wallet.balance, 0)
        self.assertEqual(result["deducted_tokens"], 20)

    def test_a_second_clawback_event_does_not_deduct_twice(self):
        """F45, 2026-08-11: charge.refunded and charge.dispute.created are
        TWO DIFFERENT Stripe events - the webhook layer's event-id dedup
        does not catch a genuine second event for the same underlying
        charge. A refund followed by a dispute (or vice versa) used to claw
        back the full order amount a second time, eating into balance from
        OTHER, unrelated purchases - simulated here by topping the wallet
        back up between the two calls, as an unrelated purchase would."""
        from .services import handle_token_order_chargeback
        from .models import TokenOrder

        first = handle_token_order_chargeback(self.order.pk, chargeback=False)
        self.wallet.refresh_from_db()
        self.assertEqual(first["deducted_tokens"], 50)
        self.assertEqual(self.wallet.balance, 50)  # 100 - 50

        # An unrelated purchase tops the wallet back up.
        self.wallet.balance = 200
        self.wallet.save(update_fields=["balance"])

        second = handle_token_order_chargeback(self.order.pk, chargeback=True)
        self.order.refresh_from_db()
        self.wallet.refresh_from_db()
        self.assertEqual(
            second["deducted_tokens"], 0,
            "a second clawback event for an already-refunded order must not deduct again",
        )
        self.assertEqual(
            self.wallet.balance, 200,
            "the unrelated purchase's tokens must survive the second event untouched",
        )
        self.assertEqual(self.order.status, TokenOrder.Status.DISPUTED)

    def test_partial_refunds_claw_only_the_new_cumulative_delta(self):
        from .models import TokenOrder
        from .services import handle_token_order_chargeback

        first = handle_token_order_chargeback(
            self.order.pk, refunded_amount_cents=100,
        )
        self.wallet.refresh_from_db()
        self.order.refresh_from_db()
        self.assertEqual(self.order.status, TokenOrder.Status.PARTIALLY_REFUNDED)
        self.assertEqual(first["deducted_tokens"], 10)
        self.assertEqual(self.wallet.balance, 90)

        duplicate = handle_token_order_chargeback(
            self.order.pk, refunded_amount_cents=100,
        )
        self.assertEqual(duplicate["deducted_tokens"], 0)

        second = handle_token_order_chargeback(
            self.order.pk, refunded_amount_cents=250,
        )
        self.wallet.refresh_from_db()
        self.order.refresh_from_db()
        self.assertEqual(second["deducted_tokens"], 15)
        self.assertEqual(self.order.clawed_tokens, 25)
        self.assertEqual(self.wallet.balance, 75)

    def test_refunding_order_one_does_not_touch_gift_funded_by_order_two(self):
        from .models import (
            AppreciationGift, RewardRecord, TokenLot, TokenOrder,
            TokenPackage, TokenTransaction,
        )
        from .services import debit_tokens, handle_token_order_chargeback, send_appreciation_gift

        debit_tokens(
            self.buyer, 50, TokenTransaction.TxType.ARTIFACT_BOUGHT,
            "consume order one before the later purchase",
        )
        package_two = TokenPackage.objects.create(
            key="cb-pack-two", name="CB Pack Two", tokens=50, price_eur="5.00",
        )
        order_two = TokenOrder.objects.create(
            wallet=self.wallet, package=package_two, tokens=50,
            amount_eur_cents=500, status=TokenOrder.Status.COMPLETED,
        )
        self.wallet.balance += 50
        self.wallet.save(update_fields=["balance"])
        TokenLot.objects.create(
            wallet=self.wallet, source_order=order_two,
            source_type=TokenLot.SourceType.PURCHASE,
            original_amount=50, remaining_amount=50,
        )
        recipient_user = get_user_model().objects.create_user("cb-recipient", password="pw")
        recipient = RecipeAuthor.objects.create(
            user=recipient_user, name="CB Recipient", slug="cb-recipient",
        )
        gift = send_appreciation_gift(
            sender_user=self.user, recipient=recipient, gift_type="coffee",
        )
        reward = RewardRecord.objects.get(related_gift=gift, recipient=recipient)

        handle_token_order_chargeback(self.order.pk, chargeback=False)

        gift.refresh_from_db()
        reward.refresh_from_db()
        self.assertFalse(gift.is_flagged)
        self.assertEqual(reward.status, RewardRecord.Status.PENDING)
        self.assertTrue(AppreciationGift.objects.filter(pk=gift.pk).exists())


@override_settings(SECURE_SSL_REDIRECT=False, CHEF_BATTLE_ENABLED=True)
class SeasonEngineTests(TestCase):
    """Phase 6 Seasons engine: lifecycle + standings snapshot + score reset."""

    def setUp(self):
        from .models import ChefBattleProfile
        User = get_user_model()
        self.chefs = []
        for i, score in enumerate([30, 10, 20]):  # deliberately unordered
            u = User.objects.create_user(username=f"season-chef-{i}", password="pw")
            a = RecipeAuthor.objects.create(user=u, name=f"Season Chef {i}", slug=f"season-chef-{i}")
            ChefBattleProfile.objects.create(author=a, seasonal_score=score, wins=score // 10)
            self.chefs.append(a)
        self.now = timezone.now()

    def _mk(self, name="S1", start_delta=-1, end_delta=1, **kw):
        from .season_service import create_season
        return create_season(
            name=name,
            starts_at=self.now + timezone.timedelta(days=start_delta),
            ends_at=self.now + timezone.timedelta(days=end_delta),
            **kw,
        )

    def test_create_requires_end_after_start(self):
        from .season_service import create_season
        with self.assertRaises(ValueError):
            create_season(name="bad", starts_at=self.now, ends_at=self.now - timezone.timedelta(days=1))

    def test_only_one_active_season(self):
        from .season_service import activate_season
        s1 = self._mk("S1", activate=True)
        s2 = self._mk("S2")
        with self.assertRaises(ValueError):
            activate_season(s2)

    def test_ended_season_cannot_reactivate(self):
        from .models import Season
        from .season_service import activate_season
        s = self._mk("S1", activate=True)
        s.status = Season.Status.ENDED
        s.save(update_fields=["status"])
        with self.assertRaises(ValueError):
            activate_season(s)

    def test_get_active_season(self):
        from .season_service import get_active_season
        self.assertIsNone(get_active_season())
        s = self._mk("S1", activate=True)
        self.assertEqual(get_active_season(), s)

    def test_close_snapshots_ranked_standings_and_resets(self):
        from .models import Season, SeasonStanding, ChefBattleProfile
        from .season_service import close_season
        s = self._mk("S1", activate=True)
        result = close_season(s)

        s.refresh_from_db()
        self.assertEqual(s.status, Season.Status.ENDED)
        self.assertEqual(result["standings_recorded"], 3)
        # Champion is the highest seasonal_score (30).
        self.assertEqual(result["champion"], self.chefs[0])

        standings = list(SeasonStanding.objects.filter(season=s).order_by("rank_position"))
        self.assertEqual([st.rank_position for st in standings], [1, 2, 3])
        self.assertEqual([st.score for st in standings], [30, 20, 10])
        self.assertEqual(standings[0].chef, self.chefs[0])

        # Live scores are reset for the next season.
        self.assertEqual(
            ChefBattleProfile.objects.filter(seasonal_score__gt=0).count(), 0
        )

    def test_close_only_active(self):
        from .season_service import close_season
        s = self._mk("S1")  # upcoming, not active
        with self.assertRaises(ValueError):
            close_season(s)

    def test_roll_seasons_command_closes_and_activates(self):
        from django.core.management import call_command
        from .models import Season
        # An active season already past its end, and an upcoming one in window.
        past = self._mk("Past", start_delta=-10, end_delta=-1, activate=True)
        upcoming = self._mk("Next", start_delta=-1, end_delta=30)
        call_command("roll_seasons")
        past.refresh_from_db()
        upcoming.refresh_from_db()
        self.assertEqual(past.status, Season.Status.ENDED)
        self.assertEqual(upcoming.status, Season.Status.ACTIVE)

    def test_leaderboard_shows_active_season_name(self):
        # With CHEF_BATTLE_ENABLED the leaderboard is public (no login needed).
        self._mk("Autumn Cup", activate=True)
        resp = self.client.get(reverse("chef_battle:season_leaderboard"))
        self.assertEqual(resp.status_code, 200)
        self.assertContains(resp, "Autumn Cup")


@override_settings(SECURE_SSL_REDIRECT=False, CHEF_BATTLE_ENABLED=True)
class SeasonSignalTests(TestCase):
    """Phase 6 integration contract: season_started / season_ended fire for factions."""

    def setUp(self):
        from .models import ChefBattleProfile
        User = get_user_model()
        u = User.objects.create_user(username="sig-chef", password="pw")
        self.author = RecipeAuthor.objects.create(user=u, name="Sig Chef", slug="sig-chef")
        ChefBattleProfile.objects.create(author=self.author, seasonal_score=15, wins=1)
        self.now = timezone.now()

    def _mk(self, activate=False):
        from .season_service import create_season
        return create_season(
            name="Sig Season",
            starts_at=self.now - timezone.timedelta(days=1),
            ends_at=self.now + timezone.timedelta(days=1),
            activate=activate,
        )

    def test_season_started_signal_fires(self):
        from .season_signals import season_started
        from .season_service import activate_season
        received = {}

        def receiver(sender, season, **kwargs):
            received["season"] = season

        season_started.connect(receiver)
        try:
            s = self._mk(activate=False)
            activate_season(s)
        finally:
            season_started.disconnect(receiver)
        self.assertEqual(received.get("season"), s)

    def test_season_ended_signal_fires_with_ranked_standings(self):
        from .season_signals import season_ended
        from .season_service import close_season
        received = {}

        def receiver(sender, season, standings, **kwargs):
            received["season"] = season
            received["standings"] = list(standings)

        season_ended.connect(receiver)
        try:
            s = self._mk(activate=True)
            close_season(s)
        finally:
            season_ended.disconnect(receiver)
        self.assertEqual(received.get("season"), s)
        self.assertEqual(len(received.get("standings", [])), 1)
        self.assertEqual(received["standings"][0].rank_position, 1)
        self.assertEqual(received["standings"][0].chef, self.author)

    def test_ended_receiver_exception_rolls_back_close(self):
        from .models import Season, SeasonStanding
        from .season_signals import season_ended
        from .season_service import close_season

        def boom(sender, season, standings, **kwargs):
            raise RuntimeError("faction finalisation failed")

        season_ended.connect(boom)
        try:
            s = self._mk(activate=True)
            with self.assertRaises(RuntimeError):
                close_season(s)
        finally:
            season_ended.disconnect(boom)
        # The close was rolled back: season still active, no standings, score intact.
        s.refresh_from_db()
        self.assertEqual(s.status, Season.Status.ACTIVE)
        self.assertEqual(SeasonStanding.objects.filter(season=s).count(), 0)
        from .models import ChefBattleProfile
        self.assertEqual(ChefBattleProfile.objects.get(author=self.author).seasonal_score, 15)


@override_settings(SECURE_SSL_REDIRECT=False, CHEF_BATTLE_ENABLED=True)
class SeasonCommittedSignalTests(TestCase):
    """season_ended_committed fires post-commit for heavy/fallible faction reward work."""

    def setUp(self):
        from .models import ChefBattleProfile
        User = get_user_model()
        u = User.objects.create_user(username="cs-chef", password="pw")
        self.author = RecipeAuthor.objects.create(user=u, name="CS Chef", slug="cs-chef")
        ChefBattleProfile.objects.create(author=self.author, seasonal_score=20, wins=2)
        self.now = timezone.now()

    def _active_season(self):
        from .season_service import create_season
        return create_season(
            name="CS Season",
            starts_at=self.now - timezone.timedelta(days=1),
            ends_at=self.now + timezone.timedelta(days=1),
            activate=True,
        )

    def test_committed_signal_fires_after_commit(self):
        from .season_signals import season_ended_committed
        from .season_service import close_season
        received = {}

        def receiver(sender, season, **kwargs):
            # By the time this runs, the close is committed and durable.
            received["season"] = season
            received["status"] = type(season).objects.get(pk=season.pk).status

        season_ended_committed.connect(receiver)
        try:
            s = self._active_season()
            with self.captureOnCommitCallbacks(execute=True):
                close_season(s)
        finally:
            season_ended_committed.disconnect(receiver)
        from .models import Season
        self.assertEqual(received.get("season"), s)
        self.assertEqual(received.get("status"), Season.Status.ENDED)

    def test_committed_signal_not_fired_on_rollback(self):
        from .season_signals import season_ended, season_ended_committed
        from .season_service import close_season
        fired = {"committed": False}

        def in_txn_boom(sender, season, standings, **kwargs):
            raise RuntimeError("in-transaction receiver failed")

        def committed_receiver(sender, season, **kwargs):
            fired["committed"] = True

        season_ended.connect(in_txn_boom)
        season_ended_committed.connect(committed_receiver)
        try:
            s = self._active_season()
            with self.assertRaises(RuntimeError):
                with self.captureOnCommitCallbacks(execute=True):
                    close_season(s)
        finally:
            season_ended.disconnect(in_txn_boom)
            season_ended_committed.disconnect(committed_receiver)
        # In-txn failure rolled back the close, so post-commit never fired.
        self.assertFalse(fired["committed"])


@override_settings(SECURE_SSL_REDIRECT=False, CHEF_BATTLE_ENABLED=True)
class SeasonLifecycleIsLockedAgainstDoubleFireTests(TestCase):
    """F24, 2026-08-11: activate_season/close_season took no row lock, so two
    overlapping roll_seasons runs (the command documents no mutex, same as
    every other cron sweep in this app) could both pass the status check on
    the SAME season before either committed - close_season would snapshot
    standings and reset seasonal_score twice and fire season_ended/
    season_ended_committed a second time, which issue real SeasonReward rows.
    Asserted on the SQL and by simulating the race deterministically (call
    once, then call again with the caller's now-stale object), same
    convention as NoShowSweepIsLockedAgainstDoubleAwardTests and
    DoubleAcceptRaceReturnsFriendlyMessageTests - not by racing real threads
    for a window that proves nothing."""

    def setUp(self):
        from .models import ChefBattleProfile
        User = get_user_model()
        u = User.objects.create_user(username="f24-chef", password="pw")
        self.author = RecipeAuthor.objects.create(user=u, name="F24 Chef", slug="f24-chef")
        ChefBattleProfile.objects.create(author=self.author, seasonal_score=20, wins=2)
        self.now = timezone.now()

    def _active_season(self, name="F24 Season"):
        from .season_service import create_season
        return create_season(
            name=name,
            starts_at=self.now - timezone.timedelta(days=1),
            ends_at=self.now + timezone.timedelta(days=1),
            activate=True,
        )

    def test_close_season_locks_the_row(self):
        from django.test.utils import CaptureQueriesContext
        from django.db import connection
        from .season_service import close_season

        s = self._active_season()
        with CaptureQueriesContext(connection) as ctx:
            close_season(s)
        locking = [q["sql"] for q in ctx.captured_queries if "FOR UPDATE" in q["sql"].upper()]
        self.assertTrue(locking, "close_season must take a row lock before snapshotting standings")

    def test_second_close_on_a_stale_object_does_not_double_process(self):
        from .season_signals import season_ended_committed
        from .season_service import close_season
        from .models import Season, SeasonStanding

        s = self._active_season()
        # A second overlapping cron run would have loaded its OWN copy of
        # this row before either call committed - fetch that independent,
        # still-ACTIVE copy now, before the first close runs.
        stale_copy = Season.objects.get(pk=s.pk)
        fire_count = {"n": 0}

        def receiver(sender, season, **kwargs):
            fire_count["n"] += 1

        season_ended_committed.connect(receiver)
        try:
            with self.captureOnCommitCallbacks(execute=True):
                first = close_season(s)
            self.assertEqual(stale_copy.status, Season.Status.ACTIVE)
            with self.captureOnCommitCallbacks(execute=True):
                second = close_season(stale_copy)
        finally:
            season_ended_committed.disconnect(receiver)

        self.assertEqual(fire_count["n"], 1, "season_ended_committed must fire only once per close")
        self.assertEqual(first["standings_recorded"], second["standings_recorded"])
        self.assertEqual(
            SeasonStanding.objects.filter(season_id=s.pk).count(),
            first["standings_recorded"],
            "a second racing close must not duplicate the standings snapshot",
        )

    def test_activate_season_locks_the_row(self):
        from django.test.utils import CaptureQueriesContext
        from django.db import connection
        from .season_service import create_season, activate_season

        s = create_season(
            name="F24 Upcoming",
            starts_at=self.now + timezone.timedelta(days=10),
            ends_at=self.now + timezone.timedelta(days=20),
        )
        with CaptureQueriesContext(connection) as ctx:
            activate_season(s)
        locking = [q["sql"] for q in ctx.captured_queries if "FOR UPDATE" in q["sql"].upper()]
        self.assertTrue(locking, "activate_season must take a row lock before flipping status")

    def test_second_activate_on_a_stale_object_is_a_harmless_noop(self):
        from .season_signals import season_started
        from .season_service import create_season, activate_season
        from .models import Season

        s = create_season(
            name="F24 Upcoming 2",
            starts_at=self.now + timezone.timedelta(days=10),
            ends_at=self.now + timezone.timedelta(days=20),
        )
        # Independent copy, fetched before either call - what a second
        # overlapping cron run's own in-memory object would look like.
        stale_copy = Season.objects.get(pk=s.pk)
        fire_count = {"n": 0}

        def receiver(sender, season, **kwargs):
            fire_count["n"] += 1

        season_started.connect(receiver)
        try:
            activate_season(s)
            self.assertEqual(stale_copy.status, Season.Status.UPCOMING)
            activate_season(stale_copy)
        finally:
            season_started.disconnect(receiver)
        self.assertEqual(fire_count["n"], 1, "season_started must fire only once per activation")


class RelinkArtifactImagesCommandTests(TestCase):
    """Recovery command: re-link blank Artifact.image to on-disk files by PK."""

    def test_relinks_blank_image_from_disk_file(self):
        import os, tempfile
        from django.conf import settings
        from django.core.management import call_command
        from .models import Artifact

        with tempfile.TemporaryDirectory() as media_root:
            with override_settings(MEDIA_ROOT=media_root):
                a = Artifact.objects.create(name="Recovery Knife", rarity=Artifact.Rarity.RARE)
                self.assertEqual(a.image, "")
                # Also seed an already-imaged artifact and one with no file.
                b = Artifact.objects.create(name="No File Relic")

                art_dir = os.path.join(media_root, "chef_battle", "artifacts")
                os.makedirs(art_dir, exist_ok=True)
                # Canonical file + a deduped variant for the same pk — canonical wins.
                fname = f"recovery-knife-{a.pk}.png"
                with open(os.path.join(art_dir, fname), "wb") as fh:
                    fh.write(b"\x89PNG\r\n")
                with open(os.path.join(art_dir, f"recovery-knife-{a.pk}_zZ9.png"), "wb") as fh:
                    fh.write(b"\x89PNG\r\n")

                call_command("relink_artifact_images")

                a.refresh_from_db()
                b.refresh_from_db()
                self.assertEqual(a.image.name, f"chef_battle/artifacts/{fname}")
                self.assertEqual(b.image, "")  # no matching file -> untouched

                # Idempotent: a second run leaves the linked one as-is.
                call_command("relink_artifact_images")
                a.refresh_from_db()
                self.assertEqual(a.image.name, f"chef_battle/artifacts/{fname}")


