class FactionSchemaTests(TestCase):
    """Phase 6 Culinary Factions — seed + model constraints."""

    def test_seed_counts(self):
        from .models import Faction
        self.assertEqual(Faction.objects.filter(kind="cuisine").count(), 10)
        self.assertEqual(Faction.objects.filter(kind="specialty").count(), 18)
        # Slugs are unique per kind; a name resolves to exactly one faction per kind.
        italian = Faction.objects.get(kind="cuisine", slug="italian")
        self.assertEqual(italian.name, "Italian")
        self.assertTrue(italian.crest_icon)

    def test_one_membership_per_kind_per_season(self):
        from django.db import IntegrityError, transaction
        from .models import Faction, FactionMembership, Season
        User = get_user_model()
        u = User.objects.create_user("fac-chef", password="pw")
        chef = RecipeAuthor.objects.create(user=u, name="Fac Chef", slug="fac-chef")
        now = timezone.now()
        season = Season.objects.create(
            name="FS", starts_at=now, ends_at=now + timezone.timedelta(days=30),
            status=Season.Status.ACTIVE,
        )
        italian = Faction.objects.get(kind="cuisine", slug="italian")
        french = Faction.objects.get(kind="cuisine", slug="french")
        FactionMembership.objects.create(chef=chef, faction=italian, faction_kind="cuisine", season=season)
        # Second cuisine membership in the same season must be rejected.
        with self.assertRaises(IntegrityError):
            with transaction.atomic():
                FactionMembership.objects.create(chef=chef, faction=french, faction_kind="cuisine", season=season)

    def test_contribution_ledger_and_standing(self):
        from .models import Faction, FactionContribution, FactionSeasonStanding, Season
        from django.db.models import Sum
        User = get_user_model()
        u = User.objects.create_user("fac-chef2", password="pw")
        chef = RecipeAuthor.objects.create(user=u, name="Fac Chef2", slug="fac-chef2")
        now = timezone.now()
        season = Season.objects.create(
            name="FS2", starts_at=now, ends_at=now + timezone.timedelta(days=30),
            status=Season.Status.ACTIVE,
        )
        bbq = Faction.objects.get(kind="specialty", slug="bbq")
        FactionContribution.objects.create(chef=chef, faction=bbq, faction_kind="specialty", season=season, points=5)
        FactionContribution.objects.create(chef=chef, faction=bbq, faction_kind="specialty", season=season, points=3)
        total = FactionContribution.objects.filter(faction=bbq, season=season).aggregate(t=Sum("points"))["t"]
        self.assertEqual(total, 8)
        # Standing row is unique per (faction, season).
        FactionSeasonStanding.objects.create(faction=bbq, season=season, total_points=8)
        from django.db import IntegrityError, transaction
        with self.assertRaises(IntegrityError):
            with transaction.atomic():
                FactionSeasonStanding.objects.create(faction=bbq, season=season, total_points=8)


class FactionNormalizationTests(TestCase):
    """Phase 6: normalized_score math + live faction leaderboard."""

    def test_normalized_score_math(self):
        from .faction_service import normalized_score
        self.assertEqual(normalized_score(0, 5), 0.0)
        self.assertEqual(normalized_score(100, 0), 0.0)   # no div-by-zero
        self.assertEqual(normalized_score(-5, 5), 0.0)
        self.assertAlmostEqual(normalized_score(100, 4), 50.0)   # 100/2
        self.assertAlmostEqual(normalized_score(90, 9), 30.0)    # 90/3
        # Size alone can't win: 200 pts over 25 members (40) loses to 100 over 4 (50).
        self.assertLess(normalized_score(200, 25), normalized_score(100, 4))

    def test_leaderboard_ranks_and_floor(self):
        from .faction_service import get_faction_leaderboard
        from .models import Faction, FactionContribution, Season, FACTION_RANK_MEMBER_FLOOR
        User = get_user_model()
        now = timezone.now()
        season = Season.objects.create(
            name="LB", starts_at=now, ends_at=now + timezone.timedelta(days=30),
            status=Season.Status.ACTIVE,
        )
        italian = Faction.objects.get(kind="cuisine", slug="italian")
        french = Faction.objects.get(kind="cuisine", slug="french")

        def seed(faction, n_members, pts_each):
            for i in range(n_members):
                u = User.objects.create_user(f"lb-{faction.slug}-{i}", password="pw")
                chef = RecipeAuthor.objects.create(user=u, name=f"{faction.slug}{i}", slug=f"lb-{faction.slug}-{i}")
                FactionContribution.objects.create(
                    chef=chef, faction=faction, faction_kind="cuisine", season=season, points=pts_each
                )

        # Italian: 5 members x 20 = 100 total, active 5 -> 100/sqrt(5) ~= 44.7
        seed(italian, FACTION_RANK_MEMBER_FLOOR, 20)
        # French: only 4 members -> below the >=5 floor, excluded from the board
        seed(french, FACTION_RANK_MEMBER_FLOOR - 1, 50)

        board = get_faction_leaderboard(season, "cuisine")
        slugs = [r["faction"].slug for r in board]
        self.assertIn("italian", slugs)
        self.assertNotIn("french", slugs)   # under the active-member floor
        self.assertEqual(board[0]["rank_position"], 1)
        self.assertEqual(board[0]["active_member_count"], FACTION_RANK_MEMBER_FLOOR)


@override_settings(CHEF_BATTLE_ENABLED=True)
class FactionEarnPathTests(TestCase):
    """Phase 6: award_faction_contribution + its uncapped insertion in award_moves."""

    def setUp(self):
        from .models import ChefBattleProfile, Faction, FactionMembership, Season
        User = get_user_model()
        u = User.objects.create_user("fep-chef", password="pw")
        self.chef = RecipeAuthor.objects.create(user=u, name="FEP Chef", slug="fep-chef")
        self.profile = ChefBattleProfile.objects.create(author=self.chef, enrolled_at=timezone.now())
        now = timezone.now()
        self.season = Season.objects.create(
            name="FEP", starts_at=now - timezone.timedelta(days=1),
            ends_at=now + timezone.timedelta(days=30), status=Season.Status.ACTIVE,
        )
        self.italian = Faction.objects.get(kind="cuisine", slug="italian")
        self.bbq = Faction.objects.get(kind="specialty", slug="bbq")
        FactionMembership.objects.create(chef=self.chef, faction=self.italian, faction_kind="cuisine", season=self.season)
        FactionMembership.objects.create(chef=self.chef, faction=self.bbq, faction_kind="specialty", season=self.season)

    def _points(self):
        from .models import FactionContribution
        from django.db.models import Sum
        return {
            "cuisine": FactionContribution.objects.filter(faction=self.italian, season=self.season).aggregate(t=Sum("points"))["t"] or 0,
            "specialty": FactionContribution.objects.filter(faction=self.bbq, season=self.season).aggregate(t=Sum("points"))["t"] or 0,
            "rows": FactionContribution.objects.filter(chef=self.chef, season=self.season).count(),
        }

    def test_award_writes_both_axes(self):
        from .faction_service import award_faction_contribution
        n = award_faction_contribution(self.chef, 5)
        self.assertEqual(n, 2)  # one cuisine + one specialty row
        p = self._points()
        self.assertEqual(p["cuisine"], 5)
        self.assertEqual(p["specialty"], 5)

    def test_noop_without_membership(self):
        from .faction_service import award_faction_contribution
        from .models import FactionMembership
        FactionMembership.objects.all().delete()
        self.assertEqual(award_faction_contribution(self.chef, 5), 0)

    def test_noop_without_active_season(self):
        from .faction_service import award_faction_contribution
        from .models import Season
        self.season.status = Season.Status.ENDED
        self.season.save(update_fields=["status"])
        self.assertEqual(award_faction_contribution(self.chef, 5), 0)

    def test_award_moves_triggers_faction_points(self):
        from .energy_service import award_moves
        award_moves(self.chef, 3, "recipe_published")
        p = self._points()
        self.assertEqual(p["rows"], 2)
        self.assertEqual(p["cuisine"], 3)

    def test_faction_points_uncapped_even_when_moves_capped(self):
        from .energy_service import award_moves, ENERGY_CAP
        from .models import ChefBattleProfile
        # Max out the moves wallet so award_moves' ENERGY_CAP early-return trips.
        ChefBattleProfile.objects.filter(pk=self.profile.pk).update(battle_moves=ENERGY_CAP)
        award_moves(self.chef, 5, "recipe_published")
        self.profile.refresh_from_db()
        self.assertEqual(self.profile.battle_moves, ENERGY_CAP)  # moves stayed capped
        p = self._points()
        self.assertEqual(p["cuisine"], 5)   # faction points STILL credited
        self.assertEqual(p["specialty"], 5)

    def test_admin_adjustment_does_not_feed_factions(self):
        from .energy_service import award_moves
        award_moves(self.chef, 10, "admin_adjustment")
        self.assertEqual(self._points()["rows"], 0)


@override_settings(CHEF_BATTLE_ENABLED=True)
class FactionSeasonReceiverTests(TestCase):
    """Phase 6: season_started carryover + season_ended standings finalisation."""

    def _chef(self, tag):
        from .models import ChefBattleProfile
        User = get_user_model()
        u = User.objects.create_user(f"fsr-{tag}", password="pw")
        chef = RecipeAuthor.objects.create(user=u, name=f"FSR {tag}", slug=f"fsr-{tag}")
        ChefBattleProfile.objects.create(author=chef, enrolled_at=timezone.now())
        return chef

    def test_season_started_opens_standings_and_carries_membership(self):
        from .models import Faction, FactionMembership, FactionSeasonStanding, Season
        from .season_service import create_season, activate_season
        now = timezone.now()
        prior = Season.objects.create(
            name="Prior", starts_at=now - timezone.timedelta(days=60),
            ends_at=now - timezone.timedelta(days=30), status=Season.Status.ENDED,
        )
        italian = Faction.objects.get(kind="cuisine", slug="italian")
        chef = self._chef("carry")
        FactionMembership.objects.create(chef=chef, faction=italian, faction_kind="cuisine", season=prior)

        new = create_season(
            name="New", starts_at=now - timezone.timedelta(days=1),
            ends_at=now + timezone.timedelta(days=30),
        )
        activate_season(new)  # fires season_started -> receiver

        self.assertTrue(
            FactionMembership.objects.filter(chef=chef, season=new, faction=italian).exists()
        )
        self.assertEqual(FactionSeasonStanding.objects.filter(season=new).count(), 28)

    def test_season_ended_finalizes_standings(self):
        from .models import Faction, FactionContribution, FactionSeasonStanding, FACTION_RANK_MEMBER_FLOOR
        from .season_service import create_season, close_season
        now = timezone.now()
        season = create_season(
            name="Fin", starts_at=now - timezone.timedelta(days=1),
            ends_at=now + timezone.timedelta(days=1), activate=True,
        )
        italian = Faction.objects.get(kind="cuisine", slug="italian")
        for i in range(FACTION_RANK_MEMBER_FLOOR):
            chef = self._chef(f"fin{i}")
            FactionContribution.objects.create(
                chef=chef, faction=italian, faction_kind="cuisine", season=season, points=10
            )
        close_season(season)  # fires season_ended -> finalize (in Bolt's txn)

        st = FactionSeasonStanding.objects.get(faction=italian, season=season)
        self.assertEqual(st.total_points, FACTION_RANK_MEMBER_FLOOR * 10)
        self.assertEqual(st.active_member_count, FACTION_RANK_MEMBER_FLOOR)
        self.assertEqual(st.rank_position, 1)
        self.assertTrue(st.rewards_pending)


@override_settings(CHEF_BATTLE_ENABLED=True)
class FactionBattleGateTests(TestCase):
    """Phase 6: battle-derived faction points — same-faction=0 + per-opponent cap."""

    def setUp(self):
        from .models import ChefBattleProfile, Faction, FactionMembership, Season
        User = get_user_model()
        self.now = timezone.now()
        self.season = Season.objects.create(
            name="BG", starts_at=self.now - timezone.timedelta(days=2),
            ends_at=self.now + timezone.timedelta(days=30), status=Season.Status.ACTIVE,
        )
        self.italian = Faction.objects.get(kind="cuisine", slug="italian")
        self.french = Faction.objects.get(kind="cuisine", slug="french")
        self.bbq = Faction.objects.get(kind="specialty", slug="bbq")
        self.grill = Faction.objects.get(kind="specialty", slug="grill")

        def mk(tag, cuisine, specialty):
            u = User.objects.create_user(f"bg-{tag}", password="pw")
            chef = RecipeAuthor.objects.create(user=u, name=f"BG {tag}", slug=f"bg-{tag}")
            ChefBattleProfile.objects.create(author=chef, enrolled_at=self.now)
            FactionMembership.objects.create(chef=chef, faction=cuisine, faction_kind="cuisine", season=self.season)
            FactionMembership.objects.create(chef=chef, faction=specialty, faction_kind="specialty", season=self.season)
            return chef

        self.chef = mk("chef", self.italian, self.bbq)
        self.opp_samebbq = mk("oppbbq", self.french, self.bbq)      # diff cuisine, SAME specialty
        self.opp_diff = mk("oppdiff", self.french, self.grill)      # both different

    def _battle(self, a, b, status="active"):
        from .models import Battle
        return Battle.objects.create(
            challenger=a, opponent=b, theme="BG", status=status, start_time=self.now,
            submission_deadline=self.now + timezone.timedelta(days=2),
            voting_deadline=self.now + timezone.timedelta(days=4),
            end_time=self.now + timezone.timedelta(days=5),
        )

    def test_same_faction_axis_blocked(self):
        from .faction_service import award_battle_faction_contribution
        from .models import FactionContribution
        battle = self._battle(self.chef, self.opp_samebbq)
        n = award_battle_faction_contribution(self.chef, self.opp_samebbq, 5, battle=battle)
        self.assertEqual(n, 1)  # cuisine (Italian vs French) awarded; specialty (BBQ==BBQ) blocked
        self.assertTrue(FactionContribution.objects.filter(chef=self.chef, faction=self.italian).exists())
        self.assertFalse(FactionContribution.objects.filter(chef=self.chef, faction=self.bbq).exists())

    def test_both_axes_awarded_when_all_different(self):
        from .faction_service import award_battle_faction_contribution
        battle = self._battle(self.chef, self.opp_diff)
        n = award_battle_faction_contribution(self.chef, self.opp_diff, 5, battle=battle)
        self.assertEqual(n, 2)

    def test_per_opponent_cap(self):
        from .faction_service import award_battle_faction_contribution
        # 3 completed battles already exist between this pair this season.
        for _ in range(3):
            self._battle(self.chef, self.opp_diff, status="completed")
        battle4 = self._battle(self.chef, self.opp_diff)
        n = award_battle_faction_contribution(self.chef, self.opp_diff, 5, battle=battle4)
        self.assertEqual(n, 0)  # cap reached -> both axes blocked


@override_settings(CHEF_BATTLE_ENABLED=True)
class FactionRewardTests(TestCase):
    """Phase 6: non-cash season rewards — Legendary artifact + Hall-of-Fame record."""

    def test_champion_gets_legendary_and_seasonreward_record(self):
        from .models import (
            Artifact, ChefArtifact, ChefBattleProfile, Faction, FactionContribution,
            FactionSeasonStanding, SeasonReward, FACTION_RANK_MEMBER_FLOOR,
        )
        from .season_service import create_season, close_season
        Artifact.objects.create(name="Ancient Champion Relic", rarity=Artifact.Rarity.LEGENDARY)
        User = get_user_model()
        now = timezone.now()
        season = create_season(
            name="Rwd", starts_at=now - timezone.timedelta(days=1),
            ends_at=now + timezone.timedelta(days=1), activate=True,
        )
        italian = Faction.objects.get(kind="cuisine", slug="italian")
        chefs = []
        for i in range(FACTION_RANK_MEMBER_FLOOR):
            u = User.objects.create_user(f"rw-{i}", password="pw")
            chef = RecipeAuthor.objects.create(user=u, name=f"RW {i}", slug=f"rw-{i}")
            ChefBattleProfile.objects.create(author=chef, enrolled_at=now)
            FactionContribution.objects.create(chef=chef, faction=italian, faction_kind="cuisine", season=season, points=10)
            chefs.append(chef)

        with self.captureOnCommitCallbacks(execute=True):
            close_season(season)

        st = FactionSeasonStanding.objects.get(faction=italian, season=season)
        self.assertEqual(st.rank_position, 1)
        self.assertFalse(st.rewards_pending)  # rewards issued
        for chef in chefs:
            self.assertTrue(
                ChefArtifact.objects.filter(chef=chef, artifact__rarity="legendary").exists(),
                f"{chef} should have a legendary artifact",
            )
            self.assertTrue(
                SeasonReward.objects.filter(chef=chef, faction=italian, season=season, placement=1).exists()
            )

    def test_non_champion_faction_gets_no_rewards(self):
        from .models import Artifact, ChefArtifact, ChefBattleProfile, Faction, FactionContribution, SeasonReward, FACTION_RANK_MEMBER_FLOOR
        from .season_service import create_season, close_season
        Artifact.objects.create(name="Relic2", rarity=Artifact.Rarity.LEGENDARY)
        User = get_user_model()
        now = timezone.now()
        season = create_season(name="R2", starts_at=now - timezone.timedelta(days=1),
                               ends_at=now + timezone.timedelta(days=1), activate=True)
        italian = Faction.objects.get(kind="cuisine", slug="italian")
        french = Faction.objects.get(kind="cuisine", slug="french")
        # Italian wins (10 pts each), French is a distant second (1 pt each) — both >=5 members.
        for i in range(FACTION_RANK_MEMBER_FLOOR):
            for fac, pts, tag in ((italian, 10, "it"), (french, 1, "fr")):
                u = User.objects.create_user(f"r2-{tag}-{i}", password="pw")
                chef = RecipeAuthor.objects.create(user=u, name=f"R2 {tag}{i}", slug=f"r2-{tag}-{i}")
                ChefBattleProfile.objects.create(author=chef, enrolled_at=now)
                FactionContribution.objects.create(chef=chef, faction=fac, faction_kind="cuisine", season=season, points=pts)
        with self.captureOnCommitCallbacks(execute=True):
            close_season(season)
        # Only Italian (rank 1) chefs got rewards; French (rank 2) did not.
        self.assertTrue(SeasonReward.objects.filter(faction=italian, season=season).exists())
        self.assertFalse(SeasonReward.objects.filter(faction=french, season=season).exists())


