class ClanScoringTests(TestCase):
    """Clan ledger, leaderboard (raw-sum + member floor), winner & champion
    selectors, one-active-clan constraint, and season-end standing finalisation."""

    def setUp(self):
        from datetime import timedelta
        from .models import Season, Faction
        User = get_user_model()
        self.season = Season.objects.create(
            name="Clan S1",
            starts_at=timezone.now() - timedelta(days=1),
            ends_at=timezone.now() + timedelta(days=30),
            status=Season.Status.ACTIVE,
        )
        self.cat = Faction.objects.create(kind=Faction.Kind.CUISINE, name="ItalianClan", slug="italian-clan-t")
        self._User = User

    def _chef(self, n):
        u = self._User.objects.create_user(f"clanchef-{n}", password="pw")
        return RecipeAuthor.objects.create(user=u, name=f"Clan Chef {n}", slug=f"clan-chef-{n}")

    def _clan(self, name, founder, approved=True):
        from django.utils.text import slugify
        from .models import Clan
        c = Clan.objects.create(
            founder=founder, name=name, slug=slugify(name),
            moderation_status=Clan.Moderation.APPROVED if approved else Clan.Moderation.PENDING,
        )
        c.categories.add(self.cat)
        return c

    def _join(self, clan, chef, role=None):
        from .models import ClanMembership
        return ClanMembership.objects.create(
            clan=clan, chef=chef,
            role=role or ClanMembership.Role.MEMBER,
            status=ClanMembership.Status.ACTIVE,
        )

    def _populate(self, clan, per_chef_points):
        """Create len(per_chef_points) active members, each with one contribution."""
        from .clan_service import award_clan_contribution
        chefs = []
        for i, pts in enumerate(per_chef_points):
            chef = self._chef(f"{clan.slug}-{i}")
            self._join(clan, chef)
            award_clan_contribution(chef, pts, self.season)
            chefs.append(chef)
        return chefs

    def test_award_credits_active_clan(self):
        from .clan_service import award_clan_contribution
        from .models import ClanContribution
        founder = self._chef("f1")
        clan = self._clan("Fusion", founder)
        self._join(clan, founder, role="founder")
        written = award_clan_contribution(founder, 5, self.season)
        self.assertEqual(written, 5)
        self.assertEqual(ClanContribution.objects.filter(clan=clan, chef=founder).count(), 1)

    def test_award_without_active_clan_is_noop(self):
        from .clan_service import award_clan_contribution
        from .models import ClanContribution
        loner = self._chef("loner")
        self.assertEqual(award_clan_contribution(loner, 10, self.season), 0)
        self.assertFalse(ClanContribution.objects.filter(chef=loner).exists())

    def test_leaderboard_ranks_by_total_and_respects_floor(self):
        from .clan_service import get_clan_leaderboard
        big = self._clan("BigClan", self._chef("bigf"))
        small = self._clan("SmallClan", self._chef("smallf"))
        under = self._clan("UnderClan", self._chef("underf"))
        self._populate(big, [10, 10, 10])      # total 30, 3 active
        self._populate(small, [1, 1, 1])       # total 3, 3 active
        self._populate(under, [50, 50])        # total 100 but only 2 active -> excluded
        board = get_clan_leaderboard(self.season)
        names = [r["clan"].name for r in board]
        self.assertEqual(names, ["BigClan", "SmallClan"])
        self.assertEqual(board[0]["rank_position"], 1)
        self.assertEqual(board[0]["total_points"], 30)
        self.assertNotIn("UnderClan", names)

    def test_winning_clan_and_champion(self):
        from .clan_service import get_season_winning_clan, get_season_clan_champion
        from .clan_service import award_clan_contribution
        winner = self._clan("Winners", self._chef("winf"))
        loser = self._clan("Losers", self._chef("losf"))
        chefs = self._populate(winner, [5, 5, 5])
        self._populate(loser, [1, 1, 1])
        # Push one winner chef to the top for the champion check.
        award_clan_contribution(chefs[1], 100, self.season)
        self.assertEqual(get_season_winning_clan(self.season), winner)
        self.assertEqual(get_season_clan_champion(self.season, winner), chefs[1])

    def test_one_active_clan_per_chef(self):
        from django.db import transaction
        from .models import ClanMembership
        chef = self._chef("dual")
        clan_a = self._clan("ClanA", self._chef("af"))
        clan_b = self._clan("ClanB", self._chef("bf"))
        self._join(clan_a, chef)
        with self.assertRaises(IntegrityError):
            with transaction.atomic():
                ClanMembership.objects.create(
                    clan=clan_b, chef=chef,
                    status=ClanMembership.Status.ACTIVE,
                )

    def test_season_ended_finalizes_clan_standings(self):
        from .season_service import close_season
        from .models import ClanSeasonStanding
        winner = self._clan("FinalWin", self._chef("fwf"))
        runner = self._clan("FinalRun", self._chef("frf"))
        self._populate(winner, [9, 9, 9])
        self._populate(runner, [2, 2, 2])
        close_season(self.season)
        win_standing = ClanSeasonStanding.objects.get(clan=winner, season=self.season)
        self.assertEqual(win_standing.rank_position, 1)
        self.assertEqual(win_standing.total_points, 27)
        self.assertTrue(win_standing.rewards_pending)
        run_standing = ClanSeasonStanding.objects.get(clan=runner, season=self.season)
        self.assertEqual(run_standing.rank_position, 2)


class ArenaObserverTests(TestCase):
    """Arena Observer prize: champion nominates 2 clan members, advisory dispute
    votes, and won_season-derived active/expiry window."""

    def setUp(self):
        from datetime import timedelta
        from .models import Season, Faction, Clan, ClanMembership
        from .clan_service import award_clan_contribution
        now = timezone.now()
        self.s1 = Season.objects.create(name="ObsS1", starts_at=now - timedelta(days=60),
                                        ends_at=now - timedelta(days=1), status=Season.Status.ENDED)
        self.s2 = Season.objects.create(name="ObsS2", starts_at=now - timedelta(days=1),
                                        ends_at=now + timedelta(days=30), status=Season.Status.ACTIVE)
        self.cat = Faction.objects.create(kind=Faction.Kind.CUISINE, name="ItObs", slug="it-obs")
        self.founder = self._chef("obs-f")
        self.clan = Clan.objects.create(founder=self.founder, name="ObsClan", slug="obs-clan",
                                        moderation_status=Clan.Moderation.APPROVED)
        self.clan.categories.add(self.cat)
        self.members = [self.founder, self._chef("obs-m1"), self._chef("obs-m2")]
        for m in self.members:
            ClanMembership.objects.create(clan=self.clan, chef=m, status=ClanMembership.Status.ACTIVE)
            award_clan_contribution(m, 5, self.s1)
        award_clan_contribution(self.founder, 100, self.s1)  # founder = top contributor = champion
        self.champion = self.founder
        self.outsider = self._chef("obs-out")

    def _chef(self, n):
        User = get_user_model()
        u = User.objects.create_user(f"obs-{n}", password="pw")
        return RecipeAuthor.objects.create(user=u, name=f"Obs {n}", slug=f"obs-chef-{n}")

    def test_champion_nominates_two_members(self):
        from .observer_service import nominate_arena_observers, is_active_arena_observer
        obs = nominate_arena_observers(self.champion, self.members[1], self.members[2], self.s1)
        self.assertEqual(len(obs), 2)
        self.assertTrue(is_active_arena_observer(self.members[1]))
        self.assertTrue(is_active_arena_observer(self.members[2]))
        self.assertFalse(is_active_arena_observer(self.outsider))

    def test_non_champion_cannot_nominate(self):
        from .observer_service import nominate_arena_observers, can_nominate_observers
        self.assertFalse(can_nominate_observers(self.members[1], self.s1))
        with self.assertRaises(ValueError):
            nominate_arena_observers(self.members[1], self.members[2], self.outsider, self.s1)

    def test_candidate_must_be_clan_member(self):
        from .observer_service import nominate_arena_observers
        with self.assertRaises(ValueError):
            nominate_arena_observers(self.champion, self.outsider, self.members[1], self.s1)

    def test_two_seats_max(self):
        from .observer_service import nominate_arena_observers, can_nominate_observers
        nominate_arena_observers(self.champion, self.members[1], self.members[2], self.s1)
        self.assertFalse(can_nominate_observers(self.champion, self.s1))  # seats full

    def test_service_rejects_a_third_seat(self):
        """The cap is enforced inside the service, not only by the view: with one
        seat already taken, nominating two more (three in two chairs) is refused."""
        from .models import ClanMembership, SeasonArenaObserver
        from .observer_service import nominate_arena_observers
        # a fourth active clan member to make the third candidate legitimate
        m4 = self._chef("obs-m4")
        ClanMembership.objects.create(clan=self.clan, chef=m4, status=ClanMembership.Status.ACTIVE)
        # pre-seat one observer directly, bypassing the view
        SeasonArenaObserver.objects.create(
            chef=self.members[1], won_season=self.s1,
            nominated_by=self.champion, clan=self.clan,
        )
        with self.assertRaises(ValueError):
            nominate_arena_observers(self.champion, self.members[2], m4, self.s1)
        self.assertEqual(
            SeasonArenaObserver.objects.filter(won_season=self.s1).count(), 1
        )

    def test_role_expires_after_following_season(self):
        from datetime import timedelta
        from .models import Season
        from .observer_service import nominate_arena_observers, is_active_arena_observer
        nominate_arena_observers(self.champion, self.members[1], self.members[2], self.s1)
        self.assertTrue(is_active_arena_observer(self.members[1]))
        # A further season begins: s2 ends, s3 becomes active.
        self.s2.status = Season.Status.ENDED
        self.s2.save(update_fields=["status"])
        Season.objects.create(name="ObsS3", starts_at=timezone.now() + timedelta(days=31),
                              ends_at=timezone.now() + timedelta(days=60), status=Season.Status.ACTIVE)
        self.assertFalse(is_active_arena_observer(self.members[1]))  # expired

    def test_cast_advisory_vote_records_and_updates(self):
        from .models import Battle, BattleReport
        from .observer_service import nominate_arena_observers, cast_observer_vote, get_observer_votes
        obs = nominate_arena_observers(self.champion, self.members[1], self.members[2], self.s1)[0]
        b = Battle.objects.create(challenger=self.members[1], opponent=self.members[2], theme="Theme",
                                  submission_deadline=timezone.now(), end_time=timezone.now())
        rep = BattleReport.objects.create(battle=b, author=self.outsider, summary="dispute",
                                          recommendation=BattleReport.Recommendation.NEEDS_REVIEW)
        v = cast_observer_vote(obs, rep, BattleReport.Recommendation.APPROVE_PAYOUT, note="fair")
        self.assertEqual(v.recommendation, "approve_payout")
        self.assertEqual(len(get_observer_votes(rep)), 1)
        cast_observer_vote(obs, rep, BattleReport.Recommendation.WITHHOLD)  # update, not duplicate
        self.assertEqual(len(get_observer_votes(rep)), 1)
        self.assertEqual(get_observer_votes(rep)[0].recommendation, "withhold")


class LiveArenaTrackerTests(TestCase):
    """Owner-visible Live Arena build tracker: matrix render + live status update."""

    def setUp(self):
        from django.conf import settings
        from django.test import Client
        U = get_user_model()
        author = RecipeAuthor.objects.filter(slug=settings.OWNER_SLUG).first()
        if author is not None and author.user_id:
            self.owner = author.user
            self.owner.is_superuser = True
            self.owner.is_staff = True
            self.owner.save()
        else:
            self.owner = U.objects.create_superuser("la-owner", "la@o.com", "pw")
            if author is None:
                RecipeAuthor.objects.create(user=self.owner, name="Owner", slug=settings.OWNER_SLUG)
            else:
                author.user = self.owner
                author.save(update_fields=["user"])
        self.client = Client()
        self.client.force_login(self.owner)

    def test_matrix_renders_16_stages(self):
        r = self.client.get("/chef-battle/master/live-arena/")
        self.assertEqual(r.status_code, 200)
        h = r.content.decode()
        self.assertEqual(h.count('data-key="'), 16)
        self.assertIn("/chef-battle/master/live-arena/update/", h)

    def test_stage_update_writes_only_its_column(self):
        from .models import LiveArenaStage
        r = self.client.post("/chef-battle/master/live-arena/update/", {
            "key": "state_contract", "column": "backend",
            "status": "present", "notes": "13 states in Battle.Status",
        })
        self.assertEqual(r.status_code, 200)
        s = LiveArenaStage.objects.get(key="state_contract")
        self.assertEqual(s.backend_status, "present")
        self.assertEqual(s.frontend_status, "absent")  # untouched
        self.assertEqual(s.backend_notes, "13 states in Battle.Status")

    def test_bad_column_rejected(self):
        r = self.client.post("/chef-battle/master/live-arena/update/", {
            "key": "state_contract", "column": "hacker", "status": "present"})
        self.assertEqual(r.status_code, 400)

    def test_non_moderator_blocked(self):
        from django.test import Client
        U = get_user_model()
        U.objects.create_user("la-nobody", "n@n.com", "pw")
        c = Client(); c.login(username="la-nobody", password="pw")
        self.assertEqual(c.get("/chef-battle/master/live-arena/").status_code, 404)


class LiveArenaPreviewTests(LiveArenaTrackerTests):
    """Preview page renders the broadcast composition for the owner."""

    def test_preview_renders(self):
        r = self.client.get("/chef-battle/master/live-arena/preview/")
