class ArenaCenterConfrontationContractTests(TestCase):
    """Confrontation payload includes the reference plinth identity."""

    FIGHTER_KEYS = {
        "name", "avatar_url", "slug", "profile_url", "side", "country", "flag",
    }

    def _pair(self):
        U = get_user_model()
        a = RecipeAuthor.objects.create(
            user=U.objects.create_user("r3-a", password="pw"), name="R3 Challenger", slug="r3-challenger"
        )
        b = RecipeAuthor.objects.create(
            user=U.objects.create_user("r3-b", password="pw"), name="R3 Opponent", slug="r3-opponent"
        )
        return a, b

    def _assert_fighter(self, fighter, *, author, side):
        self.assertEqual(set(fighter.keys()), self.FIGHTER_KEYS)
        self.assertEqual(fighter["name"], author.name)
        self.assertEqual(fighter["avatar_url"], author.display_avatar_url)
        self.assertEqual(fighter["slug"], author.slug)
        self.assertEqual(fighter["profile_url"], author.get_absolute_url())
        self.assertEqual(fighter["side"], side)
        self.assertEqual(fighter["country"], "Ireland")
        self.assertEqual(fighter["flag"], "🇮🇪")
        self.assertNotIn("flag_url", fighter)
        self.assertNotIn("country_code", fighter)

    def test_active_battle_fighters_match_3r3_contract(self):
        from chef_battle.views import _arena_center
        from .models import Battle

        a, b = self._pair()
        battle = Battle.objects.create(
            challenger=a,
            opponent=b,
            theme="3R3 Band",
            status=Battle.Status.COOKING,
            submission_deadline=timezone.now(),
            end_time=timezone.now(),
        )
        c = _arena_center(battle)
        self.assertEqual(c["type"], "active_battle")
        self._assert_fighter(c["challenger"], author=a, side="challenger")
        self._assert_fighter(c["opponent"], author=b, side="opponent")

    def test_a_ready_pair_whose_hour_has_not_come_is_still_not_at_the_centre(self):
        """Owner, 2026-08-06: the pair jumps to the centre only when their
        battle BEGINS, and until then the cells by the centre are empty.

        Pressing Ready is not the beginning. It pulls the start in to thirty
        minutes (T20, Owner 2026-08-15; fifteen until then), and those minutes
        are spent standing in the rings.
        """
        from chef_battle.views import _arena_center
        from .models import Battle

        a, b = self._pair()
        battle = Battle.objects.create(
            challenger=a,
            opponent=b,
            theme="Ready, not started",
            status=Battle.Status.SCHEDULED,
            challenger_ready=True,
            opponent_ready=True,
            start_time=timezone.now() + timezone.timedelta(minutes=15),
            submission_deadline=timezone.now(),
            end_time=timezone.now(),
        )
        self.assertEqual(_arena_center(battle)["type"], "empty")

        # Menu locked is still not begun.
        battle.status = Battle.Status.MENU_LOCKED
        battle.save(update_fields=["status"])
        self.assertEqual(_arena_center(battle)["type"], "empty")

        # The hour arrives and the battle is under way: now the centre has them.
        battle.status = Battle.Status.ACTIVE
        battle.start_time = timezone.now() - timezone.timedelta(seconds=1)
        battle.save(update_fields=["status", "start_time"])
        c = _arena_center(battle)
        self.assertEqual(c["type"], "active_battle")
        self._assert_fighter(c["challenger"], author=a, side="challenger")
        self._assert_fighter(c["opponent"], author=b, side="opponent")

    def test_an_agreed_battle_does_not_move_anyone_to_the_centre(self):
        """Owner, 2026-08-06: accepting a challenge pulled both chefs out of
        their rank rings and into the facing cells while the battle room still
        read "Awaiting readiness" and neither had pressed the button.

        The centre is for a battle that is HAPPENING. A battle that has merely
        been agreed is two chefs standing in their own rings.
        """
        from chef_battle.views import _arena_center
        from .models import Battle

        a, b = self._pair()
        battle = Battle.objects.create(
            challenger=a,
            opponent=b,
            theme="Agreed, not started",
            status=Battle.Status.SCHEDULED,
            submission_deadline=timezone.now(),
            end_time=timezone.now(),
        )
        self.assertEqual(_arena_center(battle)["type"], "empty")

        # One chef alone is not enough either.
        battle.challenger_ready = True
        battle.save(update_fields=["challenger_ready"])
        self.assertEqual(_arena_center(battle)["type"], "empty")

        # And both of them ready is STILL not the centre — that is the second
        # half of his rule: readiness schedules the fight, it does not start it.
        battle.opponent_ready = True
        battle.save(update_fields=["opponent_ready"])
        self.assertEqual(_arena_center(battle)["type"], "empty")

    def test_empty_and_crown_states_still_valid(self):
        from chef_battle.views import _arena_center
        from .models import ChefBattleProfile

        self.assertEqual(_arena_center(None), {"type": "empty"})

        a, _b = self._pair()
        ChefBattleProfile.objects.create(
            author=a,
            crown_until=timezone.now() + timezone.timedelta(hours=1),
        )
        crown = _arena_center(None)
        self.assertEqual(crown["type"], "crown")
        self.assertEqual(crown["name"], a.name)
        self.assertEqual(crown["avatar_url"], a.display_avatar_url)
        self.assertEqual(crown["profile_url"], a.get_absolute_url())
        self.assertNotIn("country", crown)
        self.assertNotIn("flag", crown)


class ArenaPhaseTests(TestCase):
    """get_arena_phase: 7-step public phase rail mapping (Ember #159)."""

    def _battle(self, status, paused_from=""):
        from .models import Battle
        U = get_user_model()
        import uuid
        tag = uuid.uuid4().hex[:6]
        a = RecipeAuthor.objects.create(user=U.objects.create_user(f"ph-a-{tag}", password="pw"), name="A", slug=f"ph-a-{tag}")
        b = RecipeAuthor.objects.create(user=U.objects.create_user(f"ph-b-{tag}", password="pw"), name="B", slug=f"ph-b-{tag}")
        return Battle.objects.create(challenger=a, opponent=b, theme="T", status=status,
                                     paused_from_status=paused_from,
                                     submission_deadline=timezone.now(), end_time=timezone.now())

    def test_none_battle_is_null(self):
        from .selectors import get_arena_phase
        self.assertIsNone(get_arena_phase(None))

    def test_status_maps_to_rung(self):
        from .models import Battle
        from .selectors import get_arena_phase
        cases = {
            Battle.Status.SCHEDULED: ("challenge", 1),
            Battle.Status.MENU_LOCKED: ("challenge", 1),
            Battle.Status.ACTIVE: ("combat", 2),
            Battle.Status.INGREDIENT_PENALTY: ("biathlon", 3),
            Battle.Status.COOKING: ("cooking", 4),
            Battle.Status.PRESENTATION: ("mod_review", 5),
            Battle.Status.VOTING: ("voting", 6),
            Battle.Status.COMPLETED: ("crown", 7),
        }
        for status, (key, step) in cases.items():
            ph = get_arena_phase(self._battle(status))
            self.assertEqual(ph["key"], key, status)
            self.assertEqual(ph["step"], step, status)
            self.assertTrue(ph["label"])

    def test_paused_resolves_to_paused_from(self):
        from .models import Battle
        from .selectors import get_arena_phase
        ph = get_arena_phase(self._battle(Battle.Status.PAUSED, paused_from="voting"))
        self.assertEqual(ph["key"], "voting")
        self.assertEqual(ph["step"], 6)


