class AcceptChallengeRankRecheckTests(TestCase):
    """F9, 2026-08-11: check_rank_matchup only ran at challenge_create, not at
    accept_challenge. A challenge stands up to twelve hours (X05); if the rank
    gap widens past adjacent in that window (a win moves rank by the ladder's
    three-wins-per-step cadence), the battle was still created. accept_challenge
    now re-checks and raises ValueError; challenge_respond surfaces it as a
    message instead of a 500."""

    def setUp(self):
        User = get_user_model()
        uc = User.objects.create_user("f9-challenger", password="pw")
        uo = User.objects.create_user("f9-opponent", password="pw")
        self.challenger = RecipeAuthor.objects.create(user=uc, name="F9 Challenger", slug="f9-challenger")
        self.opponent = RecipeAuthor.objects.create(user=uo, name="F9 Opponent", slug="f9-opponent")
        ChefBattleProfile.objects.create(author=self.challenger, enrolled_at=timezone.now())
        ChefBattleProfile.objects.create(author=self.opponent, enrolled_at=timezone.now())

    def _challenge(self):
        return BattleChallenge.objects.create(
            challenger=self.challenger, opponent=self.opponent, theme="F9 Dish",
            expires_at=timezone.now() + timezone.timedelta(hours=12),
        )

    def test_accept_raises_when_rank_gap_widened_after_the_challenge_was_sent(self):
        challenge = self._challenge()
        # Both start at the same default rank - legal when the challenge was
        # sent. Push the opponent three ranks up before it is accepted.
        ranks = list(ChefBattleProfile.Rank)
        self.opponent.battle_profile.rank = ranks[3].value
        self.opponent.battle_profile.save(update_fields=["rank"])

        with self.assertRaises(ValueError):
            accept_challenge(challenge)

    def test_accept_still_works_when_ranks_stayed_adjacent(self):
        challenge = self._challenge()
        battle = accept_challenge(challenge)
        self.assertIsNotNone(battle.pk)

    @override_settings(CHEF_BATTLE_ENABLED=True)
    def test_view_surfaces_the_rank_error_instead_of_500(self):
        challenge = self._challenge()
        ranks = list(ChefBattleProfile.Rank)
        self.opponent.battle_profile.rank = ranks[3].value
        self.opponent.battle_profile.save(update_fields=["rank"])

        client = Client()
        client.login(username="f9-opponent", password="pw")
        resp = client.post(
            reverse("chef_battle:challenge_respond", kwargs={"pk": challenge.pk}),
            {"action": "accept"},
        )
        self.assertEqual(resp.status_code, 302)
        challenge.refresh_from_db()
        self.assertEqual(challenge.status, BattleChallenge.Status.PENDING)

@override_settings(CHEF_BATTLE_ENABLED=True)
class ContentEarnsReputationTests(TestCase):
    """G6 — the two ladders the ТЗ separates on purpose.

    tz_main.md section 9 and artifact_3_models_rules.md section 9 both require
    Culinary Reputation to be earned from published content, and state the
    reason: a chef can be a strong creator without being the best fighter.
    Until 2026-08-11 reputation was written in exactly three places and every
    one of them was a battle outcome, so both ladders were PvP-driven and a
    chef who only published saw no status at all. Owner's order: fix it.
    """

    def setUp(self):
        User = get_user_model()
        self.author = RecipeAuthor.objects.create(
            user=User.objects.create_user("repchef", password="pw"),
            name="Rep Chef", slug="rep-chef",
        )
        self.profile = ChefBattleProfile.objects.create(author=self.author)

    def _reputation(self):
        self.profile.refresh_from_db()
        return self.profile.reputation

    def _recipe(self, title, slug):
        from recipes.models import Recipe
        return Recipe.objects.create(
            author=self.author, title=title, slug=slug,
            status=Recipe.Status.APPROVED,
        )

    def test_publishing_a_recipe_raises_reputation(self):
        """End to end through the real signal, not through the service: the
        chef publishes, a moderator approves, and status moves."""
        from chef_battle.services import REPUTATION_RECIPE_PUBLISHED

        before = self._reputation()
        self._recipe("Soda Bread", "soda-bread")
        self.assertEqual(self._reputation() - before, REPUTATION_RECIPE_PUBLISHED)

    def test_a_second_approval_of_the_same_recipe_pays_nothing(self):
        """The once-per-object gate must cover reputation too, or editing and
        re-approving one recipe farms status forever."""
        from chef_battle.energy_service import award_moves, EARN_RECIPE_PUBLISHED
        from chef_battle.models import BattleMoveTransaction
        from chef_battle.services import REPUTATION_RECIPE_PUBLISHED

        before = self._reputation()
        recipe = self._recipe("Brown Bread", "brown-bread")
        for _ in range(3):
            award_moves(self.author, EARN_RECIPE_PUBLISHED,
                        BattleMoveTransaction.TxType.RECIPE_PUBLISHED, reference=recipe)
        self.assertEqual(self._reputation() - before, REPUTATION_RECIPE_PUBLISHED)

    def test_a_full_move_balance_still_earns_reputation(self):
        """The cap is on ENERGY, not on status. A chef sitting at the move
        ceiling has still earned what they published."""
        from chef_battle.energy_service import award_moves, ENERGY_CAP, EARN_ARTICLE_PUBLISHED
        from chef_battle.models import BattleMoveTransaction
        from chef_battle.services import REPUTATION_ARTICLE_PUBLISHED

        recipe = self._recipe("Colcannon", "colcannon")
        ChefBattleProfile.objects.filter(pk=self.profile.pk).update(battle_moves=ENERGY_CAP)
        before = self._reputation()
        awarded = award_moves(self.author, EARN_ARTICLE_PUBLISHED,
                              BattleMoveTransaction.TxType.ARTICLE_PUBLISHED, reference=recipe)
        self.assertEqual(awarded, 0, "the move cap should have refused the moves")
        self.assertEqual(self._reputation() - before, REPUTATION_ARTICLE_PUBLISHED)

    def test_an_unidentified_like_pays_no_reputation(self):
        """A like nobody can be rate-limited on pays no moves; it must not pay
        status either, or the anti-farm gate is bypassed by the side door."""
        from chef_battle.energy_service import award_moves, EARN_LIKE_RECEIVED
        from chef_battle.models import BattleMoveTransaction

        award_moves(self.author, EARN_LIKE_RECEIVED,
                    BattleMoveTransaction.TxType.LIKE_RECEIVED)
        self.assertEqual(self._reputation(), 0)


class BoardOfMemoryTests(TestCase):
    """G7 and G4 — the two permanent records of hall_of_fame.md.

    The Board of Memory is the first twenty chefs ever to fight, in arrival
    order; it returned the top twenty BY WINS, which is a leaderboard and a
    different set. The Founding Ten ordered by updated_at, which is auto_now,
    so any later write to a completed battle evicted it from a list the
    document calls permanent.
    """

    def setUp(self):
        User = get_user_model()
        self.chefs = []
        for index in range(4):
            author = RecipeAuthor.objects.create(
                user=User.objects.create_user(f"pioneer{index}", password="pw"),
                name=f"Pioneer {index}", slug=f"pioneer-{index}",
            )
            ChefBattleProfile.objects.create(author=author, wins=index)
            self.chefs.append(author)

    def _battle(self, a, b, **kwargs):
        now = timezone.now()
        return Battle.objects.create(
            challenger=a, opponent=b, theme="Theme",
            status=kwargs.pop("status", Battle.Status.COMPLETED),
            start_time=now, submission_deadline=now, voting_deadline=now, end_time=now,
            **kwargs,
        )

    def test_the_board_is_arrival_order_not_a_leaderboard(self):
        from chef_battle.selectors import get_hall_of_fame_chefs

        first = self._battle(self.chefs[0], self.chefs[1], winner=self.chefs[1])
        second = self._battle(self.chefs[2], self.chefs[3], winner=self.chefs[3])
        Battle.objects.filter(pk=first.pk).update(
            created_at=timezone.now() - timezone.timedelta(days=2))
        Battle.objects.filter(pk=second.pk).update(
            created_at=timezone.now() - timezone.timedelta(days=1))

        board = [p.author.slug for p in get_hall_of_fame_chefs(limit=20)]
        self.assertEqual(board, ["pioneer-0", "pioneer-1", "pioneer-2", "pioneer-3"],
                         "the board must read in arrival order, not by wins")

    def test_a_chef_who_never_won_still_holds_their_place(self):
        from chef_battle.selectors import get_hall_of_fame_chefs

        self._battle(self.chefs[0], self.chefs[1], winner=self.chefs[1])
        board = [p.author.slug for p in get_hall_of_fame_chefs(limit=20)]
        self.assertIn("pioneer-0", board,
                      "turning up earns the place; winning is a different board")

    def test_the_founding_ten_survive_a_later_write(self):
        from chef_battle.models import BattleEvent
        from chef_battle.selectors import get_hall_of_fame_battles

        older = self._battle(self.chefs[0], self.chefs[1], winner=self.chefs[0])
        newer = self._battle(self.chefs[2], self.chefs[3], winner=self.chefs[2])
        for battle, minutes in ((older, 120), (newer, 60)):
            event = BattleEvent.objects.create(
                battle=battle, event_type=BattleEvent.EventType.BATTLE_FINISHED,
                message="finished", is_public=True,
            )
            BattleEvent.objects.filter(pk=event.pk).update(
                created_at=timezone.now() - timezone.timedelta(minutes=minutes))

        self.assertEqual([b.pk for b in get_hall_of_fame_battles(limit=10)],
                         [older.pk, newer.pk])

        # A moderation note, a dispute, a withdrawal resolution — any later
        # write at all. The old ordering put the touched battle last.
        older.result_reason = "Reviewed by a moderator."
        older.save(update_fields=["result_reason", "updated_at"])

        self.assertEqual([b.pk for b in get_hall_of_fame_battles(limit=10)],
                         [older.pk, newer.pk],
                         "a later write must not move a battle out of the founding ten")


@override_settings(CHEF_BATTLE_ENABLED=True)
class OneBattleSlotTests(TestCase):
    """G1 — one slot per chef, read in full.

    The slot is occupied the moment a challenge is ISSUED, and an occupied slot
    forbids ACCEPTING as well as issuing. Nothing in the code modelled a slot
    at all until 2026-08-11: a chef could hold three live battles, which
    battle_rules.md forbids in its first line.
    """

    def setUp(self):
        User = get_user_model()
        self.a, self.b, self.c = [
            RecipeAuthor.objects.create(
                user=User.objects.create_user(f"slot{n}", password="pw"),
                name=f"Slot {n}", slug=f"slot-{n}",
            )
            for n in ("a", "b", "c")
        ]
        for author in (self.a, self.b, self.c):
            ChefBattleProfile.objects.create(author=author, battle_moves=50)

    def _challenge(self, challenger, opponent, **kwargs):
        return BattleChallenge.objects.create(
            challenger=challenger, opponent=opponent, theme="Theme",
            status=kwargs.pop("status", BattleChallenge.Status.PENDING),
            expires_at=kwargs.pop("expires_at", timezone.now() + timezone.timedelta(hours=12)),
            **kwargs,
        )

    def test_a_free_slot_reads_free(self):
        from chef_battle.services import slot_occupied_reason
        self.assertIsNone(slot_occupied_reason(self.a))

    def test_an_unanswered_challenge_takes_the_slot(self):
        from chef_battle.services import slot_occupied_reason
        self._challenge(self.a, self.b)
        self.assertIn("unanswered challenge", slot_occupied_reason(self.a) or "")

    def test_an_expired_challenge_frees_the_slot(self):
        from chef_battle.services import slot_occupied_reason
        self._challenge(self.a, self.b,
                        expires_at=timezone.now() - timezone.timedelta(hours=1))
        self.assertIsNone(slot_occupied_reason(self.a))

    def test_a_live_battle_takes_the_slot_for_both_chefs(self):
        from chef_battle.services import slot_occupied_reason
        now = timezone.now()
        Battle.objects.create(
            challenger=self.a, opponent=self.b, theme="Theme",
            status=Battle.Status.ACTIVE,
            start_time=now, submission_deadline=now, voting_deadline=now, end_time=now,
        )
        for chef in (self.a, self.b):
            self.assertIn("already in a battle", slot_occupied_reason(chef) or "")

    def test_a_finished_battle_frees_the_slot(self):
        from chef_battle.services import slot_occupied_reason
        now = timezone.now()
        Battle.objects.create(
            challenger=self.a, opponent=self.b, theme="Theme",
            status=Battle.Status.COMPLETED, winner=self.a,
            start_time=now, submission_deadline=now, voting_deadline=now, end_time=now,
        )
        self.assertIsNone(slot_occupied_reason(self.a))

    def test_the_challenge_being_answered_does_not_block_its_own_acceptance(self):
        from chef_battle.services import slot_occupied_reason
        challenge = self._challenge(self.b, self.a)
        self.assertIsNone(slot_occupied_reason(self.b, ignore_challenge=challenge))

    def test_accepting_is_refused_while_the_slot_is_taken(self):
        """The half of the rule that is easy to miss: an occupied slot blocks
        ACCEPTING, not only issuing."""
        now = timezone.now()
        Battle.objects.create(
            challenger=self.a, opponent=self.c, theme="Ongoing",
            status=Battle.Status.ACTIVE,
            start_time=now, submission_deadline=now, voting_deadline=now, end_time=now,
        )
        challenge = self._challenge(self.b, self.a)
        client = Client()
        client.login(username="slota", password="pw")
        response = client.post(
            reverse("chef_battle:challenge_respond", kwargs={"pk": challenge.pk}),
            {"action": "accept"},
        )
        self.assertEqual(response.status_code, 302)
        challenge.refresh_from_db()
        self.assertEqual(challenge.status, BattleChallenge.Status.PENDING)
        self.assertFalse(Battle.objects.filter(challenge=challenge).exists())



class ForcedTransitionRevealsEntriesTests(TestCase):
    """F10, 2026-08-11: battle_detail.html shows entry.recipe/battle_statement
    when entry.is_revealed OR battle.status in {completed, presentation, voting} -
    a phase-name fallback. reveal_entries_if_ready() was the only writer of
    is_revealed, and neither operator_force_status's direct-assign branch nor
    _score_battle called it, so a forced or scored transition into one of those
    statuses could show both dishes while is_revealed stayed False in the
    database."""

    def setUp(self):
        from django.conf import settings as django_settings
        User = get_user_model()
        self.owner_user = User.objects.create_superuser("f10-greenbear", password="pw")
        self.owner_author, _ = RecipeAuthor.objects.update_or_create(
            slug=django_settings.OWNER_SLUG,
            defaults={"user": self.owner_user, "name": "F10 GreenBear"},
        )
        ua = User.objects.create_user("f10-chef-a", password="pw")
        ub = User.objects.create_user("f10-chef-b", password="pw")
        self.chef_a = RecipeAuthor.objects.create(user=ua, name="F10 Chef A", slug="f10-chef-a")
        self.chef_b = RecipeAuthor.objects.create(user=ub, name="F10 Chef B", slug="f10-chef-b")
        ChefBattleProfile.objects.create(author=self.chef_a, enrolled_at=timezone.now())
        ChefBattleProfile.objects.create(author=self.chef_b, enrolled_at=timezone.now())

    def _battle_with_unrevealed_entries(self, status):
        now = timezone.now()
        battle = Battle.objects.create(
            challenger=self.chef_a, opponent=self.chef_b,
            theme="F10 Dish", status=status,
            start_time=now,
            submission_deadline=now - timezone.timedelta(hours=1),
            voting_deadline=now + timezone.timedelta(days=1),
            end_time=now + timezone.timedelta(days=2),
        )
        for author in (self.chef_a, self.chef_b):
            BattleEntry.objects.create(
                battle=battle, author=author,
                battle_statement="Secret recipe.",
                dish_submitted_at=now, is_revealed=False,
            )
        return battle

    def test_direct_force_assign_reveals_entries(self):
        from .services import operator_force_status
        battle = self._battle_with_unrevealed_entries(Battle.Status.ACTIVE)
        operator_force_status(
            battle_id=battle.pk, operator_author=self.owner_author,
            target_status=Battle.Status.VOTING, expected_status=Battle.Status.ACTIVE,
            reason="F10 test",
        )
        self.assertTrue(
            all(battle.entries.values_list("is_revealed", flat=True)),
            "forcing straight to VOTING left an entry unrevealed while the "
            "template would already show it",
        )

    def test_calculate_battle_result_reveals_entries(self):
        battle = self._battle_with_unrevealed_entries(Battle.Status.ACTIVE)
        BattleVote.objects.create(
            battle=battle,
            voter=get_user_model().objects.create_user("f10-voter", password="pw"),
            voted_for=self.chef_a,
        )
        # T01, 2026-08-12: the scorer takes only a locked VOTING battle now.
        # This is the state the real flow is in when voting closes.
        walk_battle_to(battle, Battle.Status.VOTING)
        calculate_battle_result(battle)
        self.assertTrue(
            all(battle.entries.values_list("is_revealed", flat=True)),
            "a battle scored to COMPLETED left an entry unrevealed",
        )


class ArenaSeamTokenNotRawLiteralTests(TestCase):
    """T2, 2026-08-11: five declarations set stroke/fill to a raw #ffffff or
    #f4f1ec directly, in the same .page--arena scope that defines --arena-seam:
    #ffffff and --arena-seat: #f4f1ec two lines above them - contract section 12
    forbids scattered raw colour literals in favour of the named tokens, and
    these were the token's own value restated by hand instead of referenced.
    Fixed to var(--arena-seam) / var(--arena-seat). Not exhaustive: several
    other literals in this file (the sponsors-ring ramp, one runway-note colour)
    have no matching named token to point at, and inventing one is a design
    decision, not this cleanup's to make."""

    CSS = Path(settings.BASE_DIR) / "static" / "css" / "arena.css"

    def test_the_five_known_literals_now_reference_the_token(self):
        text = self.CSS.read_text(encoding="utf-8")
        must_not_appear = [
            ".arena-cell {\n    stroke: #ffffff;",
            '[data-occupancy="chef"] {\n    stroke: #ffffff;',
            '[data-occupancy="empty"] {\n    stroke: #ffffff;',
            ".arena-cell--sponsors-tpl {\n    stroke: #ffffff;",
            '[data-ring="6"][data-occupancy="empty"] { fill: #f4f1ec; }',
        ]
        for snippet in must_not_appear:
            self.assertNotIn(
                snippet, text,
                f"a raw literal reappeared where var(--arena-seam)/var(--arena-seat) "
                f"should be used instead: {snippet!r}",
            )
        self.assertIn("stroke: var(--arena-seam)", text)
        self.assertIn("fill: var(--arena-seat)", text)


class TokenTerminologyNotWalletTests(TestCase):
    """T1 (partial), 2026-08-11: contract section 9.1 requires TokenAccount /
    Token Balance / Token Ledger / Token Transaction terminology and forbids
    introducing new wallet or cash-balance terminology. The public VAT/refunds
    legal page said 'wallet' four times, and the Master Console's read-only
    economy hint said 'wallet balances' once - user-facing text is fixed here.

    NOT done by this card: the TokenWallet Django model itself keeps its name.
    Renaming it is a schema migration on the live Stripe payment/reward path
    (TokenWallet, TokenTransaction.wallet, TokenOrder.wallet and every view/
    template/admin reference), which is a bigger, riskier change than a
    same-day terminology fix and is the Owner's call, not an agent's to make
    unprompted on a payment-integration model."""

    def test_legal_page_does_not_say_wallet(self):
        from django.test import Client
        resp = Client().get(reverse("legal:purchases_and_vat"))
        page = resp.content.decode().lower()
        self.assertNotIn("wallet", page)
        self.assertIn("token account", page)

    def test_master_console_economy_hint_does_not_say_wallet(self):
        from django.conf import settings as django_settings
        User = get_user_model()
        owner_user = User.objects.create_superuser("tt-greenbear", password="pw")
        RecipeAuthor.objects.update_or_create(
            slug=django_settings.OWNER_SLUG,
            defaults={"user": owner_user, "name": "TT GreenBear"},
        )
        client = Client()
        client.force_login(owner_user)
        page = client.get(reverse("chef_battle:master_console")).content.decode().lower()
        self.assertNotIn("wallet balances", page)
        self.assertIn("token account balances", page)

class ArtifactPriceFollowsRarityTests(TestCase):
    """X14 — the published price list was enforced by nothing.

    RARITY_TOKEN_COST is printed in token_economy.md and audience_gifts.md and
    was referenced by no code at all. The charge came from a per-row field
    defaulting to ten, so an Epic added without a price cost a viewer 10 tokens
    instead of 150 and nothing would have said so.
    """

    def test_a_new_artifact_is_priced_by_its_rarity(self):
        from chef_battle.models import Artifact
        for rarity, expected in Artifact.RARITY_TOKEN_COST.items():
            artifact = Artifact.objects.create(name=f"Priced {rarity}", rarity=rarity)
            self.assertEqual(
                artifact.token_cost, expected,
                f"a new {rarity} artifact must cost the published {expected}T",
            )

    def test_an_explicit_price_is_never_overridden(self):
        from chef_battle.models import Artifact
        artifact = Artifact.objects.create(
            name="Hand Priced", rarity=Artifact.Rarity.EPIC, token_cost=99)
        self.assertEqual(artifact.token_cost, 99, "a chosen price is the Owner's lever")

    def test_an_existing_row_is_left_alone(self):
        from chef_battle.models import Artifact
        artifact = Artifact.objects.create(
            name="Legacy Row", rarity=Artifact.Rarity.COMMON)
        Artifact.objects.filter(pk=artifact.pk).update(
            rarity=Artifact.Rarity.LEGENDARY, token_cost=10)
        artifact.refresh_from_db()
        artifact.description = "edited"
        artifact.save(update_fields=["description"])
        artifact.refresh_from_db()
        self.assertEqual(artifact.token_cost, 10,
                         "save() may price a new row, never reprice an old one")


class RatingReadsTheOpponentTests(TestCase):
    """G8 — a win is worth what it cost, not a flat 25.

    tz_main.md section 9 asks for "opponent strength" and "repeated opponent
    reduction"; section 16 lists diminishing returns against a repeated
    opponent among the anti-abuse requirements. Neither was built: farming one
    weak neighbour paid exactly what beating the champion paid.
    """

    def setUp(self):
        User = get_user_model()
        self.a = RecipeAuthor.objects.create(
            user=get_user_model().objects.create_user("g8-a", password="pw"),
            name="G8 A", slug="g8-a")
        self.b = RecipeAuthor.objects.create(
            user=User.objects.create_user("g8-b", password="pw"),
            name="G8 B", slug="g8-b")
        self.pa = ChefBattleProfile.objects.create(author=self.a)
        self.pb = ChefBattleProfile.objects.create(author=self.b)

    def _award(self, winner_rating, loser_rating, **kwargs):
        from chef_battle.services import rating_award_for_win
        self.pa.rating, self.pb.rating = winner_rating, loser_rating
        return rating_award_for_win(self.pa, self.pb, **kwargs)

    def test_equal_ratings_pay_the_flat_award(self):
        from chef_battle.services import RATING_WIN
        self.assertEqual(self._award(0, 0), RATING_WIN)

    def test_two_new_chefs_are_unaffected(self):
        """Everyone starts at 0, so the curve must be invisible until ratings
        actually diverge — this change must not move today's numbers."""
        from chef_battle.services import RATING_WIN
        self.assertEqual(self._award(0, 0), RATING_WIN)

    def test_beating_someone_stronger_pays_more(self):
        from chef_battle.services import RATING_WIN
        self.assertGreater(self._award(100, 600), RATING_WIN)

    def test_beating_someone_weaker_pays_less(self):
        from chef_battle.services import RATING_WIN
        self.assertLess(self._award(600, 100), RATING_WIN)

    def test_the_curve_is_bounded_at_both_ends(self):
        from chef_battle.services import RATING_WIN, RATING_STRENGTH_MAX, RATING_STRENGTH_MIN
        self.assertEqual(self._award(0, 999999), round(RATING_WIN * RATING_STRENGTH_MAX))
        self.assertEqual(self._award(999999, 0), round(RATING_WIN * RATING_STRENGTH_MIN))

    def test_a_win_always_moves_the_number(self):
        """However discounted, winning must never pay nothing — that would read
        as a punishment for winning."""
        self.assertGreaterEqual(self._award(999999, 0), 1)

    def test_beating_the_same_chef_again_pays_less_each_time(self):
        from chef_battle.services import rating_award_for_win
        now = timezone.now()
        awards = []
        for _ in range(3):
            awards.append(rating_award_for_win(self.pa, self.pb, winner=self.a, loser=self.b))
            Battle.objects.create(
                challenger=self.a, opponent=self.b, theme="Repeat",
                status=Battle.Status.COMPLETED, winner=self.a, loser=self.b,
                start_time=now, submission_deadline=now, voting_deadline=now, end_time=now,
            )
        self.assertGreater(awards[0], awards[1])
        self.assertGreater(awards[1], awards[2])

    def test_an_old_rivalry_is_not_farming(self):
        from chef_battle.services import rating_award_for_win, RATING_REPEAT_WINDOW
        long_ago = timezone.now() - RATING_REPEAT_WINDOW - timezone.timedelta(days=1)
        battle = Battle.objects.create(
            challenger=self.a, opponent=self.b, theme="Ancient",
            status=Battle.Status.COMPLETED, winner=self.a, loser=self.b,
            start_time=long_ago, submission_deadline=long_ago,
            voting_deadline=long_ago, end_time=long_ago,
        )
        Battle.objects.filter(pk=battle.pk).update(updated_at=long_ago)
        fresh = rating_award_for_win(self.pa, self.pb, winner=self.a, loser=self.b)
        self.assertEqual(fresh, rating_award_for_win(self.pa, self.pb))


class MovesLedgerRecordsItsBalanceTests(TestCase):
    """G9 — the moves ledger could not be reconciled against the balance.

    tz_main.md section 17.7 asks for balance_after and it was never added, so
    nothing could prove a chef's move balance was the sum of its own history —
    while the token ledger has carried exactly that field since it was written.
    """

    def setUp(self):
        User = get_user_model()
        self.author = RecipeAuthor.objects.create(
            user=User.objects.create_user("g9-chef", password="pw"),
            name="G9 Chef", slug="g9-chef")
        ChefBattleProfile.objects.create(author=self.author, battle_moves=0)

    def test_every_award_and_spend_records_the_balance_it_produced(self):
        from chef_battle.energy_service import award_moves, spend_moves
        from chef_battle.models import BattleMoveTransaction
        TxType = BattleMoveTransaction.TxType

        award_moves(self.author, 5, TxType.ADMIN_ADJUSTMENT)
        award_moves(self.author, 7, TxType.ADMIN_ADJUSTMENT)
        spend_moves(self.author, 3, TxType.COMBAT_ACTION_SPENT)

        rows = list(BattleMoveTransaction.objects.filter(chef=self.author)
                    .order_by("created_at", "pk")
                    .values_list("amount", "balance_after"))
        self.assertEqual(rows, [(5, 5), (7, 12), (-3, 9)])

    def test_the_ledger_reconciles_against_the_profile(self):
        from chef_battle.energy_service import award_moves
        from chef_battle.models import BattleMoveTransaction
        TxType = BattleMoveTransaction.TxType

        for amount in (4, 6, 2):
            award_moves(self.author, amount, TxType.ADMIN_ADJUSTMENT)

        last = (BattleMoveTransaction.objects.filter(chef=self.author)
                .order_by("-created_at", "-pk").first())
        profile = ChefBattleProfile.objects.get(author=self.author)
        self.assertEqual(last.balance_after, profile.battle_moves,
                         "the last ledger row must agree with the balance it claims to explain")


class SeasonStandingCarriesTheRecordTests(TestCase):
    """G10 and G12 — a standing that can say what the chef actually did.

    A standing carried a score and a position only, so a season leaderboard
    could rank chefs and never show a record; and no battle carried a season,
    so the only way to ask which battles belonged to a season was a date
    window.
    """

    def setUp(self):
        from chef_battle.season_service import create_season
        User = get_user_model()
        self.a, self.b = [
            RecipeAuthor.objects.create(
                user=User.objects.create_user(f"g10-{n}", password="pw"),
                name=f"G10 {n}", slug=f"g10-{n}")
            for n in ("a", "b")
        ]
        ChefBattleProfile.objects.create(author=self.a, seasonal_score=30)
        ChefBattleProfile.objects.create(author=self.b, seasonal_score=10)
        now = timezone.now()
        self.season = create_season(
            name="Test Season",
            starts_at=now - timezone.timedelta(days=1),
            ends_at=now + timezone.timedelta(days=1),
            activate=True,
        )

    def _completed(self, winner, loser):
        now = timezone.now()
        return Battle.objects.create(
            challenger=winner, opponent=loser, theme="Season Dish",
            status=Battle.Status.COMPLETED, winner=winner, loser=loser,
            start_time=now, submission_deadline=now, voting_deadline=now, end_time=now,
        )

    def test_a_new_battle_is_stamped_with_the_active_season(self):
        battle = self._completed(self.a, self.b)
        self.assertEqual(battle.season_id, self.season.pk,
                         "G12: a battle must record the season it was fought in")

    def test_the_stamp_is_never_rewritten(self):
        battle = self._completed(self.a, self.b)
        self.season.status = self.season.Status.ENDED
        self.season.save(update_fields=["status"])
        battle.result_reason = "edited later"
        battle.save(update_fields=["result_reason", "season", "updated_at"])
        battle.refresh_from_db()
        self.assertEqual(battle.season_id, self.season.pk)

    def test_closing_a_season_freezes_wins_losses_and_streak(self):
        from chef_battle.season_service import close_season
        from chef_battle.models import SeasonStanding

        self._completed(self.a, self.b)
        self._completed(self.a, self.b)
        self._completed(self.b, self.a)
        self._completed(self.a, self.b)

        close_season(self.season)

        first = SeasonStanding.objects.get(season=self.season, chef=self.a)
        second = SeasonStanding.objects.get(season=self.season, chef=self.b)
        self.assertEqual((first.wins, first.losses), (3, 1))
        self.assertEqual((second.wins, second.losses), (1, 3))
        self.assertEqual(first.streak, 2, "the longest run inside the season, not the lifetime one")

    def test_the_record_is_the_seasons_own_and_not_the_lifetime_counters(self):
        from chef_battle.season_service import close_season
        from chef_battle.models import SeasonStanding

        ChefBattleProfile.objects.filter(author=self.a).update(wins=99, losses=42)
        self._completed(self.a, self.b)
        close_season(self.season)

        standing = SeasonStanding.objects.get(season=self.season, chef=self.a)
        self.assertEqual((standing.wins, standing.losses), (1, 0),
                         "a standing is a photograph of one season, not a copy of the profile")


class BattleEntrySubmitRequiresCookingPhaseTests(TestCase):
    """F12, 2026-08-11: battle_entry_submit only excluded SCHEDULED/MENU_LOCKED,
    so a chef could submit their dish (setting dish_submitted_at) while ACTIVE -
    before combat resolved, before the ingredient biathlon, before a moderator
    ever saw a photo. reveal_entries_if_ready's ACTIVE branch reads exactly
    that field to jump the battle straight to VOTING, so a battle could reach
    public voting with zero combat and zero moderated evidence. The gate now
    matches cooking_submit's own: COOKING only, the phase a moderator opens
    after approve_cooking_phase()."""

    def setUp(self):
        from recipes.models import Recipe
        User = get_user_model()
        u = User.objects.create_user("f12-ch", password="pw")
        self.ch = RecipeAuthor.objects.create(user=u, name="F12 Ch", slug="f12-ch")
        self.op = RecipeAuthor.objects.create(
            user=User.objects.create_user("f12-op", password="pw"), name="F12 Op", slug="f12-op")
        self.recipe = Recipe.objects.create(
            title="F12 Dish", slug="f12-dish", author=self.ch,
            category="meat", short_description="Test",
            ingredients="egg", method="cook", status=Recipe.Status.APPROVED,
        )
        self.now = timezone.now()
        self.client = Client()
        self.client.force_login(u)

    def _battle(self, status):
        return Battle.objects.create(
            challenger=self.ch, opponent=self.op, theme="F12 Battle",
            status=status, start_time=self.now,
            submission_deadline=self.now + timezone.timedelta(hours=1),
            voting_deadline=self.now + timezone.timedelta(days=1),
            end_time=self.now + timezone.timedelta(days=2),
        )

    def _post(self, battle):
        return self.client.post(
            reverse("chef_battle:battle_entry_submit", kwargs={"pk": battle.pk}),
            {"content_type": "photo", "recipe": self.recipe.pk, "battle_statement": "x"},
        )

    @override_settings(CHEF_BATTLE_ENABLED=True)
    def test_blocked_while_combat_is_active(self):
        battle = self._battle(Battle.Status.ACTIVE)
        resp = self._post(battle)
        self.assertEqual(resp.status_code, 302)
        self.assertEqual(battle.entries.count(), 0)

    @override_settings(CHEF_BATTLE_ENABLED=True)
    def test_blocked_during_ingredient_penalty_biathlon(self):
        battle = self._battle(Battle.Status.INGREDIENT_PENALTY)
        resp = self._post(battle)
        self.assertEqual(resp.status_code, 302)
        self.assertEqual(battle.entries.count(), 0)

    @override_settings(CHEF_BATTLE_ENABLED=True)
    def test_allowed_once_moderator_opens_cooking_phase(self):
        battle = self._battle(Battle.Status.COOKING)
        # battle_recipe_attach (MENU_LOCKED-only) is what normally creates
        # this row before combat; recreate just that much of the setup so the
        # COOKING-phase submission has an existing author-owned entry to fill in.
        BattleEntry.objects.create(battle=battle, author=self.ch)
        resp = self._post(battle)
        self.assertEqual(resp.status_code, 302)
        entry = battle.entries.get(author=self.ch)
        self.assertIsNotNone(entry.dish_submitted_at)
        self.assertEqual(entry.recipe_id, self.recipe.pk)


class ChallengeAcceptRequiresAgeVerificationTests(TestCase):
    """F13, 2026-08-11: gate_age_verified ran at challenge_create (on the
    challenger), token purchase and gift-sending, but never on the opponent
    who accepts - the one action that actually seats a chef in a real-money
    arena. A challenge can sit unanswered for up to twelve hours (X05), so
    the challenger's own age check at creation time cannot stand in for it."""

    def setUp(self):
        User = get_user_model()
        self.challenger = RecipeAuthor.objects.create(
            user=User.objects.create_user("f13-ch", password="pw"), name="F13 Ch", slug="f13-ch")
        self.op_user = User.objects.create_user("f13-op", password="pw")
        self.opponent = RecipeAuthor.objects.create(user=self.op_user, name="F13 Op", slug="f13-op")
        self.challenge = BattleChallenge.objects.create(
            challenger=self.challenger, opponent=self.opponent, theme="F13 Theme",
            expires_at=timezone.now() + timezone.timedelta(hours=12),
        )
        self.client = Client()
        self.client.force_login(self.op_user)

    @override_settings(CHEF_BATTLE_ENABLED=True)
    def test_accept_blocked_when_opponent_not_age_verified(self):
        resp = self.client.post(
            reverse("chef_battle:challenge_respond", kwargs={"pk": self.challenge.pk}),
            {"action": "accept"},
        )
        self.assertEqual(resp.status_code, 302)
        self.challenge.refresh_from_db()
        self.assertEqual(self.challenge.status, BattleChallenge.Status.PENDING)
        self.assertFalse(Battle.objects.filter(challenge=self.challenge).exists())

    @override_settings(CHEF_BATTLE_ENABLED=True)
    def test_accept_allowed_once_opponent_confirms_age(self):
        ChefBattleProfile.objects.create(author=self.opponent, age_verified=True)
        resp = self.client.post(
            reverse("chef_battle:challenge_respond", kwargs={"pk": self.challenge.pk}),
            {"action": "accept"},
        )
        self.challenge.refresh_from_db()
        self.assertEqual(self.challenge.status, BattleChallenge.Status.ACCEPTED)
        self.assertTrue(Battle.objects.filter(challenge=self.challenge).exists())


class ModerateEntryToPresentationRevealsEntriesTests(TestCase):
    """F14, 2026-08-11: operator_moderate_entry's own COOKING -> PRESENTATION
    transition (the only place PRESENTATION is ever set) didn't call the
    reveal update F10 added to operator_force_status and _score_battle - the
    one path into a _REVEAL_IMPLIED_TARGETS status that missed it, because it
    runs through real photo moderation rather than the operator console."""

    def setUp(self):
        from django.conf import settings as django_settings
        from django.core.files.base import ContentFile

        User = get_user_model()
        self.owner_user = User.objects.create_superuser("f14-greenbear", password="pw")
        self.owner_author, _ = RecipeAuthor.objects.update_or_create(
            slug=django_settings.OWNER_SLUG,
            defaults={"user": self.owner_user, "name": "F14 GreenBear"},
        )
        ua = User.objects.create_user("f14-chef-a", password="pw")
        ub = User.objects.create_user("f14-chef-b", password="pw")
        self.chef_a = RecipeAuthor.objects.create(user=ua, name="F14 Chef A", slug="f14-chef-a")
        self.chef_b = RecipeAuthor.objects.create(user=ub, name="F14 Chef B", slug="f14-chef-b")
        ChefBattleProfile.objects.create(author=self.chef_a, enrolled_at=timezone.now())
        ChefBattleProfile.objects.create(author=self.chef_b, enrolled_at=timezone.now())

        now = timezone.now()
        self.battle = Battle.objects.create(
            challenger=self.chef_a, opponent=self.chef_b, theme="F14 Dish",
            status=Battle.Status.COOKING, start_time=now,
            submission_deadline=now + timezone.timedelta(hours=1),
            voting_deadline=now + timezone.timedelta(days=1),
            end_time=now + timezone.timedelta(days=2),
        )
        self.entry_a = BattleEntry.objects.create(
            battle=self.battle, author=self.chef_a, dish_submitted_at=now,
            is_revealed=False, cooked_photo=ContentFile(b"fake", name="a.jpg"),
            real_photo_confirmed=True,
        )
        self.entry_b = BattleEntry.objects.create(
            battle=self.battle, author=self.chef_b, dish_submitted_at=now,
            is_revealed=False, cooked_photo=ContentFile(b"fake", name="b.jpg"),
            real_photo_confirmed=True,
        )

    def test_second_approval_reveals_both_entries(self):
        from chef_battle.services import operator_moderate_entry

        operator_moderate_entry(
            entry_id=self.entry_a.pk, operator_author=self.owner_author,
            new_status=BattleEntry.ModerationStatus.APPROVED,
        )
        self.battle.refresh_from_db()
        self.assertEqual(self.battle.status, Battle.Status.COOKING,
                          "one approval must not move the phase")

        operator_moderate_entry(
            entry_id=self.entry_b.pk, operator_author=self.owner_author,
            new_status=BattleEntry.ModerationStatus.APPROVED,
        )
        self.battle.refresh_from_db()
        self.assertEqual(self.battle.status, Battle.Status.PRESENTATION)
        self.assertTrue(
            all(self.battle.entries.values_list("is_revealed", flat=True)),
            "moderating both photos into PRESENTATION left an entry unrevealed",
        )


class EnrolBonusIsLockedAgainstDoubleCreditTests(TestCase):
    """F15, 2026-08-11: chef_enroll checked profile.enrolled_at with no lock
    before calling award_enrol_bonus, which itself does a plain read-modify-
    write on chest_moves/battle_moves - two concurrent submits (double-click,
    retried request) both saw enrolled_at=None and both credited the bonus.
    Now locks the profile row and re-checks enrolled_at under the lock, same
    pattern as F4/F5 - and the same SQL-mechanism testing convention: assert
    the lock exists rather than race real threads for a window that proves
    nothing."""

    def setUp(self):
        from recipes.models import Recipe
        User = get_user_model()
        u = User.objects.create_user("f15-chef", password="pw")
        self.author = RecipeAuthor.objects.create(user=u, name="F15 Chef", slug="f15-chef")
        Recipe.objects.create(
            title="F15 Prior Dish", slug="f15-prior-dish", author=self.author,
            category="meat", short_description="Test",
            ingredients="egg", method="cook", status=Recipe.Status.APPROVED,
        )
        self.client = Client()
        self.client.force_login(u)

    @override_settings(CHEF_BATTLE_ENABLED=True)
    def test_enrol_locks_the_profile_row(self):
        from django.test.utils import CaptureQueriesContext
        from django.db import connection

        with CaptureQueriesContext(connection) as ctx:
            self.client.post(reverse("chef_battle:chef_enroll"), {
                "confirm_age": "1", "confirm_rules": "1",
            })
        locking = [q["sql"] for q in ctx.captured_queries if "FOR UPDATE" in q["sql"].upper()]
        self.assertTrue(locking, "enrolment must take a row lock before crediting the bonus")

    @override_settings(CHEF_BATTLE_ENABLED=True)
    def test_second_submit_does_not_recredit_the_bonus(self):
        from chef_battle.models import BattleMoveTransaction

        self.client.post(reverse("chef_battle:chef_enroll"), {
            "confirm_age": "1", "confirm_rules": "1",
        })
        profile = ChefBattleProfile.objects.get(author=self.author)
        total_after_first = profile.chest_moves + profile.battle_moves
        self.assertGreater(total_after_first, 0, "the prior approved recipe must have earned a bonus")
        tx_count_after_first = BattleMoveTransaction.objects.filter(chef=self.author).count()

        # chef_enroll's own top-of-view enrolled_at check short-circuits a
        # second submit once enrolment succeeded; this pins that the second
        # request truly leaves the balance and ledger untouched.
        self.client.post(reverse("chef_battle:chef_enroll"), {
            "confirm_age": "1", "confirm_rules": "1",
        })
        profile.refresh_from_db()
        self.assertEqual(profile.chest_moves + profile.battle_moves, total_after_first)
        self.assertEqual(
            BattleMoveTransaction.objects.filter(chef=self.author).count(),
            tx_count_after_first,
        )


class ResetDisputedBattlesRevealsEntriesTests(TestCase):
    """F18, 2026-08-11: the admin bulk action moved DISPUTED battles straight
    to VOTING (a _REVEAL_IMPLIED_TARGETS status) through a bare queryset
    .update(), the same class of gap F10/F14 closed elsewhere - just reached
    through a direct admin bulk update instead of a service function."""

    def setUp(self):
        User = get_user_model()
        ua = User.objects.create_user("f18-chef-a", password="pw")
        ub = User.objects.create_user("f18-chef-b", password="pw")
        self.chef_a = RecipeAuthor.objects.create(user=ua, name="F18 Chef A", slug="f18-chef-a")
        self.chef_b = RecipeAuthor.objects.create(user=ub, name="F18 Chef B", slug="f18-chef-b")
        now = timezone.now()
        self.battle = Battle.objects.create(
            challenger=self.chef_a, opponent=self.chef_b, theme="F18 Dish",
            status=Battle.Status.DISPUTED, start_time=now,
            submission_deadline=now - timezone.timedelta(hours=1),
            voting_deadline=now + timezone.timedelta(days=1),
            end_time=now + timezone.timedelta(days=2),
        )
        for author in (self.chef_a, self.chef_b):
            BattleEntry.objects.create(
                battle=self.battle, author=author,
                battle_statement="Secret.", dish_submitted_at=now, is_revealed=False,
            )

    def test_bulk_reset_reveals_entries(self):
        from chef_battle.admin import reset_disputed_battles

        class _FakeModelAdmin:
            def message_user(self, *a, **k):
                pass

        reset_disputed_battles(_FakeModelAdmin(), None, Battle.objects.filter(pk=self.battle.pk))
        self.battle.refresh_from_db()
        self.assertEqual(self.battle.status, Battle.Status.VOTING)
        self.assertTrue(
            all(self.battle.entries.values_list("is_revealed", flat=True)),
            "bulk-resetting a disputed battle to VOTING left an entry unrevealed",
        )


class DoubleAcceptRaceReturnsFriendlyMessageTests(TestCase):
    """F19, 2026-08-11: Battle.challenge is a unique OneToOneField, so data
    integrity never actually broke under a double-accept race, but
    accept_challenge doesn't lock the challenge row and the view only caught
    ValueError - a second concurrent accept hit an unhandled IntegrityError,
    a bare 500. Simulated deterministically by pre-occupying the OneToOne slot
    the way a winning concurrent request would, rather than racing real
    threads for a window that proves nothing."""

    def setUp(self):
        self.challenger = RecipeAuthor.objects.create(
            user=get_user_model().objects.create_user("f19-ch", password="pw"),
            name="F19 Ch", slug="f19-ch")
        self.op_user = get_user_model().objects.create_user("f19-op", password="pw")
        self.opponent = RecipeAuthor.objects.create(user=self.op_user, name="F19 Op", slug="f19-op")
        ChefBattleProfile.objects.create(author=self.opponent, age_verified=True)
        self.challenge = BattleChallenge.objects.create(
            challenger=self.challenger, opponent=self.opponent, theme="F19 Theme",
            expires_at=timezone.now() + timezone.timedelta(hours=12),
        )
        now = timezone.now()
        Battle.objects.create(
            challenge=self.challenge, challenger=self.challenger, opponent=self.opponent,
            theme="F19 Theme", status=Battle.Status.MENU_LOCKED, start_time=now,
            submission_deadline=now + timezone.timedelta(hours=48),
            voting_deadline=now + timezone.timedelta(days=2),
            end_time=now + timezone.timedelta(days=2),
        )
        self.client = Client()
        self.client.force_login(self.op_user)

    @override_settings(CHEF_BATTLE_ENABLED=True)
    def test_racing_accept_gets_a_message_not_a_500(self):
        resp = self.client.post(
            reverse("chef_battle:challenge_respond", kwargs={"pk": self.challenge.pk}),
            {"action": "accept"},
        )
        self.assertEqual(resp.status_code, 302)

class CookingFormatSetsTheArtifactTierTests(TestCase):
    """G3 — «этого ещё и вправду нет — будем строить».

    chef_levels.md sets the winner's artifact tier from how the dish was
    cooked: a photo series draws from the basic pool, a live cook from the
    premium one, and webcam counts only when BOTH chefs streamed. The field it
    names never existed — while BattleEntryForm has carried the photo/video
    radio since it was written, collecting the answer and dropping it.
    """

    def setUp(self):
        User = get_user_model()
        self.a, self.b = [
            RecipeAuthor.objects.create(
                user=User.objects.create_user(f"g3-{n}", password="pw"),
                name=f"G3 {n}", slug=f"g3-{n}")
            for n in ("a", "b")
        ]
        now = timezone.now()
        self.battle = Battle.objects.create(
            challenger=self.a, opponent=self.b, theme="Format Dish",
            status=Battle.Status.ACTIVE,
            start_time=now, submission_deadline=now, voting_deadline=now, end_time=now,
        )

    def _entry(self, author, fmt):
        return BattleEntry.objects.create(
            battle=self.battle, author=author, cooking_format=fmt)

    def test_photos_draw_from_the_basic_pool(self):
        from chef_battle.services import drop_weights_for_battle
        fmt = BattleEntry.CookingFormat.PHOTOS
        self._entry(self.a, fmt)
        self._entry(self.b, fmt)
        self.assertEqual(set(drop_weights_for_battle(self.battle)), {"common", "uncommon"})

    def test_both_on_camera_draw_from_the_premium_pool(self):
        from chef_battle.services import drop_weights_for_battle
        fmt = BattleEntry.CookingFormat.WEBCAM
        self._entry(self.a, fmt)
        self._entry(self.b, fmt)
        self.assertEqual(set(drop_weights_for_battle(self.battle)),
                         {"rare", "epic", "legendary"})

    def test_a_mixed_battle_takes_the_lower_tier(self):
        """The document's own tie-break, and it is the strict one: one chef
        cooking to camera must not lift the other's prize pool."""
        from chef_battle.services import drop_weights_for_battle
        self._entry(self.a, BattleEntry.CookingFormat.WEBCAM)
        self._entry(self.b, BattleEntry.CookingFormat.PHOTOS)
        self.assertEqual(set(drop_weights_for_battle(self.battle)), {"common", "uncommon"})

    def test_a_battle_with_no_entries_is_not_premium(self):
        from chef_battle.services import drop_weights_for_battle
        self.assertEqual(set(drop_weights_for_battle(self.battle)), {"common", "uncommon"})

    def test_the_submission_form_stores_the_choice_it_collects(self):
        from chef_battle.forms import BattleEntryForm
        from recipes.models import Recipe

        recipe = Recipe.objects.create(
            author=self.a, title="Format Recipe", slug="format-recipe",
            status=Recipe.Status.APPROVED)
        # Built the way battle_entry_submit builds it: an instance carrying the
        # author, because BattleEntry.clean() checks recipe ownership against
        # it and the form only assigns the author in save().
        form = BattleEntryForm(
            {"content_type": "video", "recipe": recipe.pk, "battle_statement": "live"},
            instance=BattleEntry(battle=self.battle, author=self.a),
            author=self.a, battle=self.battle)
        self.assertTrue(form.is_valid(), form.errors)
        entry = form.save()
        self.assertEqual(entry.cooking_format, BattleEntry.CookingFormat.WEBCAM)


class SeasonRulesAreDataTests(TestCase):
    """G11 — a season's numbers were only ever changeable by deploying.

    tz_main.md section 17.12 lists crown_rule and reward_rules_json on Season
    and neither existed, so the rules lived in season_service.py. A season that
    sets nothing must behave exactly as every season has so far.
    """

    def _season(self, **kwargs):
        from chef_battle.models import Season
        now = timezone.now()
        return Season.objects.create(
            name="Rules Season", starts_at=now, ends_at=now + timezone.timedelta(days=30),
            **kwargs)

    def test_a_season_with_no_rules_pays_the_standing_numbers(self):
        from chef_battle.season_service import reward_rules, DEFAULT_REWARD_RULES
        self.assertEqual(reward_rules(self._season()), DEFAULT_REWARD_RULES)

    def test_no_season_at_all_pays_the_standing_numbers(self):
        from chef_battle.season_service import reward_rules, DEFAULT_REWARD_RULES
        self.assertEqual(reward_rules(None), DEFAULT_REWARD_RULES)

    def test_a_season_can_override_one_number_and_keep_the_rest(self):
        from chef_battle.season_service import reward_rules, DEFAULT_REWARD_RULES
        rules = reward_rules(self._season(reward_rules_json={"seasonal_win": 40}))
        self.assertEqual(rules["seasonal_win"], 40)
        self.assertEqual(rules["seasonal_second"], DEFAULT_REWARD_RULES["seasonal_second"])

    def test_a_malformed_override_costs_that_season_its_override_and_nothing_else(self):
        from chef_battle.season_service import reward_rules, DEFAULT_REWARD_RULES
        for junk in ("not a dict", [1, 2], {"seasonal_win": "ten"},
                     {"seasonal_win": -5}, {"seasonal_win": True}, {"unknown": 3}):
            self.assertEqual(
                reward_rules(self._season(reward_rules_json=junk))["seasonal_win"],
                DEFAULT_REWARD_RULES["seasonal_win"],
                f"{junk!r} must fall back rather than break a battle",
            )

    def test_the_crown_rule_is_text_for_a_human_and_falls_back(self):
        from chef_battle.season_service import crown_rule, DEFAULT_CROWN_RULE
        self.assertEqual(crown_rule(self._season()), DEFAULT_CROWN_RULE)
        self.assertEqual(
            crown_rule(self._season(crown_rule="Top of the ladder holds it all season.")),
            "Top of the ladder holds it all season.")


class StalledBattleIsVoidedNotDrawnTests(TestCase):
    """F20, 2026-08-11: battle_detail's inline auto-trigger called
    calculate_battle_result for ANY non-COMPLETED battle past end_time, no
    matter the phase. _score_battle's zero-vote tie-break can't tell "voting
    never opened" from "voting opened and tied 0-0", so a battle stuck in
    INGREDIENT_PENALTY (waiting on approve_cooking_phase), COOKING (waiting on
    a cooked photo and its moderation) or PRESENTATION (waiting on a vote) was
    scored as a paid draw - full rating/reputation/moves to both chefs for a
    battle nobody judged, and strictly better than a real loss since losing
    carries no penalty. Now cancelled with no reward to either side instead."""

    def setUp(self):
        User = get_user_model()
        self.ch = RecipeAuthor.objects.create(
            user=User.objects.create_user("f20-ch", password="pw"), name="F20 Ch", slug="f20-ch")
        self.op = RecipeAuthor.objects.create(
            user=User.objects.create_user("f20-op", password="pw"), name="F20 Op", slug="f20-op")

    def _stalled_battle(self, status, theme="F20 Stalled"):
        now = timezone.now()
        return Battle.objects.create(
            challenger=self.ch, opponent=self.op, theme=theme,
            status=status, start_time=now - timezone.timedelta(days=3),
            submission_deadline=now - timezone.timedelta(days=2),
            voting_deadline=now - timezone.timedelta(hours=1),
            end_time=now - timezone.timedelta(hours=1),
        )

    def test_cooking_phase_stalled_battle_is_voided_not_drawn(self):
        from chef_battle.services import void_stalled_battle
        battle = self._stalled_battle(Battle.Status.COOKING)
        void_stalled_battle(battle)
        self.assertEqual(battle.status, Battle.Status.CANCELLED)
        self.assertFalse(
            ChefBattleProfile.objects.filter(author__in=[self.ch, self.op]).exists(),
            "neither chef should have earned a profile/rating from a battle nobody judged",
        )

    def test_ingredient_penalty_and_presentation_also_void(self):
        from chef_battle.services import void_stalled_battle
        for status in (Battle.Status.INGREDIENT_PENALTY, Battle.Status.PRESENTATION):
            battle = self._stalled_battle(status, theme=f"F20 {status}")
            void_stalled_battle(battle)
            self.assertEqual(battle.status, Battle.Status.CANCELLED)

    def test_not_yet_expired_stalled_battle_is_left_alone(self):
        from chef_battle.services import void_stalled_battle
        now = timezone.now()
        battle = Battle.objects.create(
            challenger=self.ch, opponent=self.op, theme="F20 Not Yet",
            status=Battle.Status.COOKING, start_time=now,
            submission_deadline=now + timezone.timedelta(hours=1),
            voting_deadline=now + timezone.timedelta(days=1),
            end_time=now + timezone.timedelta(days=2),
        )
        void_stalled_battle(battle)
        self.assertEqual(battle.status, Battle.Status.COOKING)

    def test_already_completed_battle_is_untouched(self):
        from chef_battle.services import void_stalled_battle
        battle = self._stalled_battle(Battle.Status.COOKING)
        battle.status = Battle.Status.COMPLETED
        battle.save(update_fields=["status"])
        void_stalled_battle(battle)
        self.assertEqual(battle.status, Battle.Status.COMPLETED)

    def test_sweep_voids_all_qualifying_battles(self):
        from chef_battle.services import void_stalled_battles
        b1 = self._stalled_battle(Battle.Status.COOKING, theme="F20 Sweep A")
        b2 = self._stalled_battle(Battle.Status.INGREDIENT_PENALTY, theme="F20 Sweep B")
        count = void_stalled_battles()
        self.assertEqual(count, 2)
        b1.refresh_from_db()
        b2.refresh_from_db()
        self.assertEqual(b1.status, Battle.Status.CANCELLED)
        self.assertEqual(b2.status, Battle.Status.CANCELLED)

    @override_settings(CHEF_BATTLE_ENABLED=True)
    def test_battle_detail_view_voids_a_stalled_battle_instead_of_scoring_it(self):
        battle = self._stalled_battle(Battle.Status.COOKING)
        client = Client()
        client.force_login(self.ch.user)
        resp = client.get(reverse("chef_battle:battle_detail", kwargs={"pk": battle.pk}))
        self.assertEqual(resp.status_code, 200)
        battle.refresh_from_db()
        self.assertEqual(battle.status, Battle.Status.CANCELLED)

    @override_settings(CHEF_BATTLE_ENABLED=True)
    def test_battle_detail_view_still_scores_a_votable_battle_normally(self):
        # Regression: ACTIVE/VOTING past end_time is a real votable phase
        # (battle_vote's own gate accepts both) and must still resolve
        # through calculate_battle_result, not be swept as stalled.
        battle = self._stalled_battle(Battle.Status.VOTING, theme="F20 Real Result")
        client = Client()
        client.force_login(self.ch.user)
        resp = client.get(reverse("chef_battle:battle_detail", kwargs={"pk": battle.pk}))
        self.assertEqual(resp.status_code, 200)
        battle.refresh_from_db()
        self.assertEqual(battle.status, Battle.Status.COMPLETED)
        self.assertEqual(battle.result_reason, "Draw by public vote")


class AcceptChallengeSlotRaceTests(TestCase):
    """F21, 2026-08-11: slot_occupied_reason was checked unlocked in the view
    before accept_challenge ran, so two DIFFERENT pending challenges to the
    same chef, accepted near-simultaneously, both passed before either battle
    existed - G1's one-slot rule held for one challenge answered twice (F19's
    IntegrityError) but not for two different challenges answered together.
    accept_challenge now locks the accepting chef's profile row and re-checks
    the slot under it. Simulated deterministically by committing the first
    accept and then calling accept_challenge for the second challenge, rather
    than racing real threads for a window that proves nothing."""

    def setUp(self):
        User = get_user_model()
        self.x = RecipeAuthor.objects.create(
            user=User.objects.create_user("f21-x", password="pw"), name="F21 X", slug="f21-x")
        self.a = RecipeAuthor.objects.create(
            user=User.objects.create_user("f21-a", password="pw"), name="F21 A", slug="f21-a")
        self.b = RecipeAuthor.objects.create(
            user=User.objects.create_user("f21-b", password="pw"), name="F21 B", slug="f21-b")
        self.challenge_a = BattleChallenge.objects.create(
            challenger=self.a, opponent=self.x, theme="F21 Challenge A",
            expires_at=timezone.now() + timezone.timedelta(hours=12),
        )
        self.challenge_b = BattleChallenge.objects.create(
            challenger=self.b, opponent=self.x, theme="F21 Challenge B",
            expires_at=timezone.now() + timezone.timedelta(hours=12),
        )

    def test_second_accept_is_rejected_once_the_first_has_committed(self):
        from chef_battle.services import accept_challenge
        accept_challenge(self.challenge_a)
        with self.assertRaises(ValueError):
            accept_challenge(self.challenge_b)
        self.challenge_b.refresh_from_db()
        self.assertEqual(self.challenge_b.status, BattleChallenge.Status.PENDING)
        self.assertFalse(Battle.objects.filter(challenge=self.challenge_b).exists())

    def test_view_surfaces_the_slot_error_instead_of_creating_a_second_battle(self):
        from chef_battle.services import accept_challenge
        accept_challenge(self.challenge_a)
        client = Client()
        client.force_login(self.x.user)
        with override_settings(CHEF_BATTLE_ENABLED=True):
            resp = client.post(
                reverse("chef_battle:challenge_respond", kwargs={"pk": self.challenge_b.pk}),
                {"action": "accept"},
            )
        self.assertEqual(resp.status_code, 302)
        self.challenge_b.refresh_from_db()
        self.assertEqual(self.challenge_b.status, BattleChallenge.Status.PENDING)

    def test_the_second_challenge_can_be_accepted_once_the_first_battle_ends(self):
        from chef_battle.services import accept_challenge
        battle_a = accept_challenge(self.challenge_a)
        walk_battle_to(battle_a, Battle.Status.COMPLETED)
        battle_b = accept_challenge(self.challenge_b)
        self.assertIsNotNone(battle_b.pk)


