class ScorerAcceptsOnlyVotingTests(TestCase):
    """T01, Owner brief 2026-08-12 — the scorer's source state is a contract.

    calculate_battle_result used to accept every status except COMPLETED, so a
    cancelled, void, walkover, paused, disputed, scheduled, menu-locked, active,
    cooking or presentation battle could be finished AND PAID by any caller that
    reached it — and with no votes cast the tie-break paid both chefs a draw for
    a fight that never happened. v2.5.1010 narrowed the one caller in
    battle_detail and left the scorer open.
    """

    REFUSED = [
        Battle.Status.SCHEDULED, Battle.Status.MENU_LOCKED, Battle.Status.ACTIVE,
        Battle.Status.AWAITING_SUBMISSIONS, Battle.Status.REVEALED,
        Battle.Status.COOKING, Battle.Status.PRESENTATION,
        Battle.Status.INGREDIENT_PENALTY, Battle.Status.PAUSED,
        Battle.Status.CANCELLED, Battle.Status.DISPUTED,
        Battle.Status.WAITING, Battle.Status.WALKOVER, Battle.Status.VOID,
    ]

    def setUp(self):
        User = get_user_model()
        self.a, self.b = [
            RecipeAuthor.objects.create(
                user=User.objects.create_user(f"t01-{n}", password="pw"),
                name=f"T01 {n}", slug=f"t01-{n}")
            for n in ("a", "b")
        ]
        self.pa = ChefBattleProfile.objects.create(author=self.a)
        self.pb = ChefBattleProfile.objects.create(author=self.b)

    def _battle(self, status):
        past = timezone.now() - timezone.timedelta(hours=1)
        return Battle.objects.create(
            challenger=self.a, opponent=self.b, theme="T01 Dish", status=status,
            start_time=past, submission_deadline=past, voting_deadline=past,
            end_time=past,
        )

    def _snapshot(self):
        fields = ("rating", "reputation", "wins", "losses", "seasonal_score",
                  "battle_moves", "crown_count", "crown_until", "win_streak", "rank")
        out = {}
        for profile in (self.pa, self.pb):
            profile.refresh_from_db()
            out[profile.pk] = {f: getattr(profile, f) for f in fields}
        return out

    def test_every_non_voting_status_is_refused_and_pays_nothing(self):
        from chef_battle.models import BattleMoveTransaction, RewardRecord
        from chef_battle.services import calculate_battle_result

        for status in self.REFUSED:
            with self.subTest(status=status):
                battle = self._battle(status)
                before = self._snapshot()
                moves_before = BattleMoveTransaction.objects.count()
                rewards_before = RewardRecord.objects.count()

                calculate_battle_result(battle)

                battle.refresh_from_db()
                self.assertEqual(
                    battle.status, status,
                    f"a {status} battle must not be moved by the ordinary scorer")
                self.assertIsNone(battle.winner_id)
                self.assertEqual(self._snapshot(), before,
                                 f"a {status} battle paid a chef something")
                self.assertEqual(BattleMoveTransaction.objects.count(), moves_before)
                self.assertEqual(RewardRecord.objects.count(), rewards_before)

    def test_an_expired_active_battle_with_no_votes_is_not_a_paid_draw(self):
        """The exact shape the brief names: expired ACTIVE, zero votes, a plain
        GET. It used to be scored, and the zero-vote tie-break paid both chefs
        the second-place share."""
        from chef_battle.services import calculate_battle_result

        battle = self._battle(Battle.Status.ACTIVE)
        before = self._snapshot()
        calculate_battle_result(battle)
        battle.refresh_from_db()
        self.assertEqual(battle.status, Battle.Status.ACTIVE)
        self.assertEqual(self._snapshot(), before)

    def test_voting_still_completes_exactly_once(self):
        from chef_battle.models import BattleVote
        from chef_battle.services import calculate_battle_result

        battle = self._battle(Battle.Status.VOTING)
        User = get_user_model()
        BattleVote.objects.create(
            battle=battle, voted_for=self.a,
            voter=User.objects.create_user("t01-voter", password="pw"))

        calculate_battle_result(battle)
        battle.refresh_from_db()
        self.assertEqual(battle.status, Battle.Status.COMPLETED)
        self.assertEqual(battle.winner_id, self.a.pk)

        self.pa.refresh_from_db()
        wins_after_first = self.pa.wins
        rating_after_first = self.pa.rating

        calculate_battle_result(battle)   # a second sweep lands on the same row
        self.pa.refresh_from_db()
        self.assertEqual(self.pa.wins, wins_after_first, "scored twice")
        self.assertEqual(self.pa.rating, rating_after_first, "paid twice")

    def test_the_callers_object_is_told_the_truth_when_it_is_stale(self):
        """A caller holding a battle it read minutes ago must not be able to
        write its own older idea of the status back over a terminal one."""
        from chef_battle.services import calculate_battle_result

        battle = self._battle(Battle.Status.VOTING)
        stale = Battle.objects.get(pk=battle.pk)          # the caller's copy
        Battle.objects.filter(pk=battle.pk).update(status=Battle.Status.CANCELLED)

        calculate_battle_result(stale)

        self.assertEqual(stale.status, Battle.Status.CANCELLED,
                         "the caller's object must be corrected from the locked row")
        battle.refresh_from_db()
        self.assertEqual(battle.status, Battle.Status.CANCELLED)


class AdminForceCompleteFollowsTheScorerContractTests(TestCase):
    """T01 — the admin action used to count every battle it touched as
    force-completed whether or not anything happened, so an operator pressing
    it on a cancelled battle was told it worked."""

    def setUp(self):
        User = get_user_model()
        self.a, self.b = [
            RecipeAuthor.objects.create(
                user=User.objects.create_user(f"t01adm-{n}", password="pw"),
                name=f"T01 adm {n}", slug=f"t01adm-{n}")
            for n in ("a", "b")
        ]
        ChefBattleProfile.objects.create(author=self.a)
        ChefBattleProfile.objects.create(author=self.b)

    def test_it_reports_what_the_contract_refused(self):
        from chef_battle.admin import force_complete_battles

        past = timezone.now() - timezone.timedelta(hours=1)
        cancelled = Battle.objects.create(
            challenger=self.a, opponent=self.b, theme="Refused",
            status=Battle.Status.CANCELLED,
            start_time=past, submission_deadline=past, voting_deadline=past,
            end_time=past,
        )

        said = []

        class _Admin:
            def message_user(self, request, message, level=None):
                said.append(message)

        force_complete_battles(_Admin(), None, Battle.objects.filter(pk=cancelled.pk))

        cancelled.refresh_from_db()
        self.assertEqual(cancelled.status, Battle.Status.CANCELLED)
        self.assertTrue(any("0 battle(s) force-completed" in m for m in said))
        self.assertTrue(any("only accepts a battle in Voting" in m for m in said),
                        "the operator must be told it did nothing")



class RevealIsAtomicAndCannotResurrectTests(TestCase):
    """T02, Owner brief 2026-08-12 - reveal_entries_if_ready had neither a
    transaction nor a lock.

    It branched on the CALLER's status, counted entries outside any lock, and
    then wrote status back. A battle cancelled, voided or paused between that
    read and that write was dragged back into ACTIVE or VOTING - with both
    dishes revealed to the public - by nothing heavier than someone opening
    the battle page.
    """

    TERMINAL = [
        Battle.Status.CANCELLED, Battle.Status.VOID, Battle.Status.PAUSED,
        Battle.Status.WALKOVER, Battle.Status.COMPLETED, Battle.Status.DISPUTED,
    ]

    def setUp(self):
        User = get_user_model()
        self.a, self.b = [
            RecipeAuthor.objects.create(
                user=User.objects.create_user(f"t02-{n}", password="pw"),
                name=f"T02 {n}", slug=f"t02-{n}")
            for n in ("a", "b")
        ]
        ChefBattleProfile.objects.create(author=self.a)
        ChefBattleProfile.objects.create(author=self.b)

    def _battle(self, status, *, submitted=2, deadline_passed=True):
        now = timezone.now()
        offset = -1 if deadline_passed else 1
        battle = Battle.objects.create(
            challenger=self.a, opponent=self.b, theme="T02 Dish", status=status,
            start_time=now - timezone.timedelta(hours=2),
            submission_deadline=now + timezone.timedelta(hours=offset),
            voting_deadline=now + timezone.timedelta(hours=6),
            end_time=now + timezone.timedelta(hours=6),
        )
        for index, author in enumerate((self.a, self.b)):
            BattleEntry.objects.create(
                battle=battle, author=author,
                dish_submitted_at=now if index < submitted else None,
            )
        return battle

    def test_a_battle_that_went_terminal_under_us_is_never_advanced(self):
        from chef_battle.services import reveal_entries_if_ready

        for source in (Battle.Status.MENU_LOCKED, Battle.Status.ACTIVE):
            for terminal in self.TERMINAL:
                with self.subTest(source=source, terminal=terminal):
                    battle = self._battle(source)
                    stale = Battle.objects.get(pk=battle.pk)   # the caller's copy
                    Battle.objects.filter(pk=battle.pk).update(status=terminal)

                    reveal_entries_if_ready(stale)

                    battle.refresh_from_db()
                    self.assertEqual(battle.status, terminal,
                                     "a terminal battle was resurrected by a reveal")
                    self.assertEqual(stale.status, terminal,
                                     "the caller must be corrected from the locked row")
                    self.assertFalse(
                        battle.entries.filter(is_revealed=True).exists(),
                        "the dishes of a cancelled battle were made public")

    def test_menu_locked_still_opens_combat_when_both_dishes_are_in(self):
        from chef_battle.services import reveal_entries_if_ready

        battle = self._battle(Battle.Status.MENU_LOCKED, deadline_passed=False)
        reveal_entries_if_ready(battle)
        battle.refresh_from_db()
        self.assertEqual(battle.status, Battle.Status.ACTIVE)
        self.assertEqual(battle.entries.filter(is_revealed=True).count(), 2)

    def test_menu_locked_still_opens_combat_on_the_deadline_alone(self):
        from chef_battle.services import reveal_entries_if_ready

        battle = self._battle(Battle.Status.MENU_LOCKED, submitted=0)
        reveal_entries_if_ready(battle)
        battle.refresh_from_db()
        self.assertEqual(battle.status, Battle.Status.ACTIVE)

    def test_menu_locked_waits_when_neither_the_dishes_nor_the_deadline_are_in(self):
        from chef_battle.services import reveal_entries_if_ready

        battle = self._battle(
            Battle.Status.MENU_LOCKED, submitted=1, deadline_passed=False)
        reveal_entries_if_ready(battle)
        battle.refresh_from_db()
        self.assertEqual(battle.status, Battle.Status.MENU_LOCKED)
        self.assertFalse(battle.entries.filter(is_revealed=True).exists())

    def test_active_advances_only_on_both_dishes_and_is_idempotent(self):
        from chef_battle.services import reveal_entries_if_ready

        battle = self._battle(Battle.Status.ACTIVE)
        reveal_entries_if_ready(battle)
        battle.refresh_from_db()
        self.assertEqual(battle.status, Battle.Status.VOTING)

        updated_at = battle.updated_at
        reveal_entries_if_ready(battle)          # a second page view
        battle.refresh_from_db()
        self.assertEqual(battle.status, Battle.Status.VOTING)
        self.assertEqual(battle.updated_at, updated_at,
                         "a repeat reveal wrote to a battle it had already advanced")
        self.assertEqual(battle.entries.filter(is_revealed=True).count(), 2)

    def test_active_does_not_advance_on_the_deadline_alone(self):
        """F68 stays closed: an ACTIVE battle past its deadline is a no-show
        for handle_no_show_battles, not a free trip to a public vote."""
        from chef_battle.services import reveal_entries_if_ready

        battle = self._battle(Battle.Status.ACTIVE, submitted=1)
        reveal_entries_if_ready(battle)
        battle.refresh_from_db()
        self.assertEqual(battle.status, Battle.Status.ACTIVE)
        self.assertFalse(battle.entries.filter(is_revealed=True).exists())


class RevealSerialisesAgainstACancellationTests(TransactionTestCase):
    """T02 - the real interleaving, with two connections and a barrier.

    Captured SQL proves a FOR UPDATE was emitted; it does not prove the reveal
    WAITS for the cancelling transaction and then re-reads what it committed.
    One thread holds the battle locked and cancels it; the other calls the
    reveal on a stale MENU_LOCKED instance and must come out with a cancelled
    battle and two hidden dishes.
    """

    def test_a_reveal_that_waits_on_a_cancellation_sees_the_cancellation(self):
        import threading
        import time
        from django.db import connections, transaction
        from chef_battle.services import reveal_entries_if_ready

        User = get_user_model()
        a, b = [
            RecipeAuthor.objects.create(
                user=User.objects.create_user(f"t02race-{n}", password="pw"),
                name=f"T02 race {n}", slug=f"t02race-{n}")
            for n in ("a", "b")
        ]
        ChefBattleProfile.objects.create(author=a)
        ChefBattleProfile.objects.create(author=b)
        now = timezone.now()
        battle = Battle.objects.create(
            challenger=a, opponent=b, theme="T02 race",
            status=Battle.Status.MENU_LOCKED,
            start_time=now - timezone.timedelta(hours=2),
            submission_deadline=now - timezone.timedelta(hours=1),
            voting_deadline=now + timezone.timedelta(hours=6),
            end_time=now + timezone.timedelta(hours=6),
        )
        for author in (a, b):
            BattleEntry.objects.create(
                battle=battle, author=author, dish_submitted_at=now)

        stale = Battle.objects.get(pk=battle.pk)     # read before either thread
        start = threading.Barrier(2)
        errors = []

        def cancel():
            try:
                start.wait(timeout=10)
                with transaction.atomic():
                    locked = Battle.objects.select_for_update().get(pk=battle.pk)
                    time.sleep(0.4)                  # the reveal blocks in here
                    locked.status = Battle.Status.CANCELLED
                    locked.save(update_fields=["status", "updated_at"])
            except Exception as exc:
                errors.append(exc)
            finally:
                connections.close_all()

        def reveal():
            try:
                start.wait(timeout=10)
                time.sleep(0.1)                      # arrive second, on purpose
                reveal_entries_if_ready(stale)
            except Exception as exc:
                errors.append(exc)
            finally:
                connections.close_all()

        threads = [threading.Thread(target=cancel), threading.Thread(target=reveal)]
        for thread in threads:
            thread.start()
        for thread in threads:
            thread.join(timeout=30)

        self.assertEqual(errors, [])
        battle.refresh_from_db()
        self.assertEqual(battle.status, Battle.Status.CANCELLED,
                         "the reveal overwrote a cancellation it had waited for")
        self.assertFalse(battle.entries.filter(is_revealed=True).exists())



@override_settings(CHEF_BATTLE_ENABLED=True)
class BothChefsPressReadyAtOnceTests(TransactionTestCase):
    """T03, Owner brief 2026-08-12 - the proof the F67 fix was missing.

    F67 (v2.5.1016) put the lock in battle_set_ready and asserted it by finding
    FOR UPDATE in the captured SQL. That proves a lock was REQUESTED; it does
    not prove the second chef's request waits for the first to commit and then
    re-reads the flag it wrote. Two threads, two connections and a barrier do,
    and this is the exact moment the race happens in real life: both chefs are
    standing in the antechamber watching the same clock, and they click
    together.

    Before the lock, each request read the other's flag as False and wrote it
    back False on save, so whichever committed first was erased - and that chef
    could not press Ready again once the status left SCHEDULED, losing the grace
    period to an unearned walkover.
    """

    def _post_together(self, clients, url):
        """Fire one POST per client from its own thread, released together."""
        import threading
        from django.db import connections

        start = threading.Barrier(len(clients))
        errors, codes = [], []

        def press(client):
            try:
                start.wait(timeout=10)
                codes.append(client.post(url).status_code)
            except Exception as exc:          # surfaced below, never swallowed
                errors.append(exc)
            finally:
                connections.close_all()

        threads = [threading.Thread(target=press, args=(c,)) for c in clients]
        for thread in threads:
            thread.start()
        for thread in threads:
            thread.join(timeout=30)
        self.assertEqual(errors, [])
        return codes

    def setUp(self):
        User = get_user_model()
        self.challenger = RecipeAuthor.objects.create(
            user=User.objects.create_user("t03-ch", password="pw"),
            name="T03 Challenger", slug="t03-ch")
        self.opponent = RecipeAuthor.objects.create(
            user=User.objects.create_user("t03-op", password="pw"),
            name="T03 Opponent", slug="t03-op")
        ChefBattleProfile.objects.create(author=self.challenger)
        ChefBattleProfile.objects.create(author=self.opponent)
        now = timezone.now()
        self.original_start = now + timezone.timedelta(hours=6)
        self.battle = Battle.objects.create(
            challenger=self.challenger, opponent=self.opponent, theme="T03 theme",
            status=Battle.Status.SCHEDULED, start_time=self.original_start,
            submission_deadline=now + timezone.timedelta(days=2),
            voting_deadline=now + timezone.timedelta(days=4),
            end_time=now + timezone.timedelta(days=5),
        )
        self.url = reverse("chef_battle:battle_set_ready", args=[self.battle.pk])
        self.chef_client = Client()
        self.chef_client.force_login(self.challenger.user)
        self.rival_client = Client()
        self.rival_client.force_login(self.opponent.user)

    def _started_events(self):
        return BattleEvent.objects.filter(
            battle=self.battle, event_type=BattleEvent.EventType.BATTLE_STARTED)

    def test_two_simultaneous_clicks_both_survive_and_start_moves_once(self):
        codes = self._post_together([self.chef_client, self.rival_client], self.url)
        self.assertEqual(codes, [302, 302])

        self.battle.refresh_from_db()
        self.assertTrue(self.battle.challenger_ready, "the challenger's click was erased")
        self.assertTrue(self.battle.opponent_ready, "the opponent's click was erased")
        self.assertLess(self.battle.start_time, self.original_start,
                        "both chefs are ready and the start was never pulled forward")
        self.assertEqual(self.battle.status, Battle.Status.SCHEDULED,
                         "Ready must not teleport the battle out of SCHEDULED")
        self.assertEqual(self._started_events().count(), 1,
                         "the both-ready announcement fired more than once")

    def test_pressing_ready_again_afterwards_changes_nothing(self):
        self._post_together([self.chef_client, self.rival_client], self.url)
        self.battle.refresh_from_db()
        settled_start = self.battle.start_time
        settled_updated = self.battle.updated_at

        for client in (self.chef_client, self.rival_client):
            self.assertEqual(client.post(self.url).status_code, 302)

        self.battle.refresh_from_db()
        self.assertTrue(self.battle.challenger_ready)
        self.assertTrue(self.battle.opponent_ready)
        self.assertEqual(self.battle.start_time, settled_start)
        self.assertEqual(self.battle.updated_at, settled_updated,
                         "a repeated Ready wrote to the battle again")
        self.assertEqual(self._started_events().count(), 1)

    def test_one_chef_double_clicking_does_not_make_a_pair(self):
        """The same chef twice is not both chefs: the second click must not
        satisfy the pair check on the strength of the first."""
        second_tab = Client()
        second_tab.force_login(self.challenger.user)
        codes = self._post_together([self.chef_client, second_tab], self.url)
        self.assertEqual(codes, [302, 302])

        self.battle.refresh_from_db()
        self.assertTrue(self.battle.challenger_ready)
        self.assertFalse(self.battle.opponent_ready)
        self.assertEqual(self.battle.start_time, self.original_start,
                         "one chef clicking twice pulled the start forward")
        self.assertEqual(self._started_events().count(), 0)



class CombatLogAndChatNeverParseAChefsNameTests(TestCase):
    """T04, Owner brief 2026-08-12 - stored XSS in the combat log.

    BattleRound.log_message is built server-side out of BOTH chefs' own names
    ("{attacker.name} lands a full hit on {defender.name}"), stored, and then
    handed to the browser as JSON by battle_state_poll and combat_action. Two
    call sites wrote it straight into innerHTML - the battle page's own combat
    script and main.js - so a chef who called himself an <img onerror> tag ran
    script in every spectator's browser, once per round, for as long as the log
    was on screen. The battle chat had the same shape with a hand-rolled
    "replace every <" pass, which leaves the ampersand wrong and is one
    forgotten call site from being an injection again.

    The fix is the DOM API, not server-side escaping: the payload IS the name,
    and a name is text.
    """

    PAYLOAD = '<img src=x onerror="window.__pwned=1">'

    #: Values that reach the browser as JSON and are wholly or partly typed by
    #: a chef. None of them may ever be concatenated into markup.
    TAINTED = (
        "log_message", "display_name", "msg.body", "combat_winner",
        "challenger_name", "opponent_name", "dataset.label", "data.url",
    )

    def _scripts(self):
        from django.conf import settings
        root = settings.BASE_DIR
        paths = sorted((root / "templates" / "chef_battle").glob("*.html"))
        paths += [root / "static" / "js" / "main.js"]
        paths += sorted((root / "static" / "js").glob("arena_*.js"))
        return [(p, p.read_text(encoding="utf-8")) for p in paths]

    def test_no_battle_or_arena_script_writes_tainted_data_as_markup(self):
        offenders = []
        for path, source in self._scripts():
            for number, line in enumerate(source.splitlines(), 1):
                if "innerHTML" not in line and "insertAdjacentHTML" not in line:
                    continue
                if "=" not in line and "insertAdjacentHTML" not in line:
                    continue
                for token in self.TAINTED:
                    if token in line:
                        offenders.append(f"{path.name}:{number}: {line.strip()[:120]}")
        self.assertEqual(
            offenders, [],
            "user-controlled text is being written as markup:\n" + "\n".join(offenders))

    def test_the_combat_log_row_is_built_from_nodes(self):
        from django.conf import settings

        template = (settings.BASE_DIR / "templates" / "chef_battle"
                    / "battle_detail.html").read_text(encoding="utf-8")
        self.assertIn("function buildCombatLogRow(r)", template)
        self.assertIn("message.textContent = r.log_message;", template)

    def test_the_server_stores_the_payload_verbatim_so_the_browser_is_the_defence(self):
        """Not a bug - a chef may call himself what he likes, and the log is a
        record of what he called himself. This pins WHERE the defence lives:
        the string arrives at the browser intact, so the rendering has to be
        safe rather than the storage sanitised."""
        from chef_battle.models import BattleRound

        User = get_user_model()
        attacker = RecipeAuthor.objects.create(
            user=User.objects.create_user("t04-a", password="pw"),
            name=self.PAYLOAD, slug="t04-a")
        defender = RecipeAuthor.objects.create(
            user=User.objects.create_user("t04-b", password="pw"),
            name="T04 Defender", slug="t04-b")
        ChefBattleProfile.objects.create(author=attacker)
        ChefBattleProfile.objects.create(author=defender)
        now = timezone.now()
        battle = Battle.objects.create(
            challenger=attacker, opponent=defender, theme="T04",
            status=Battle.Status.ACTIVE, start_time=now,
            submission_deadline=now + timezone.timedelta(days=2),
            voting_deadline=now + timezone.timedelta(days=4),
            end_time=now + timezone.timedelta(days=5),
        )
        round_obj = BattleRound.objects.create(
            battle=battle, round_number=1, attacker=attacker, defender=defender,
            attack_power=10, defence_power=5,
            outcome=BattleRound.Outcome.FULL_HIT,
            challenger_hits=1, opponent_hits=0,
            log_message=f"{attacker.name} lands a full hit on {defender.name}. (10 vs 5)",
        )
        round_obj.refresh_from_db()
        self.assertIn(self.PAYLOAD, round_obj.log_message)



class CookedPhotoIsAValidatedNormalisedImageTests(TestCase):
    """T05, Owner brief 2026-08-12 - BattleEntry.cooked_photo had NO validation.

    Every other image field on the site carries validate_image_upload; this one,
    the file a chef submits as EVIDENCE of a cooked dish and which the arena
    publishes after moderation, carried nothing. The chef's own bytes were
    stored under the chef's own filename and served back from /media, so an
    .html file, an SVG with a script in it, or a polyglot that is a valid JPEG
    AND valid HTML went straight onto the site.

    The upload is now decoded and RE-ENCODED. Nothing the uploader supplied
    survives: not the container, not the metadata, not the name.
    """

    def setUp(self):
        User = get_user_model()
        self.chef = RecipeAuthor.objects.create(
            user=User.objects.create_user("t05-ch", password="pw"),
            name="T05 Chef", slug="t05-ch")
        self.rival = RecipeAuthor.objects.create(
            user=User.objects.create_user("t05-op", password="pw"),
            name="T05 Rival", slug="t05-op")
        ChefBattleProfile.objects.create(author=self.chef)
        ChefBattleProfile.objects.create(author=self.rival)
        now = timezone.now()
        self.battle = Battle.objects.create(
            challenger=self.chef, opponent=self.rival, theme="T05",
            status=Battle.Status.COOKING, start_time=now,
            submission_deadline=now + timezone.timedelta(days=2),
            voting_deadline=now + timezone.timedelta(days=4),
            end_time=now + timezone.timedelta(days=5),
        )
        BattleEntry.objects.create(battle=self.battle, author=self.chef)
        BattleEntry.objects.create(battle=self.battle, author=self.rival)

    # ── helpers ──────────────────────────────────────────────────────────────

    def _image_bytes(self, fmt, size=(64, 48), colour=(200, 100, 50)):
        from io import BytesIO
        from PIL import Image

        buffer = BytesIO()
        Image.new("RGB", size, colour).save(buffer, format=fmt)
        return buffer.getvalue()

    def _upload(self, name, content, content_type="image/jpeg"):
        from django.core.files.uploadedfile import SimpleUploadedFile
        return SimpleUploadedFile(name, content, content_type=content_type)

    def _submit(self, upload):
        from chef_battle.services import submit_cooked_photo
        return submit_cooked_photo(
            battle=self.battle, author=self.chef, photo=upload,
            real_photo_confirmed=True)

    # ── what must be refused ─────────────────────────────────────────────────

    def test_refusals(self):
        from django.core.exceptions import ValidationError
        from chef_battle.models import BattleEntry as Entry

        html = b"<html><script>window.__pwned=1</script></html>"
        svg = (b'<svg xmlns="http://www.w3.org/2000/svg" onload="window.__pwned=1">'
               b'<text>dish</text></svg>')
        cases = {
            "HTML named .html": self._upload("dish.html", html, "text/html"),
            "HTML named .jpg": self._upload("dish.jpg", html, "image/jpeg"),
            "SVG named .svg": self._upload("dish.svg", svg, "image/svg+xml"),
            "SVG named .png": self._upload("dish.png", svg, "image/png"),
            "a truncated JPEG": self._upload(
                "dish.jpg", self._image_bytes("JPEG")[:120], "image/jpeg"),
            "an empty file": self._upload("dish.jpg", b"", "image/jpeg"),
            "a polyglot": self._upload(
                "dish.jpg", self._image_bytes("JPEG") + html, "image/jpeg"),
        }
        for label, upload in cases.items():
            with self.subTest(case=label):
                if label == "a polyglot":
                    # A polyglot DECODES - no decoder test can refuse it. What
                    # closes it is that the trailing payload is not pixels and
                    # therefore is not in the re-encoded file.
                    entry = self._submit(upload)
                    entry.refresh_from_db()
                    stored = entry.cooked_photo.read()
                    self.assertNotIn(b"<script", stored,
                                     "the appended payload survived re-encoding")
                    entry.cooked_photo.delete(save=True)
                    Entry.objects.filter(pk=entry.pk).update(cooked_photo="")
                    continue
                with self.assertRaises(ValidationError):
                    self._submit(upload)
                self.assertFalse(
                    Entry.objects.get(battle=self.battle, author=self.chef).cooked_photo,
                    f"{label} was stored before it validated")

    def test_a_file_over_the_byte_ceiling_is_refused(self):
        from django.core.exceptions import ValidationError
        from recipes.validators import NORMALISED_IMAGE_MAX_BYTES

        oversized = self._upload(
            "dish.jpg", b"\xff\xd8\xff" + b"\x00" * NORMALISED_IMAGE_MAX_BYTES)
        with self.assertRaises(ValidationError) as caught:
            self._submit(oversized)
        self.assertIn("MB or smaller", caught.exception.messages[0])

    def test_an_image_over_the_pixel_ceiling_is_refused_before_it_is_decoded(self):
        """A decompression bomb is small on disk and enormous in memory: the
        dimensions are read from the header and judged before any pixel is
        allocated."""
        from django.core.exceptions import ValidationError
        from recipes.validators import normalise_uploaded_image

        bomb = self._upload("bomb.png", self._image_bytes("PNG", size=(20000, 20000)),
                            "image/png")
        with self.assertRaises(ValidationError) as caught:
            normalise_uploaded_image(bomb, prefix="cooked", max_pixels=1_000_000)
        self.assertEqual(caught.exception.code, "image_too_large")

    # ── what must be accepted, and what is stored ────────────────────────────

    def test_each_accepted_format_is_stored_under_a_name_this_server_generated(self):
        from PIL import Image

        for fmt, claimed_name in (("JPEG", "my dish.jpg"),
                                  ("PNG", "my dish.png"),
                                  ("WEBP", "my dish.webp")):
            with self.subTest(fmt=fmt):
                BattleEntry.objects.filter(
                    battle=self.battle, author=self.chef).update(cooked_photo="")
                upload = self._upload(claimed_name, self._image_bytes(fmt))
                entry = self._submit(upload)

                entry.refresh_from_db()
                self.assertTrue(entry.cooked_photo)
                stored_name = entry.cooked_photo.name.rsplit("/", 1)[-1]
                self.assertTrue(stored_name.startswith("cooked-"),
                                f"stored as {stored_name}, not a server-generated name")
                self.assertNotIn("my dish", stored_name)
                entry.cooked_photo.open()
                with Image.open(entry.cooked_photo) as image:
                    self.assertEqual(image.format, fmt)
                entry.cooked_photo.delete(save=True)

    def test_the_extension_a_chef_typed_does_not_decide_the_format(self):
        """A real PNG named .jpg is still a PNG, and is stored as one."""
        from PIL import Image

        entry = self._submit(self._upload("dish.jpg", self._image_bytes("PNG")))
        entry.refresh_from_db()
        self.assertTrue(entry.cooked_photo.name.endswith(".png"))
        entry.cooked_photo.open()
        with Image.open(entry.cooked_photo) as image:
            self.assertEqual(image.format, "PNG")
        entry.cooked_photo.delete(save=True)

    def test_metadata_is_dropped_and_the_hash_is_of_the_stored_file(self):
        import hashlib
        from io import BytesIO
        from PIL import Image

        buffer = BytesIO()
        secret = b"GPS 53.3498 N, -6.2603 W - the chef's home address"
        Image.new("RGB", (64, 48), (10, 20, 30)).save(
            buffer, format="JPEG", comment=secret)
        raw = buffer.getvalue()
        self.assertIn(secret, raw, "the fixture itself has no metadata to drop")

        entry = self._submit(self._upload("dish.jpg", raw))
        entry.refresh_from_db()
        entry.cooked_photo.open()
        stored = entry.cooked_photo.read()
        self.assertNotIn(secret, stored, "the uploader's metadata was stored")
        self.assertNotEqual(hashlib.sha256(raw).hexdigest(), entry.photo_hash,
                            "the hash is of the upload, not of what was stored")
        self.assertEqual(hashlib.sha256(stored).hexdigest(), entry.photo_hash)
        entry.cooked_photo.delete(save=True)


