class TwoUploadsOfOneDishLeaveOnePhotoTests(TransactionTestCase):
    """T06, Owner brief 2026-08-12 - the first cooked photo is the evidence.

    F69 gave submit_cooked_photo the battle lock. That serialises a moderator
    cancelling the battle against an upload, and it does NOT serialise two
    uploads from the same chef - two tabs, or one impatient double-submit. The
    "have you already sent one?" check was made on an entry read BEFORE the
    transaction opened, so both requests saw an empty photo and the second
    silently replaced the evidence a moderator may already have been looking
    at, taking the moderation state and the hash with it.
    """

    def _jpeg(self, colour):
        from io import BytesIO
        from PIL import Image
        buffer = BytesIO()
        Image.new("RGB", (48, 32), colour).save(buffer, format="JPEG")
        return buffer.getvalue()

    def _upload(self, name, colour):
        from django.core.files.uploadedfile import SimpleUploadedFile
        return SimpleUploadedFile(name, self._jpeg(colour), content_type="image/jpeg")

    def setUp(self):
        User = get_user_model()
        self.chef = RecipeAuthor.objects.create(
            user=User.objects.create_user("t06-ch", password="pw"),
            name="T06 Chef", slug="t06-ch")
        self.rival = RecipeAuthor.objects.create(
            user=User.objects.create_user("t06-op", password="pw"),
            name="T06 Rival", slug="t06-op")
        ChefBattleProfile.objects.create(author=self.chef)
        ChefBattleProfile.objects.create(author=self.rival)
        now = timezone.now()
        self.battle = Battle.objects.create(
            challenger=self.chef, opponent=self.rival, theme="T06",
            status=Battle.Status.COOKING, start_time=now,
            submission_deadline=now + timezone.timedelta(days=2),
            voting_deadline=now + timezone.timedelta(days=4),
            end_time=now + timezone.timedelta(days=5),
        )
        BattleEntry.objects.create(battle=self.battle, author=self.chef)

    def test_two_simultaneous_uploads_leave_one_photo_and_one_honest_error(self):
        import threading
        import time
        from unittest import mock
        from django.db import connections
        from chef_battle import services
        from chef_battle.services import submit_cooked_photo

        start = threading.Barrier(2)
        results, refusals, errors = [], [], []

        # The window is real but narrow: both requests read the entry, then
        # spend time decoding and re-encoding the image before they open their
        # transaction. Widening THAT step - not the code under test - is what
        # makes the interleaving happen every run instead of one in twenty.
        real_normalise = services.normalise_uploaded_image

        def slow_normalise(*args, **kwargs):
            result = real_normalise(*args, **kwargs)
            time.sleep(0.3)
            return result

        def upload(colour, name):
            try:
                start.wait(timeout=10)
                results.append(submit_cooked_photo(
                    battle=self.battle, author=self.chef,
                    photo=self._upload(name, colour), real_photo_confirmed=True))
            except ValueError as refusal:
                refusals.append(str(refusal))
            except Exception as exc:
                errors.append(exc)
            finally:
                connections.close_all()

        threads = [
            threading.Thread(target=upload, args=((10, 200, 10), "first.jpg")),
            threading.Thread(target=upload, args=((200, 10, 10), "second.jpg")),
        ]
        with mock.patch.object(services, "normalise_uploaded_image", slow_normalise):
            for thread in threads:
                thread.start()
            for thread in threads:
                thread.join(timeout=30)

        self.assertEqual(errors, [], "a race must not surface as a 500")
        self.assertEqual(len(results), 1, "both uploads were accepted")
        self.assertEqual(len(refusals), 1)
        self.assertIn("already submitted", refusals[0])

        entry = BattleEntry.objects.get(battle=self.battle, author=self.chef)
        self.assertTrue(entry.cooked_photo)
        self.assertEqual(entry.cooked_photo.name, results[0].cooked_photo.name,
                         "the stored photo is not the one the winner submitted")

    def test_the_hash_and_the_moderation_state_belong_to_the_stored_file(self):
        import hashlib
        from chef_battle.services import submit_cooked_photo

        entry = submit_cooked_photo(
            battle=self.battle, author=self.chef,
            photo=self._upload("dish.jpg", (40, 80, 120)), real_photo_confirmed=True)
        entry.refresh_from_db()
        entry.cooked_photo.open()
        stored = entry.cooked_photo.read()
        self.assertEqual(hashlib.sha256(stored).hexdigest(), entry.photo_hash)
        self.assertEqual(entry.moderation_status, BattleEntry.ModerationStatus.PENDING)

    def test_a_cancellation_that_commits_first_wins_and_no_photo_is_stored(self):
        """The card's own wording: a cancellation committed first must win and
        refuse the stale upload. Two connections, a barrier, and the canceller
        holding the battle row while the upload waits for it."""
        import threading
        import time
        from django.db import connections, transaction
        from chef_battle.services import submit_cooked_photo

        start = threading.Barrier(2)
        refusals, errors, stored = [], [], []

        def cancel():
            try:
                start.wait(timeout=10)
                with transaction.atomic():
                    locked = Battle.objects.select_for_update().get(pk=self.battle.pk)
                    time.sleep(0.4)
                    locked.status = Battle.Status.CANCELLED
                    locked.save(update_fields=["status", "updated_at"])
            except Exception as exc:
                errors.append(exc)
            finally:
                connections.close_all()

        def upload():
            try:
                start.wait(timeout=10)
                time.sleep(0.1)
                stored.append(submit_cooked_photo(
                    battle=self.battle, author=self.chef,
                    photo=self._upload("late.jpg", (7, 7, 7)),
                    real_photo_confirmed=True))
            except ValueError as refusal:
                refusals.append(str(refusal))
            except Exception as exc:
                errors.append(exc)
            finally:
                connections.close_all()

        threads = [threading.Thread(target=cancel), threading.Thread(target=upload)]
        for thread in threads:
            thread.start()
        for thread in threads:
            thread.join(timeout=30)

        self.assertEqual(errors, [])
        self.assertEqual(stored, [], "a cancelled battle accepted a photo")
        self.assertEqual(len(refusals), 1)
        self.assertIn("COOKING", refusals[0])
        entry = BattleEntry.objects.get(battle=self.battle, author=self.chef)
        self.assertFalse(entry.cooked_photo)
        self.assertEqual(entry.photo_hash, "")

    def test_the_battle_row_is_locked_before_the_entry_row(self):
        """Order is the whole deadlock guarantee, so it is asserted rather than
        described: every other function in this phase takes the battle first."""
        from django.db import connection
        from django.test.utils import CaptureQueriesContext
        from chef_battle.services import submit_cooked_photo

        with CaptureQueriesContext(connection) as captured:
            submit_cooked_photo(
                battle=self.battle, author=self.chef,
                photo=self._upload("dish.jpg", (90, 90, 10)),
                real_photo_confirmed=True)

        locks = [q["sql"] for q in captured.captured_queries
                 if "FOR UPDATE" in q["sql"].upper()]
        battle_locks = [i for i, sql in enumerate(locks)
                        if "chef_battle_battle\"" in sql.lower()]
        entry_locks = [i for i, sql in enumerate(locks)
                       if "chef_battle_battleentry" in sql.lower()]
        self.assertTrue(battle_locks, "the battle row is not locked")
        self.assertTrue(entry_locks, "the entry row is not locked")
        self.assertLess(min(battle_locks), min(entry_locks),
                        "the entry was locked before the battle - deadlock order")
# T12: this is deliberately a database-level test. A service-only assertion
# cannot protect admin, cron, a management command, or a stale ORM instance.
class BattleStatusTransitionDatabaseGuardTests(TransactionTestCase):
    # RED ON MAIN, NOT MINE, FIXED ON THE WAY PAST (T19, 2026-08-15).
    # reset_sequences rewinds recipes_recipeauthor's sequence to 1 while the
    # rows created by the project's own migrations are still in the table, so
    # the first author this class creates collides on the primary key and the
    # whole class dies in setUp. Nothing here asserts an id - the tests read
    # self.battle.pk - so the reset buys nothing and costs the class.

    def setUp(self):
        if connection.vendor != "postgresql":
            self.skipTest("The production transition guard is PostgreSQL-specific.")
        User = get_user_model()
        self.a = RecipeAuthor.objects.create(
            user=User.objects.create_user("t12-a", password="pw"),
            name="T12 A", slug="t12-a",
        )
        self.b = RecipeAuthor.objects.create(
            user=User.objects.create_user("t12-b", password="pw"),
            name="T12 B", slug="t12-b",
        )
        now = timezone.now()
        self.battle = Battle.objects.create(
            challenger=self.a, opponent=self.b, theme="T12",
            status=Battle.Status.SCHEDULED, start_time=now,
            submission_deadline=now + timezone.timedelta(days=2),
            end_time=now + timezone.timedelta(days=4),
        )

    def test_a_legal_transition_is_accepted(self):
        from .state_machine import transition_battle_status

        transition_battle_status(self.battle.pk, Battle.Status.MENU_LOCKED)
        self.battle.refresh_from_db()
        self.assertEqual(self.battle.status, Battle.Status.MENU_LOCKED)

    def test_a_terminal_battle_cannot_be_resurrected_by_direct_sql(self):
        self.battle.status = Battle.Status.CANCELLED
        self.battle.save(update_fields=["status"])

        with self.assertRaises(IntegrityError), transaction.atomic():
            Battle.objects.filter(pk=self.battle.pk).update(status=Battle.Status.VOTING)

        self.battle.refresh_from_db()
        self.assertEqual(self.battle.status, Battle.Status.CANCELLED)

    def test_a_stale_orm_instance_cannot_overwrite_a_terminal_state(self):
        stale = Battle.objects.get(pk=self.battle.pk)
        self.battle.status = Battle.Status.CANCELLED
        self.battle.save(update_fields=["status"])
        stale.status = Battle.Status.ACTIVE

        with self.assertRaises(IntegrityError), transaction.atomic():
            stale.save(update_fields=["status"])

        self.battle.refresh_from_db()
        self.assertEqual(self.battle.status, Battle.Status.CANCELLED)


@override_settings(CHEF_BATTLE_ENABLED=True, OWNER_SLUG="greenbear")
class OwnerArenaAccountControlsTests(TestCase):
    def setUp(self):
        User = get_user_model()
        self.owner_user = User.objects.create_superuser(
            username="greenbear", email="owner@example.test", password="owner-pass"
        )
        self.owner, _ = RecipeAuthor.objects.update_or_create(
            slug="greenbear", defaults={"user": self.owner_user, "name": "GreenBear"}
        )
        self.target_user = User.objects.create_user(
            username="target-chef", email="target@example.test", password="target-pass"
        )
        self.target = RecipeAuthor.objects.create(
            user=self.target_user, name="Target Chef", slug="target-chef", bio="personal biography"
        )
        ChefBattleProfile.objects.update_or_create(
            author=self.owner, defaults={"enrolled_at": timezone.now()}
        )
        ChefBattleProfile.objects.create(author=self.target, enrolled_at=timezone.now())
        self.action_url = reverse("chef_battle:owner_arena_account_action")

    def _until(self):
        return (timezone.now() + timezone.timedelta(hours=2)).strftime("%Y-%m-%dT%H:%M")

    def test_only_owner_sees_controls_and_cannot_target_self(self):
        self.client.force_login(self.owner_user)
        response = self.client.get(reverse("chef_battle:arena"))
        self.assertContains(response, "Delete Account")
        response = self.client.post(self.action_url, {
            "chef_slug": "greenbear", "action": "mute", "until": self._until(),
        })
        self.assertEqual(response.status_code, 404)

        self.client.force_login(self.target_user)
        response = self.client.post(self.action_url, {
            "chef_slug": "greenbear", "action": "mute", "until": self._until(),
        })
        self.assertEqual(response.status_code, 404)

    def test_mute_prevents_arena_chat_until_deadline(self):
        now = timezone.now()
        battle = Battle.objects.create(
            challenger=self.owner,
            opponent=self.target,
            status=Battle.Status.ACTIVE,
            theme="Mute test",
            submission_deadline=now + timezone.timedelta(days=2),
            end_time=now + timezone.timedelta(days=4),
        )
        self.client.force_login(self.owner_user)
        self.client.post(self.action_url, {
            "chef_slug": self.target.slug, "action": "mute", "until": self._until(),
        })
        self.client.force_login(self.target_user)
        self.client.post(reverse("chef_battle:battle_chat_send", args=[battle.pk]), {"body": "blocked"})
        self.assertFalse(BattleChatMessage.objects.filter(battle=battle, body="blocked").exists())

    def test_block_ends_sessions_and_prevents_login_until_deadline(self):
        target_client = Client()
        self.assertTrue(target_client.login(username="target-chef", password="target-pass"))
        self.client.force_login(self.owner_user)
        self.client.post(self.action_url, {
            "chef_slug": self.target.slug, "action": "block", "until": self._until(),
        })
        self.assertNotIn("_auth_user_id", target_client.session)
        self.assertFalse(target_client.login(username="target-chef", password="target-pass"))

    def test_delete_requires_checkbox_then_removes_login_and_anonymises_history(self):
        User = get_user_model()
        self.client.force_login(self.owner_user)
        response = self.client.post(self.action_url, {
            "chef_slug": self.target.slug, "action": "delete",
        })
        self.assertEqual(response.status_code, 302)
        self.assertTrue(User.objects.filter(pk=self.target_user.pk).exists())

        self.client.post(self.action_url, {
            "chef_slug": self.target.slug, "action": "delete", "confirm_delete": "on",
        })
        self.assertFalse(User.objects.filter(pk=self.target_user.pk).exists())
        self.target.refresh_from_db()
        self.assertIsNone(self.target.user_id)
        self.assertEqual(self.target.name, "Deleted Chef")
        self.assertEqual(self.target.slug, f"deleted-chef-{self.target.pk}")
        self.assertEqual(self.target.bio, "")
        self.assertTrue(LedgerEvent.objects.filter(
            event_type=LedgerEvent.EventType.ADMIN_NOTE,
            target=self.target,
            payload__action="account_deleted_and_anonymised",
        ).exists())


@override_settings(SECURE_SSL_REDIRECT=False, CHEF_BATTLE_ENABLED=True)
class ChallengeAcceptanceOpensPreparationWindowTests(TestCase):
    """T19, Owner 2026-08-15.

    Accepting a challenge opens FORTY-EIGHT HOURS of preparation - recipes
    created and uploaded, ingredients bought, products and workplace prepared,
    the two hidden blocks placed - and nothing runs before that acceptance.

    Before this, accept_challenge set start_time to `proposed_start_time or
    now`, so a challenge carrying no proposed time started the fight the
    instant it was accepted. The 48 hours already in the code is
    submission_deadline = start_time + 48h, the window AFTER the start, and
    the two were being read as the same rule.
    """

    def setUp(self):
        User = get_user_model()
        self.user_a = User.objects.create_user(username="prep-a", password="pw")
        self.user_b = User.objects.create_user(username="prep-b", password="pw")
        self.chef_a = RecipeAuthor.objects.create(user=self.user_a, name="Prep A", slug="prep-a")
        self.chef_b = RecipeAuthor.objects.create(user=self.user_b, name="Prep B", slug="prep-b")

    def _challenge(self, **kwargs):
        return BattleChallenge.objects.create(
            challenger=self.chef_a,
            opponent=self.chef_b,
            theme="Preparation window",
            expires_at=timezone.now() + timezone.timedelta(hours=12),
            **kwargs,
        )

    def test_acceptance_with_no_proposed_time_schedules_the_start_48_hours_out(self):
        before = timezone.now()

        battle = accept_challenge(self._challenge())

        window = battle.start_time - before
        self.assertGreaterEqual(window, timezone.timedelta(hours=47, minutes=59))
        self.assertLessEqual(window, timezone.timedelta(hours=48, minutes=1))
        self.assertEqual(battle.status, Battle.Status.SCHEDULED)

    def test_a_proposed_time_inside_the_window_cannot_shorten_it(self):
        """The challenger asking for an earlier slot is asking the pair to cook
        with no preparation. Pressing Ready is the sanctioned way to start
        sooner, and it belongs to the two chefs rather than to the challenger."""
        before = timezone.now()

        battle = accept_challenge(
            self._challenge(proposed_start_time=before + timezone.timedelta(hours=2))
        )

        self.assertGreaterEqual(
            battle.start_time - before, timezone.timedelta(hours=47, minutes=59)
        )

    def test_a_later_proposed_time_is_honoured(self):
        proposed = timezone.now() + timezone.timedelta(days=5)

        battle = accept_challenge(self._challenge(proposed_start_time=proposed))

        self.assertEqual(battle.start_time, proposed)

    def test_the_deadlines_keep_their_offsets_from_the_start(self):
        """The preparation window must not be mistaken for the submission
        window: both exist, and they measure different things."""
        battle = accept_challenge(self._challenge())

        self.assertEqual(
            battle.submission_deadline - battle.start_time, timezone.timedelta(hours=48)
        )
        self.assertEqual(
            battle.voting_deadline - battle.submission_deadline, timezone.timedelta(days=2)
        )
        self.assertEqual(battle.end_time, battle.voting_deadline)

    def test_nothing_starts_before_the_challenge_is_accepted(self):
        challenge = self._challenge()

        self.assertIsNone(challenge.accepted_at)
        self.assertFalse(Battle.objects.filter(challenge=challenge).exists())


@override_settings(SECURE_SSL_REDIRECT=False, CHEF_BATTLE_ENABLED=True)
class ChallengeCarriesItsTaskTests(TestCase):
    """T19: a challenge says what is being fought over - a contest of one of
    the CHALLENGED chef's existing recipes, or a completely new one.

    This is not theme_recipe, which is the challenger's own dish and becomes
    his entry on accept; the two were being read as the same field, so the
    task the Owner describes had no representation at all.
    """

    def setUp(self):
        from recipes.models import Recipe

        User = get_user_model()
        self.user_a = User.objects.create_user(username="task-a", password="pw")
        self.user_b = User.objects.create_user(username="task-b", password="pw")
        self.user_c = User.objects.create_user(username="task-c", password="pw")
        self.chef_a = RecipeAuthor.objects.create(user=self.user_a, name="Task A", slug="task-a")
        self.chef_b = RecipeAuthor.objects.create(user=self.user_b, name="Task B", slug="task-b")
        self.chef_c = RecipeAuthor.objects.create(user=self.user_c, name="Task C", slug="task-c")
        self.own_recipe = Recipe.objects.create(
            title="My dish", slug="task-my-dish", author=self.chef_a,
            ingredients="lamb", method="Cook.", status=Recipe.Status.APPROVED,
        )
        self.their_recipe = Recipe.objects.create(
            title="Their dish", slug="task-their-dish", author=self.chef_b,
            ingredients="beef", method="Cook.", status=Recipe.Status.APPROVED,
        )
        self.stranger_recipe = Recipe.objects.create(
            title="Stranger dish", slug="task-stranger-dish", author=self.chef_c,
            ingredients="fish", method="Cook.", status=Recipe.Status.APPROVED,
        )

    def _form(self, **kwargs):
        from .forms import BattleChallengeForm

        return BattleChallengeForm(**kwargs)

    def _data(self, **overrides):
        data = {
            "opponent": self.chef_b.pk,
            "task_kind": BattleChallenge.TaskKind.NEW_RECIPE,
            "theme_recipe": self.own_recipe.pk,
            "theme": "Best modern Irish lamb",
            "battle_type": BattleChallenge.BattleType.PHOTO,
            "message": "New recipe, both of us from scratch.",
        }
        data.update(overrides)
        return data

    def test_a_new_recipe_challenge_is_the_default_and_needs_no_contested_recipe(self):
        form = self._form(data=self._data(), challenger=self.chef_a)

        self.assertTrue(form.is_valid(), form.errors)
        challenge = form.save()
        self.assertEqual(challenge.task_kind, BattleChallenge.TaskKind.NEW_RECIPE)
        self.assertIsNone(challenge.contested_recipe)

    def test_contesting_a_recipe_records_which_one(self):
        form = self._form(
            data=self._data(
                task_kind=BattleChallenge.TaskKind.CONTEST_RECIPE,
                contested_recipe=self.their_recipe.pk,
            ),
            challenger=self.chef_a,
        )

        self.assertTrue(form.is_valid(), form.errors)
        challenge = form.save()
        self.assertEqual(challenge.contested_recipe, self.their_recipe)

    def test_contesting_without_naming_a_recipe_is_refused(self):
        form = self._form(
            data=self._data(task_kind=BattleChallenge.TaskKind.CONTEST_RECIPE),
            challenger=self.chef_a,
        )

        self.assertFalse(form.is_valid())
        self.assertIn("contested_recipe", form.errors)

    def test_the_contested_recipe_must_belong_to_the_chef_being_challenged(self):
        form = self._form(
            data=self._data(
                task_kind=BattleChallenge.TaskKind.CONTEST_RECIPE,
                contested_recipe=self.stranger_recipe.pk,
            ),
            challenger=self.chef_a,
        )

        self.assertFalse(form.is_valid())
        self.assertIn("contested_recipe", form.errors)

    def test_a_new_recipe_challenge_cannot_also_contest_one(self):
        form = self._form(
            data=self._data(contested_recipe=self.their_recipe.pk),
            challenger=self.chef_a,
        )

        self.assertFalse(form.is_valid())
        self.assertIn("contested_recipe", form.errors)

    def test_the_challenger_cannot_contest_his_own_recipe(self):
        offered = self._form(challenger=self.chef_a).fields["contested_recipe"].queryset

        self.assertNotIn(self.own_recipe, offered)
        self.assertIn(self.their_recipe, offered)

    def test_the_challenged_chef_sees_the_task_before_accepting(self):
        challenge = BattleChallenge.objects.create(
            challenger=self.chef_a,
            opponent=self.chef_b,
            theme="Contested",
            task_kind=BattleChallenge.TaskKind.CONTEST_RECIPE,
            contested_recipe=self.their_recipe,
            message="I am contesting this one.",
            expires_at=timezone.now() + timezone.timedelta(hours=12),
        )
        self.client.force_login(self.user_b)

        response = self.client.get(reverse("chef_battle:challenge_list"))

        self.assertContains(response, "Contesting a recipe of the chef being challenged")
        self.assertContains(response, self.their_recipe.title)
        self.assertContains(response, challenge.message)


@override_settings(SECURE_SSL_REDIRECT=False, CHEF_BATTLE_ENABLED=True)
class NextBattleStripCarriesItsStartTimeTests(TestCase):
    """T21, Owner 2026-08-15: the pill's distance from the starting position is
    its remaining time, so the row itself has to carry the time.

    The placement is arena_deck.js's job and is measured in the browser, not
    here. What a Python test can hold is the contract underneath it: the row
    that moves is the <li>, and the time it moves by is on that <li> in a form
    Date.parse can read. Without it every pill silently falls back to zero and
    the board is flat again - the exact failure this card was written to end.
    """

    def setUp(self):
        User = get_user_model()
        self.staff = User.objects.create_user(
            username="t21-staff", password="pw", is_staff=True, is_superuser=True)
        self.chef_a = RecipeAuthor.objects.create(
            user=User.objects.create_user(username="t21-a", password="pw"),
            name="Strip Chef A", slug="t21-a")
        self.chef_b = RecipeAuthor.objects.create(
            user=User.objects.create_user(username="t21-b", password="pw"),
            name="Strip Chef B", slug="t21-b")
        self.start = timezone.now() + timezone.timedelta(hours=30)
        self.battle = Battle.objects.create(
            challenger=self.chef_a, opponent=self.chef_b, theme="Strip theme",
            status=Battle.Status.SCHEDULED, start_time=self.start,
            submission_deadline=self.start + timezone.timedelta(hours=48),
            voting_deadline=self.start + timezone.timedelta(days=4),
            end_time=self.start + timezone.timedelta(days=4),
        )

    def test_the_row_carries_a_parseable_start_time(self):
        self.client.force_login(self.staff)

        response = self.client.get(reverse("chef_battle:arena"))

        self.assertEqual(response.status_code, 200)
        html = response.content.decode()
        self.assertIn('<li data-start-time="%s"' % self.start.isoformat(), html)

    def test_the_payload_start_time_is_the_same_string_the_row_uses(self):
        """The poll replaces these rows wholesale, so the two paths have to
        agree on the format or the board jumps on the first tick."""
        from .views import _build_arena_payload

        payload = _build_arena_payload()

        self.assertEqual(payload["upcoming"][0]["start_time"], self.start.isoformat())


@override_settings(CHEF_BATTLE_ENABLED=True)
class ArenaEndpointsActuallyEnforceTheirRateLimitTests(TestCase):
    """AA5, 2026-08-15 - found by the full Arena audit the Owner ordered.

    Two endpoints, two faults, and the first is the worst kind:

    arena_take_seat carried @ratelimit(block=False) from the day it shipped.
    block=False means the decorator SETS request.limited and leaves the
    decision to the view - and the view never read it. So the limit did
    nothing at all while looking, to any reviewer scrolling past, exactly like
    a limit. arena_state does this correctly twenty lines away, which is what
    makes it a mistake rather than a policy.

    arena_ping had no limit at all, and writes to ChefBattleProfile and claims
    a seat on every call.

    arena_battle_popup had the same fault and was fixed with them, but that
    endpoint no longer exists: AA6 removed the whole popup surface once AA4
    left it with no caller, so its two tests went with it.

    Each test drives the endpoint past its own limit and asserts the refusal,
    then asserts the SHAPE of the refusal, because a JSON endpoint that starts
    returning HTML on refusal breaks the caller as surely as no limit at all.
    """

    def setUp(self):
        from .models import ChefBattleProfile

        User = get_user_model()
        self.user = User.objects.create_user("aa5-viewer", password="pw")
        self.author = RecipeAuthor.objects.create(
            user=self.user, name="AA5 Viewer", slug="aa5-viewer")
        ChefBattleProfile.objects.create(author=self.author)
        self.client.force_login(self.user)

    def tearDown(self):
        from django.core.cache import cache
        cache.clear()          # the limiter's counters live here

    def _drive(self, method, url, limit, payload=None):
        """Call an endpoint limit+1 times and return the last response."""
        call = getattr(self.client, method)
        last = None
        for _ in range(limit + 1):
            last = call(url, payload or {})
        return last

    def test_take_seat_refuses_past_its_limit_instead_of_ignoring_it(self):
        from django.core.cache import cache
        cache.clear()

        response = self._drive("post", reverse("chef_battle:arena_take_seat"), 60)
        self.assertEqual(
            response.status_code, 429,
            "arena_take_seat still ignores request.limited - the decorator is decorative")
        self.assertEqual(response.json()["error"], "rate_limited")

    def test_ping_refuses_past_its_limit(self):
        from django.core.cache import cache
        cache.clear()

        response = self._drive("post", reverse("chef_battle:arena_ping"), 60)
        self.assertEqual(response.status_code, 429)
        self.assertEqual(response.json()["error"], "rate_limited")

    def test_an_ordinary_viewer_is_never_limited_at_the_real_cadence(self):
        """The renderer pings every 20s and polls state every 10s. A limit that
        a real browser trips is a bug, so the honest cadence is asserted, not
        assumed: a minute of pinging is three calls, not sixty."""
        from django.core.cache import cache
        cache.clear()

        for _ in range(3):
            response = self.client.post(reverse("chef_battle:arena_ping"))
            self.assertEqual(response.status_code, 200)



class ChefPotentialIsIndicativeNotExactTests(TestCase):
    """AA7, 2026-08-15. ARENA_HALL_PLAN A1 asks for "an *approximate* attack
    and defence potential (derived from artifacts, but the artifacts
    themselves are NOT shown - only indicative info)", and its own open
    question 3 offers a range, stars or a rounded number.

    The arena shipped the exact aggregate and put a "~" in front of it. For a
    small loadout an exact sum is not indicative at all: it can be decomposed
    back into the very artifact list the plan says must stay hidden. The band
    is computed server-side, so the precise figure never leaves it.
    """

    def test_a_value_becomes_the_band_it_falls_in(self):
        from .views import _potential_band

        self.assertEqual(_potential_band(47), "40–60")
        self.assertEqual(_potential_band(40), "40–60")
        self.assertEqual(_potential_band(59), "40–60")
        self.assertEqual(_potential_band(60), "60–80")
        self.assertEqual(_potential_band(1), "0–20")

    def test_nothing_at_all_is_an_empty_string_not_a_zero_band(self):
        """"0–20" would advertise a floor the chef has not earned."""
        from .views import _potential_band

        self.assertEqual(_potential_band(0), "")
        self.assertEqual(_potential_band(None), "")

    def test_the_payload_carries_the_band_and_not_the_exact_sum(self):
        from .models import Artifact, ChefArtifact, ChefBattleProfile
        from .views import _build_arena_payload

        User = get_user_model()
        author = RecipeAuthor.objects.create(
            user=User.objects.create_user("aa7-chef", password="pw"),
            name="AA7 Chef", slug="aa7-chef")
        ChefBattleProfile.objects.create(
            author=author, enrolled_at=timezone.now(), last_seen_at=timezone.now())
        blade = Artifact.objects.create(
            name="AA7 Blade", rarity=Artifact.Rarity.EPIC,
            effect_type="attack", effect_value=47, token_cost=10)
        ChefArtifact.objects.create(
            chef=author, artifact=blade, status=ChefArtifact.Status.AVAILABLE)

        chefs = [c for cells in _build_arena_payload()["rings"].values() for c in cells]
        mine = next(c for c in chefs if c["slug"] == "aa7-chef")

        self.assertEqual(mine["atk_band"], "40–60")
        self.assertNotIn("atk", mine, "the exact aggregate must not be published")
        self.assertNotIn("def", mine)
        self.assertEqual(mine["def_band"], "")

    def test_the_renderer_reads_the_band_and_no_longer_the_raw_number(self):
        from pathlib import Path
        from django.conf import settings as django_settings

        source = (Path(django_settings.BASE_DIR) / "static" / "js"
                  / "arena_render.js").read_text(encoding="utf-8")
        self.assertIn("chef.atk_band", source)
        self.assertNotIn("chef.atk ||", source)
        self.assertNotIn("chef['def'] ||", source)


@override_settings(CHEF_BATTLE_ENABLED=True)
class EnrollingAsAChefGivesUpTheSpectatorSeatTests(TestCase):
    """AA8, 2026-08-15: a chef stands in their rank ring, not in the stands.

    _ensure_spectator_seat() refuses an enrolled author, so from the moment of
    enrolment no new seat is taken - but nothing released the one the viewer
    was already holding. It sat occupied until the 180-second lapse swept it:
    a front-row seat held by somebody now on the floor, in a hall whose
    capacity is a fixed 114.
    """

    def setUp(self):
        from .models import ChefBattleProfile

        User = get_user_model()
        self.user = User.objects.create_user("aa8-viewer", password="pw")
        self.author = RecipeAuthor.objects.create(
            user=self.user, name="AA8 Viewer", slug="aa8-viewer")
        ChefBattleProfile.objects.create(author=self.author, last_seen_at=timezone.now())
        self.client.force_login(self.user)

    def test_the_seat_is_released_the_moment_the_viewer_enrols(self):
        from .arena_seating import claim_seat, get_active_seat

        seat = claim_seat(self.author)
        self.assertIsNotNone(get_active_seat(self.author))

        response = self.client.post(reverse("chef_battle:chef_enroll"),
                                    {"confirm_age": "1", "confirm_rules": "1"})
        self.assertEqual(response.status_code, 302)

        self.assertIsNone(get_active_seat(self.author),
                          "the new chef is still holding a seat in the stands")
        seat.refresh_from_db()
        self.assertIsNotNone(seat.released_at)


class OwnerIsPresentButOutsideTheCompetitionTests(TestCase):
    """T22, Owner ruling: GreenBear stands on the Arena and may wear a clan,
    but he is outside the competition.

    Half of this contract has always been in - is_immortal() stops the game
    TAKING anything from his account at the penalty, the rank demotion and the
    refusal charge. The other half was never built: nothing stopped the game
    COUNTING him. He appeared in the opponent dropdown, and he stood in a
    public ladder keyed to WINS while his rank is hand-set by migrations
    0020/0025 - a place no battle earned.
    """

    def setUp(self):
        from .models import ChefBattleProfile

        User = get_user_model()
        # The Owner's author already exists - migration 0020 creates it and
        # 0025 gives it the infinite balance. Take it rather than creating a
        # second one; AGENTS.md section 18 means this row is never invented.
        self.owner = RecipeAuthor.objects.get(slug=settings.OWNER_SLUG)
        self.owner_profile, _ = ChefBattleProfile.objects.get_or_create(
            author=self.owner)
        ChefBattleProfile.objects.filter(pk=self.owner_profile.pk).update(
            enrolled_at=timezone.now(), rating=9999, wins=0, seasonal_score=500)
        self.owner_profile.refresh_from_db()

        self.chef_user = User.objects.create_user("t22-chef", password="pw")
        self.chef = RecipeAuthor.objects.create(
            user=self.chef_user, name="T22 Chef", slug="t22-chef")
        self.chef_profile = ChefBattleProfile.objects.create(
            author=self.chef, enrolled_at=timezone.now(),
            rating=10, wins=1, seasonal_score=5,
        )

    def test_he_is_absent_from_the_public_ladder(self):
        from .selectors import get_rankings

        slugs = [p.author.slug for p in get_rankings()]
        self.assertIn("t22-chef", slugs, "the ordinary chef vanished - the filter is too wide")
        self.assertNotIn(settings.OWNER_SLUG, slugs)

    def test_he_is_absent_from_the_top_profiles_panel(self):
        from .selectors import get_top_profiles

        slugs = [p.author.slug for p in get_top_profiles()]
        self.assertIn("t22-chef", slugs)
        self.assertNotIn(settings.OWNER_SLUG, slugs)

    def test_his_rating_of_9999_does_not_head_the_ladder(self):
        """The specific failure this card exists to stop: ordered by -rating,
        a hand-set 9999 puts him first on a board that means 'best chef'."""
        from .selectors import get_rankings

        top = list(get_rankings())
        self.assertTrue(top, "ladder is empty - the test proves nothing")
        self.assertNotEqual(top[0].author.slug, settings.OWNER_SLUG)

    def test_a_challenge_naming_him_is_refused_by_the_server(self):
        """Not merely hidden from the dropdown - the acceptance requires the
        refusal to survive a POST that names his pk directly."""
        from .services import check_owner_not_in_battle

        self.assertIsNotNone(check_owner_not_in_battle(self.chef, self.owner))

    def test_he_cannot_issue_a_challenge_either(self):
        """Both directions - the exclusion must not depend on which side of
        the form he lands on."""
        from .services import check_owner_not_in_battle

        self.assertIsNotNone(check_owner_not_in_battle(self.owner, self.chef))

    def test_two_ordinary_chefs_are_still_allowed_to_fight(self):
        """The guard must refuse him, not everybody."""
        from .services import check_owner_not_in_battle

        other_user = get_user_model().objects.create_user("t22-other", password="pw")
        other = RecipeAuthor.objects.create(
            user=other_user, name="Other", slug="t22-other")
        self.assertIsNone(check_owner_not_in_battle(self.chef, other))

    def test_he_is_not_offered_in_the_opponent_dropdown(self):
        from .forms import BattleChallengeForm

        form = BattleChallengeForm(challenger=self.chef)
        offered = [a.slug for a in form.fields["opponent"].queryset]
        self.assertNotIn(settings.OWNER_SLUG, offered)

    def test_he_takes_no_season_standing(self):
        """A season is the most permanent competitive record the game keeps."""
        from .views import season_leaderboard  # noqa: F401  (import proves the view loads)
        from .selectors import _uncompeting_slugs
        from .models import ChefBattleProfile

        ranked = (
            ChefBattleProfile.objects.filter(seasonal_score__gt=0)
            .exclude(author__slug__in=_uncompeting_slugs())
        )
        self.assertNotIn(settings.OWNER_SLUG,
                         [p.author.slug for p in ranked])

    def test_the_protective_half_is_untouched(self):
        """This card ADDS an exclusion; it does not trade the protection away.
        is_immortal() must still answer True for him afterwards."""
        from .services import is_immortal

        self.assertTrue(is_immortal(self.owner_profile))
        self.assertFalse(is_immortal(self.chef_profile))

    def test_he_does_not_hold_the_arena_centre_crown(self):
        """T22's original enumeration covered the ladders, the ladder panel,
        the dropdown and season standings, but not _arena_center()'s own
        crown query - a SEPARATE read path from get_crown_streak (which
        already excludes him). Found 2026-08-16 while verifying T28: his
        crown_until is set a decade out, so without this exclusion the arena
        centre stage shows him as Crown holder while the adjacent Crown
        Streak metric (already fixed) shows 0 for the same reign - a visible
        self-contradiction on one page."""
        from .views import _arena_center

        ChefBattleProfile.objects.filter(pk=self.owner_profile.pk).update(
            crown_until=timezone.now() + timezone.timedelta(days=3650))
        self.assertEqual(_arena_center(active_battle=None)["type"], "empty")

    def test_he_does_not_hold_the_crown_holder_page_either(self):
        """G13's dedicated 'who wears the crown' page had the same gap as the
        arena centre - a second, independent read path onto the same field."""
        from django.test import Client

        ChefBattleProfile.objects.filter(pk=self.owner_profile.pk).update(
            crown_until=timezone.now() + timezone.timedelta(days=3650))
        with override_settings(CHEF_BATTLE_ENABLED=True):
            response = Client().get(reverse("chef_battle:crown_holder"))
        self.assertNotIn(self.owner.name.encode(), response.content)

    def test_the_master_console_hides_his_crown_too_if_it_is_ever_reset(self):
        """Owner ruling, 2026-08-16, reversing the first instinct: the console
        is his mirror of truth, but a hand-set crown_until on his own account
        is not truth - T22 already makes it structurally impossible for him
        to win a real one (check_owner_not_in_battle refuses every challenge
        naming him), so any value there is leftover test fixture, never a
        real event. If it is ever set again by mistake - exactly as the
        production 2036 date was - the console must not surface it either.
        Everything else the console reports (real chefs, real counts, real
        battles) is untouched and remains fully unfiltered."""
        from .selectors import get_master_state

        ChefBattleProfile.objects.filter(pk=self.owner_profile.pk).update(
            crown_until=timezone.now() + timezone.timedelta(days=3650))
        state = get_master_state()
        self.assertIsNone(state["arena"]["crown_holder"])


class ClanWearsItsTopChefsAuraTests(TestCase):
    """Owner's rule, 2026-08-16: a clan's aura is the aura of its most senior
    chef.

    Ranked, not scored - get_clan_top_contributors() next door orders by season
    points, which changes every time somebody cooks. A clan's face should not
    flicker week to week.
    """

    def setUp(self):
        from .models import ChefBattleProfile, Clan, ClanMembership

        User = get_user_model()
        self.clan = Clan.objects.create(
            founder=self._author("clan-founder", "Founder"),
            name="Aura Clan", slug="aura-clan",
            moderation_status=Clan.Moderation.APPROVED,
        )
        self._join(self.clan.founder, ClanMembership.Role.FOUNDER)

    def _author(self, slug, name):
        User = get_user_model()
        user = User.objects.create_user(slug, password="pw")
        return RecipeAuthor.objects.create(user=user, name=name, slug=slug)

    def _join(self, author, role=None):
        from .models import ClanMembership
        return ClanMembership.objects.create(
            clan=self.clan, chef=author,
            role=role or ClanMembership.Role.MEMBER,
            status=ClanMembership.Status.ACTIVE,
        )

    def _profile(self, author, rank, rating=0):
        from .models import ChefBattleProfile
        return ChefBattleProfile.objects.create(
            author=author, rank=rank, rating=rating, enrolled_at=timezone.now())

    def test_the_highest_ranked_member_carries_the_aura(self):
        from .clan_selectors import get_clan_top_chef
        from .models import ChefBattleProfile

        self._profile(self.clan.founder, ChefBattleProfile.Rank.PREP_COOK)
        star = self._author("clan-star", "Star")
        self._join(star)
        self._profile(star, ChefBattleProfile.Rank.HEAD_CHEF)

        top = get_clan_top_chef(self.clan)
        self.assertEqual(top.author.slug, "clan-star",
                         "the founder outranked a Head Chef - ordering is wrong")

    def test_rating_breaks_a_rank_tie(self):
        from .clan_selectors import get_clan_top_chef
        from .models import ChefBattleProfile

        self._profile(self.clan.founder, ChefBattleProfile.Rank.SOUS_CHEF, rating=10)
        rival = self._author("clan-rival", "Rival")
        self._join(rival)
        self._profile(rival, ChefBattleProfile.Rank.SOUS_CHEF, rating=99)

        self.assertEqual(get_clan_top_chef(self.clan).author.slug, "clan-rival")

    def test_the_owner_never_becomes_the_clans_face(self):
        """His rank is hand-set. Letting him wear the clan's aura would hand any
        clan he joins the best aura on the site for nothing - which is exactly
        why his own aura is a separate gold crown instead."""
        from .clan_selectors import get_clan_top_chef
        from .models import ChefBattleProfile

        self._profile(self.clan.founder, ChefBattleProfile.Rank.PREP_COOK)
        owner = RecipeAuthor.objects.get(slug=settings.OWNER_SLUG)
        self._join(owner)
        ChefBattleProfile.objects.update_or_create(
            author=owner,
            defaults={"rank": ChefBattleProfile.Rank.CULINARY_MASTER,
                      "rating": 9999, "enrolled_at": timezone.now()},
        )

        top = get_clan_top_chef(self.clan)
        self.assertIsNotNone(top)
        self.assertNotEqual(top.author.slug, settings.OWNER_SLUG)
        self.assertEqual(top.author.slug, "clan-founder")

    def test_a_clan_of_unenrolled_members_has_no_aura(self):
        from .clan_selectors import get_clan_top_chef

        self.assertIsNone(get_clan_top_chef(self.clan),
                          "no ChefBattleProfile exists - there is no aura to wear")


class RankMapsToTheOctagonsOwnRingNumberTests(TestCase):
    """rank_to_ring_index() is the INVERSE of _RANK_ORDER and the two are easy
    to confuse: pick the wrong one and a chef's aura comes out upside down -
    a Kitchen Porter wearing the Culinary Master's light."""

    def test_every_rank_maps_to_the_ring_geometry_actually_builds(self):
        from .selectors import get_arena_geometry, rank_to_ring_index

        rings = [r for r in get_arena_geometry()["rings"] if r.get("kind") == "rank"]
        self.assertEqual(len(rings), 8)
        for ring in rings:
            self.assertEqual(
                rank_to_ring_index(ring["key"]), ring["index"],
                f"{ring['key']} maps to ring {rank_to_ring_index(ring['key'])} "
                f"but geometry puts it on ring {ring['index']}",
            )

    def test_the_master_is_ring_one_and_the_porter_is_ring_eight(self):
        from .models import ChefBattleProfile
        from .selectors import rank_to_ring_index

        self.assertEqual(rank_to_ring_index(ChefBattleProfile.Rank.CULINARY_MASTER), 1)
        self.assertEqual(rank_to_ring_index(ChefBattleProfile.Rank.KITCHEN_PORTER), 8)

    def test_an_unknown_rank_loses_its_aura_rather_than_breaking_the_page(self):
        from .selectors import rank_to_ring_index

        self.assertEqual(rank_to_ring_index("archmage"), 0)


class TheOwnerWearsACrownOnTheFloorNotARankAuraTests(TestCase):
    """His rank is hand-set to EXECUTIVE_CHEF by migrations 0020/0025. Without
    an explicit marker he renders on the arena floor as an ordinary ring-2
    chef, indistinguishable from anyone who earns that rank."""

    def test_the_payload_marks_the_owner_and_nobody_else(self):
        from .models import ChefBattleProfile
        from .views import _build_arena_payload

        owner = RecipeAuthor.objects.get(slug=settings.OWNER_SLUG)
        ChefBattleProfile.objects.update_or_create(
            author=owner,
            defaults={"rank": ChefBattleProfile.Rank.EXECUTIVE_CHEF,
                      "enrolled_at": timezone.now(),
                      "last_seen_at": timezone.now()},
        )
        User = get_user_model()
        other_user = User.objects.create_user("crown-rival", password="pw")
        other = RecipeAuthor.objects.create(
            user=other_user, name="Rival", slug="crown-rival")
        ChefBattleProfile.objects.create(
            author=other, rank=ChefBattleProfile.Rank.EXECUTIVE_CHEF,
            enrolled_at=timezone.now(), last_seen_at=timezone.now())

        payload = _build_arena_payload()
        flags = {}
